-- The lines this pack can read, by chat type and the exact text as it arrives: the sound's
-- file name, its length in seconds, and what the voice says if that isn't the line itself.
-- Written by tools/voice/build.mjs, so don't edit it here.
local _, ns = ...

ns.Voice = "narrator"
ns.Lines = {
	say = {
		["\"Everyone settles up with me eventually,\" he'd say. Got a big laugh, every time. The keeper laughed too."] = { "89001247f914", 7.73 },
		["\"First lesson,\" she said, eating my dinner. \"Try the door.\" You'd be amazed how rich that lesson has made me, and how few people learn it."] = { "d55a46fd4071", 9.82 },
		["\"I did,\" the master said. \"Aged nine. And it hangs there for the day ye ruin something and sit down to cry about it. Look up, is all.\""] = { "3d1d2d89c219", 10.08 },
		["\"Left where the old oak used to be,\" he said. \"Right at the Hobbs place, only it's not the Hobbs place now. If you reach the river, you've gone wrong.\""] = { "a02a17b3d20f", 10.29 },
		["\"There you are,\" I said. \"Term's up.\" He looked at me for a while, a dead man sitting there chatting with him. \"It doesn't say which one,\" he said."] = { "0cdfc39b7ed4", 9.72 },
		["\"Water behind the big rock.\" \"Bad bridge, go around.\" \"Keep going, nearly there.\" Never a name."] = { "0def2dd33934", 8.39 },
		["A Skyborne I met says she woke one morning some years ago, and the wind was empty. Nobody knows why they left."] = { "1f63edc1e970", 8.1 },
		["A bard once wrote a song about me. Eleven verses. Very stirring."] = { "f0e2f95436ff", 5.28 },
		["A bear came out of the trees at a woodcutters' camp while I was there for supper. A big one, hungry, heading straight for the cook pot and the cook."] = { "8e2300c9bd4c", 8.99 },
		["A boar chased me up a rock in Durotar. I'll say this for myself: I climbed it beautifully. It was getting down that hadn't occurred to me."] = { "bd322078de9a", 9.48 },
		["A boatman took me through the Wetlands once, along the channel where you can see Grim Batol on a clear day, if you want to. He didn't."] = { "638a3765b5d8", 9.67 },
		["A boulder once came down across a path I was helping clear. I asked the earth to move it. The earth declined."] = { "8e16021d1264", 7.5 },
		["A boy fell into the canal in Stormwind, by the Trade District, where the water runs deep and fast toward the harbor. He couldn't swim. Neither could I."] = { "dccecadf2025", 10 },
		["A branch as wide as a road. Then a branch as wide as a table. Then one as wide as my hand, with a long drop on both sides, and behind me a low, soft cough."] = { "51861c810874", 13.11 },
		["A buzzard picked me out on my first day in the Badlands. It flew in lazy circles over me, sometimes landing on a rock up ahead to see how I was getting on."] = { "919b838854b5", 10.48 },
		["A caretaker, I thought. But nobody ever came or went, and I watch doors for a living. Every night, that loaf, still steaming."] = { "b9fe3d85f2c9", 9.4 },
		["A carnie at the Darkmoon Faire bet me a silver I couldn't find the pea under his three cups."] = { "3bd69407464d", 5.41 },
		["A cart of lamp oil caught fire at Thorium Point, in the Searing Gorge, right beside the crates of blasting powder. Everyone there knew what that meant."] = { "667317ba0bad", 10.08 },
		["A cart went off a bridge in Tirisfal, horse and driver and all, into deep black water. Everyone on the bank was pulling off their boots and counting how long they could hold their breath."] = { "97ca66511944", 12.04 },
		["A cook there swears she served him two breakfasts on the same day. He tipped both times. Different amounts."] = { "ce6dc5b89cbe", 7.21 },
		["A dear friend and I quarreled once, over something small. I said a thing that I shouldn't have. I decided to give it a decade, so she might cool."] = { "12151f7ba311", 10.06 },
		["A decade became a century. I rehearsed my apology beneath every moon there was. I grew very fine at it, and I carried it for three hundred years."] = { "575f73ea2502", 11.02 },
		["A dragon, she said. A real one. I told her that was a terrible idea. She asked again every hour."] = { "b63335aabd0c", 8.2 },
		["A druid at the dock told me later what that dance means. By dancing back, I had accepted the challenge. I wish I'd run sooner than I did."] = { "1394f4ff9b98", 10 },
		["A dwarf I know wrote to an orc she knows. Same day, same hour, they both sat on his knee. Same red coat. Same cookie crumb caught in the left side of the beard."] = { "9645b1c5bbc0", 11.55 },
		["A farmer at a bar once bet me a silver that his pig could outdrink me. I'd had a few already, and it seemed like easy money."] = { "85c06e27e415", 7.92 },
		["A farmer came to me in a dry year with a purse. He'd heard a shaman could bring rain. He wanted it by the end of the week, and he wanted a price."] = { "40c93e814ab7", 9.12 },
		["A farmer offered me a hot meal if I'd catch his hen. I laughed. I had just slain a bear that very week."] = { "f7b6f27c0861", 7.58 },
		["A farmer outside Goldshire swore you could bargain with kobolds. Give them a candle, he said, and they'll leave you be."] = { "61b58d9b6c7c", 8.2 },
		["A fellow in the Swamp of Sorrows sold me a mud bath. It's a real business. He's got a sign, and a tub. I paid him actual money, for mud, in that swamp."] = { "9ad55b6954ba", 12.28 },
		["A fellow traveler asked why I was still wearing the torn one. I told him the roads were too dusty. He asked if I was waiting for someone to wash them."] = { "2edd667c49c7", 8.93 },
		["A ferryman in the Riverglades let me try his pole. I pushed as hard as I could. The ferry spun in a circle in the middle of the river."] = { "cf0b5337d034", 8.99 },
		["A few winters back, in a quiet inn, a child behind me dropped a cup. Just a cup. It broke on the floor."] = { "f281fe1af872", 8.46 },
		["A flood took out a ford while a herder's boy was still halfway across with his family's goats. The water was too fast to swim and too wide to throw a rope."] = { "df8f8894dbdd", 10.24 },
		["A friend of mine told me about the Pools of Vision, down in the caves beneath Thunder Bluff. I've never gone. This is why."] = { "a73a638f105d", 8.33 },
		["A friend tried it. She danced until dawn and never saw a face. She goes back every full moon now. She says she isn't lonely anymore, and that's the strange part."] = { "b4d909c274f8", 11.81 },
		["A goat herder told me there's someone out here who sits at strangers' fires and listens to their whole story."] = { "d83ebb93137f", 6.3 },
		["A good friend of mine died on the second day. Nobody out there had done anything wrong, by what they knew."] = { "b888102aa473", 7.03 },
		["A gray figure walked the upstairs hall of my aunt's house for sixty years. Everyone had a theory. Murder, betrayal, a lost love."] = { "05aa9ae1a0d0", 9.48 },
		["A hammer of Light, right between the horns. Not to hurt him. Just to give him a moment to reconsider."] = { "1a648f8ae114", 7.03 },
		["A hammer, and a banner. There was one thing more the old man wanted. And it was the hardest to find."] = { "a59dd21da6d8", 7.63 },
		["A heel of bread. She said it was for my little friend, because it looked hungry. Then her mother shouted, and off she ran."] = { "f849467f4868", 8.88 },
		["A horse won't leave a burning barn. It goes back to its stall, because that's where it feels safe. An old carter shouted the trick at me as I ran in."] = { "b173b56e2ca8", 10.37 },
		["A hunter will buy me by hundreds a pack. What am I?"] = { "e75a3fdf8a58", 4.05 },
		["A kobold will wear me on top of its head,"] = { "c30826ca395f", 2.9 },
		["A kodo can't outrun it. Neither can you. I could feel it on my back, and I could hear the calves screaming, and then our eldest stopped dead and pulled out a flint."] = { "19f7274b44e1", 10.48 },
		["A little girl beside me had one ticket too. Together, the carnie said, we could buy one paper flower."] = { "52f527578657", 7.78 },
		["A little girl once stopped me on a farm road. She'd dragged a branch across it and sat down behind it, very stern."] = { "8c590c1064fc", 7.86 },
		["A mage in Dalaran paid me to carry a sealed crate across town. Keep it level, she said. Don't open it, and don't listen to it."] = { "dd7466343f9c", 9.17 },
		["A man in a tall hat waved to me from the gate, like he'd known I was watching all along."] = { "bb1bbfbeceb4", 5.88 },
		["A mile on, there was a second patrol. Same question, same answer. They bought two sacks and paid me not to mention them either."] = { "2bb5590b7431", 8.8 },
		["A murloc stole my net at Longshore, right off the sand, and sat there holding it. So I thought I'd try talking to it."] = { "a8604ef48612", 7.86 },
		["A neighbor of ours kept an apple tree that hadn't fruited in thirty years. Took up good ground. Everyone in Elwynn told him to cut it down."] = { "ce30a41a9935", 9.12 },
		["A nightsaber, as large as any I've seen. I jumped. I caught a vine, swung, lost it, caught another, hit a limb with my ribs, and hauled myself up, gasping."] = { "d7d31e957c87", 12.46 },
		["A notice goes up every winter: throughout Azeroth, it is the season to be jolly. My old sergeant read it to us like a battle order. Then he went to practice."] = { "872944e8e07a", 10.71 },
		["A person can lie to you all day, but their tracks can't. Show me where you've walked, and I'll tell you who you are."] = { "5bec79a09f10", 7.39 },
		["A proper bow stave has to sit for years before it's fit to work. An old bowyer I used to buy from had rafters full of them, tagged by the year."] = { "40e1249bffe0", 10.24 },
		["A proper circle has twelve marks, drawn in order, with a steady hand. I drew mine once in a wine cellar, with the door splintering behind me."] = { "9b99d9bd7f46", 9.72 },
		["A rockfall came down on a mountain road while I was walking it with a family of tinkers. Stones the size of fists, and bigger ones behind."] = { "acbc4c3a0500", 9.46 },
		["A scholar there told me the step was never broken. It was left out on purpose, by whoever built the place."] = { "5b3bb84666fe", 7.13 },
		["A sentinel finally asked what I was doing. I told her. She looked at the tree, then at me, and said that root had been there three hundred years."] = { "31bb02579457", 9.22 },
		["A shaman will carry me, waiting for death,"] = { "be6ef2b40c89", 3.4 },
		["A shaman's first totem should be carved by their own hand. It's a sacred moment. I worked on mine for a year, by firelight, in silence."] = { "357d94e67d10", 10.42 },
		["A ship broke on the skerries in the worst squall of the year, close enough that we could hear them shouting. No boat could live in that water."] = { "64d35bd022f7", 8.65 },
		["A single wheel came out of the smoke and kept going. It rolled clean across the salt. The crowd rose to its feet."] = { "ab392075cc4f", 7.55 },
		["A sluice gate jammed in a flooding tunnel, with a dozen workers on the wrong side of it. The gearbox that opens it is the size of a bread oven, and somebody had to get inside."] = { "97e63ba922e5", 11.55 },
		["A stable caught fire at a roadside inn while I was there, with nine horses inside and every one of them too frightened to come out."] = { "cb06409c425b", 7.99 },
		["A storm rolled over the plains while I was at Bloodhoof Village, and I stood out in it with an old herder. The wind flattened every blade of grass for miles."] = { "54e2572d9b29", 10.5 },
		["A stranger came to one of our burials once, and I watched his face fall. Drums, singing, somebody's cousin dancing on a table. He thought we had no respect."] = { "ff71af914b46", 11.68 },
		["A stranger sat down beside me, broke a loaf in two, and handed me the bigger half. Didn't say one word."] = { "085e9174473f", 7.92 },
		["A sweet old lady sat down at my table with her knitting. She said the dice looked ever so much fun, and would I teach her?"] = { "46b4d93afdaf", 7.86 },
		["A tinker in Ironforge sold me a self-warming coat. Little brass coils in the lining. Best purchase of my life for almost an hour."] = { "1d21099ae819", 9.46 },
		["A tracker once told me fires draw more than travelers. The things out there can't feel warmth, but they remember it."] = { "ca09341c7f6a", 7.81 },
		["A trader at Thorium Point had a grand idea. Sell ice in the Searing Gorge. Haul it from Dun Morogh, name your price. Everyone there is dying for it."] = { "081667d56ecd", 11.44 },
		["A trader in Ratchet swears there's a map of the whole world, cut into pieces, and every inn on the continent keeps one. Ask the innkeeper for the old page, he says."] = { "514cbbdc455b", 11.15 },
		["A trader in Winterspring sold me a pair of fine thick gloves. Then she pressed a second, thinner pair into my hands and told me to wear those underneath."] = { "0b111ecba5a9", 9.82 },
		["A trader's wagon got stuck in a ford in the Barrens with the river rising fast. Six of us pushing, and the wheels only sank deeper."] = { "fe88547cd4bb", 8.99 },
		["A traveler once gave me a stool she'd made on the road. She hadn't measured me first. It came up to about my knee."] = { "526c6c67832c", 8.33 },
		["A traveler, half frozen, swearing they'd been walking toward that light since they were young."] = { "a1e7606c42ab", 5.9 },
		["A very fast talker on the Ratchet docks sold me a plot of land in Durotar. Had a deed and everything. Fertile soil, he said. River view."] = { "cee7a455327a", 10.61 },
		["A village hired me once to clear something bad from their well. They paid me at the edge of town, at arm's length, and asked me to be gone by dark."] = { "1351b178b240", 9.59 },
		["A village once asked me to carve a mask for their children's festival. Something friendly, they said. Nothing frightening."] = { "5a7554c6bee4", 7.78 },
		["A week later I forgot to carry the seven, and lost my eyebrows. I went back to the note. It was my own handwriting. I'd know that crooked g anywhere."] = { "b9c4c5f65a12", 10.84 },
		["A week later I had to take off the thick ones to fix a buckle. My bare hands would have frozen to it. The thin pair saved my fingers."] = { "5331e4d415ce", 9.3 },
		["A week later I heard my story told in the same tavern, by him, with a bigger raptor. And he was charging admission."] = { "18ccded9e85f", 8.33 },
		["A while later, in a city a long way from there, I bought a shelf. I asked what the wood was. Fine Ashenvale timber, he said, and very cheap."] = { "c285bb80b4a5", 10.32 },
		["A woman at the back told me it was very nice, but her children hadn't eaten since yesterday."] = { "17f1998b30e8", 5.54 },
		["A woodcutter cut his leg badly, far out in the hills, and the nearest healer was half a day's walk away. Nobody had a horse."] = { "69962b8b0303", 9.17 },
		["A year on, on the far side of the sea, I was digging through my pack for a bit of string. And there it was, at the bottom."] = { "9468df2dba58", 8.33 },
		["A young man came all the way out to Tirisfal to find me, carrying a satchel. His grandfather, it seems, once loaned me forty silver."] = { "db5a4f2d3794", 9.3 },
		["A young mother and an old carpenter, when it happened to me. Both of them bleeding. I had enough for one, and I knew it."] = { "c9ba6b74c790", 8.1 },
		["A young soldier with a broken leg, shouting, and there I was, all eager. I laid on my hands before anyone had set the bone."] = { "62948293f56e", 8.83 },
		["About a mile on, one passed me without so much as a look. That's when it struck me. They weren't chasing me. We were all running from the same thing."] = { "77f65ba02c19", 10.66 },
		["About a week in, I tried to remember what color my front door was at home. It was a silly thing, and I just couldn't get it."] = { "26fa32193122", 7.92 },
		["About six feet, he said. He wasn't unfriendly about it. He looked at me the way a good tailor would."] = { "e900339c1bde", 6.95 },
		["About this high, it has a groove you could rest your arm in. I asked the old master who cut it, and she laughed at me."] = { "1965df1c696f", 8.23 },
		["Across Darrowmere Lake, in the Western Plaguelands, stands Caer Darrow. They say there's a school there, of a sort, and that its bell still rings at dawn."] = { "18b51df6023a", 10.5 },
		["Actual rain, in Tanaris! People ran out into the street and stood with their mouths open. Old goblins were weeping. It was very moving, for about ten minutes."] = { "5483c0b4f512", 11.81 },
		["After I woke, I went back to the old house. I don't know why. You do, at first. There was nobody left there that I knew."] = { "e9a2c560dd60", 9.46 },
		["After a long time it said, in a voice like dry leaves, I used to swim here. It waded in to the knees and stayed there."] = { "e8c01f9bf0ab", 9.06 },
		["After a long while I worked it out. I could hear something else, out there in the dark, holding still as well."] = { "a1f046dd509f", 7.5 },
		["After a long while our sergeant whispered, \"Whose orders?\" And I swear to you, somebody down the line drew breath to answer."] = { "cfd5281f5f99", 8.75 },
		["After a month I asked what I was doing wrong. She said nothing. I was doing it right. It was the tree that was taking its time."] = { "f3bf73fd46b6", 8.99 },
		["After a week in Felwood, you'd be glad to see anybody. So I walked up to Timbermaw Hold with a big smile, and a large furbolg put one paw on my chest."] = { "c9c36a659f5b", 10.71 },
		["After a week of it, I started humming the right note as I went by. One night, they played it clean. I clapped."] = { "23c4ad6b3888", 8.05 },
		["After a while I answered. I gave my name, as a joke. It asked again. So I told it where I was from. It asked again."] = { "b996531e9f9f", 10.5 },
		["After a while the smell changed. It smelled like my own ration, exactly, right down to the dried apple."] = { "3c1378264ec2", 7.39 },
		["After a while, it was saying my name, in my grandmother's voice. Very kind. \"Come out here,\" it said. \"There's plenty of room.\" She'd been dead six years."] = { "cd144408ebf9", 11.62 },
		["After that I thanked every tree I passed, just in case. It's a big forest. It slowed me down a good deal."] = { "7c6accfcedaa", 7.92 },
		["After that the pylons started failing, and they lost word from the other islands."] = { "513ea6429a0e", 5.07 },
		["After that we all did it. The clerk knew. He just kept writing it down, and kept drawing rations for forty."] = { "d3e336794da7", 7.44 },
		["After that, half the camp started asking for green thread. They said it made it easier to spot your own people in the fog."] = { "1efcf3fa2ad8", 8.23 },
		["After the Sundering, the city lost the magic of the Well, and its rulers would not let go. Their elders say the prince meant to feed that magic with a demon."] = { "d575296f258c", 10.42 },
		["After the city was lost, I set up a little repair bench in the camp. A child came to me one day with a tin bird and said it was broken."] = { "e8b0fea18fb2", 8.8 },
		["After the exile, Taelan's mother told him his father was dead. So the boy did what boys do. He buried the hammer at his father's grave, down by the Undercroft. An empty grave, for a man still living."] = { "724d1732ac9f", 15.26 },
		["After the first war against the Legion, he and his druids lay down to sleep in the Emerald Dream. She stayed awake. Someone had to watch over the kaldorei."] = { "4758e5baf998", 10.5 },
		["After the river fight they still called the full roll every morning. Forty names. There were twelve of us left to hear them."] = { "b084945a2167", 7.58 },
		["After the worst day we ever had, he came down the line as usual. Same order, same full bucket. And he stopped at every empty place."] = { "47da9df27dc1", 9.82 },
		["After two weeks in Desolace, where everything is gray, I bought a scrap of blue cloth at Shadowprey Village. The seller asked what I meant to mend with so little."] = { "804828c4d38e", 10.19 },
		["Afterward, shaking too hard to hold a cup, I asked how she had stayed so calm."] = { "5a73d405c28d", 4.99 },
		["All my life I've done the asking. You call out, you wait, and perhaps something answers. That's the order of things."] = { "05f5b3091c95", 7.86 },
		["All of us were. The whole company, in perfect ranks, in the dark. And no one could remember getting up."] = { "1135496acde6", 7.99 },
		["All right, quiet down a moment. I've got a tale for you."] = { "966d586eac7c", 4.21 },
		["All sorts stop there. People who'd cut each other down anywhere else, sitting with bowls on their knees, too tired to bother. Nobody asked me who I was."] = { "4bf77e657b4a", 10.5 },
		["All the walkways up at Freewind Post are rope, slung between the needles, a long way above anything soft. There's an old ropemaker who tends them."] = { "14155ad74a35", 10.42 },
		["All we had in the yard was a hay wagon. I don't remember whose idea it was. Twenty of us got behind it and ran."] = { "be2994e9a146", 7.86 },
		["Along the high cliffs of Zephras Isle there's a row of posts, sunk deep in the rock. Each one has a rope tied to it, running out to the edge, and stopping there."] = { "f0efb50eb503", 10.5 },
		["Along the row, quietly, lifting each latch with my teeth. I'd reached the last one when a man with a lantern came round the wagon and shouted."] = { "a7c802294dfd", 9.17 },
		["Among my clan, no fire is refused at night. Not to anyone. The cold doesn't care whose side you're on, so neither do we, until sunrise."] = { "d19456a34ef4", 10.97 },
		["Among their papers was a torn journal page in Stalvan's hand. All about Tilloa. How she was growing up. How bright she was. Careful writing, the way you write something you've thought about for a long time."] = { "6b6d54f3a9d9", 13.84 },
		["An apothecary saw me looking, and asked in a kind voice if I'd like to know what it was for. I found I had somewhere to be."] = { "13e0bb25de7d", 8.46 },
		["An eager young one asked me why I let the wolves take that deer. I could have stopped them, and it was so gentle."] = { "dd9a0887b423", 6.97 },
		["An echo, I told myself. Except an echo comes back quieter, and this came back a little louder."] = { "0ed56c74c83e", 6.56 },
		["An enemy came to our fire once, half dead and missing a boot. My grandmother looked at him for a long time. Then she handed him meat, and said nothing."] = { "f16195feda4f", 10.19 },
		["An explorer at Marshal's Refuge in Un'Goro offered me a copper for every unusual stone I brought back. I found one that rang like a bell when you tapped it."] = { "f7df4d89c377", 10.55 },
		["An hour I stood there, out of facts and getting cross. Finally I said I give up, I don't think I know anything at all."] = { "dfda5c774c3e", 8.28 },
		["An hour he was at it. Threats, mostly. Nothing came out of that water. So he stomped back up the beach, very angry."] = { "02c6f79a78c9", 9.77 },
		["An hour later, it was full of snow again. Not wet. Dry, and packed tight, in the shape of a hand."] = { "08aac8c5e94d", 7.63 },
		["An hour of walking blind, with sand like thrown gravel. Then the rope snapped tight and nearly tore me in half. Someone was down, and the wind was dragging them."] = { "1c0a52a854ae", 12.09 },
		["An hour on, I felt a tickle starting in my throat. And before I could cough, I heard it, somewhere behind me. Coughing for me."] = { "016eab31424f", 8.93 },
		["An inn I stayed at had a stew-eating champion, and a sign. Beat him, it said, and win a week of meals on the house."] = { "544b1e9f3f02", 7.97 },
		["An innkeeper once set a bowl of stew in front of me and stood there beaming, and the whole room went quiet to hear my verdict."] = { "f60373016560", 8.15 },
		["An ogre caught me up by Crushridge Hold, in the Alterac Mountains. One of the big ones with two heads. It held me up by the ankle while they discussed it."] = { "3790e9879079", 10.92 },
		["An ogre walked by behind him, and he asked it for a copper too. It paid. I still have that receipt, and it's the most official thing I own."] = { "4f617558c57b", 9.87 },
		["An old burglar taught me never to take everything. A man who's lost all his silver calls the watch. A man who's lost half starts counting it again."] = { "42b0f97681c5", 9.9 },
		["An old dwarf in Thelsamar told me there's a stone on the shore of Loch Modan that opens if you sit facing the water at dawn and bow to it three times."] = { "74a5996b1f15", 9.64 },
		["An old fellow came out and asked if he could keep one tree. Just one, the one by the gate. Our officer said no, quite gently."] = { "89be62d5a8f1", 9.72 },
		["An old fisherman pulled me into his boat and asked what I'd said. I made the noise again. He went pale and rowed faster."] = { "2d511004a26b", 8.8 },
		["An old guide took six of us over the hills once, and made the strongest of us carry a coil of rope as thick as my arm. That was me."] = { "7b8f43ea7a40", 9.35 },
		["An old herder came by and moved my bedroll around, without asking, so my feet faced the cave. He said never sleep with your head toward it."] = { "f052af08755c", 9.87 },
		["An old herder told me not to worry. Things that die out on the plains like to lie down somewhere comfortable. I'd only taken its spot."] = { "444ddeb09fb7", 9.17 },
		["An old hooded seller held out a small carved box and said, you'll want this later. I said no thank you. The seller only nodded, as if I'd said yes."] = { "2f77a95e6384", 11.13 },
		["An old marsh hand told me that's how it works. The swamp doesn't steal. It's more of a shop. You give it what you've got, and it gives you what somebody else had."] = { "5d26e92d73ee", 10.5 },
		["An old mason in Stormwind told me every stone in those white walls has somebody's mark on it, if you know where to look."] = { "b8771f69e63b", 7.13 },
		["An old merchant, the room almost dark, one candle by his bed. In, and out. Some time after midnight he stopped, and I started the prayer."] = { "36917982b11d", 11.39 },
		["An old miner took me down there. He knocked. We waited a long time. And up through the stone came four knocks in return."] = { "412a08868364", 8.99 },
		["An old one in our camp wore a knotted cord around his wrist. One knot for each enemy he'd killed, and it went up past his elbow. Pups would beg to touch it."] = { "138a17be4e57", 10.89 },
		["An old prospector stopped me on the trail out there, some years ago. Sun-beaten, half blind. He grabbed my arm and said, don't take the left path. That's all."] = { "ec16cd92ade5", 11.96 },
		["An old scholar walked over, regarded me, and said gently that it had been quite an eventful century. I believe it may have been written down."] = { "6ec2e312209a", 9.12 },
		["An old shepherd grazes her flock on it. I couldn't believe it. They'll fight there at noon, and by dusk, there she is with her sheep, as calm as you please."] = { "5ecf7b39e3d4", 10.89 },
		["An old smith in Ironforge let me watch her temper a blade. She heated it, quenched it, and then, to my surprise, heated it again, very gently."] = { "1df833140ce2", 10.5 },
		["An old soldier taught me this. Every morning, name one thing you're glad you lived to see."] = { "58a90d1634d3", 6.56 },
		["An old soldier told me never to fight anyone who's smiling, never to bet on anything that can talk, and never to sleep at a nice inn beside a cheap graveyard."] = { "6346284d1018", 10.32 },
		["An old trapper in the Hinterlands showed me how to tie a snare. Twist, loop, pull. I got it on the third try and was very proud."] = { "0d4baf8c4138", 9.64 },
		["An old wanderer I met there had been camping in those woods for years. I asked what he was doing. He said he'd come to enjoy the end of the summer."] = { "da93e146e457", 8.7 },
		["An old warrior asked me once if I knew what honor was. I said, it's never running from a fight."] = { "d9cac7620b47", 6.84 },
		["An old warrior asked me to reach it with my left hand. I couldn't. Then she asked me to picture my right arm in a sling."] = { "f9840c5b5ac9", 8.15 },
		["An old woman was washing a shirt at the ford, late one evening, with no house for miles. I called out good evening. She kept scrubbing."] = { "b5250e153651", 9.46 },
		["An old woodsman once told me that at any fire, the seat with its back to the dark is the one things come to first. Not to hurt you. Just to look."] = { "d8e66d47f1d1", 9.64 },
		["An ooze in Un'Goro Crater ate my map. I'd set it down for a moment on a rock, and the rock turned out to have opinions."] = { "b93826a95839", 8.2 },
		["And I got handed a pair of mittens. Red ones, badly knitted. Then somebody hurried over and snatched the little one away without looking at me."] = { "1086aea4e6d7", 9.17 },
		["And I said out loud, without thinking, well, that wasn't so... And something up in the branches, in a voice like a creak, said bad."] = { "98314fe26a4f", 10.06 },
		["And I was thinking how nice that was, when I noticed the rock wasn't behind me anymore. I was four steps from the edge, and I don't remember standing up."] = { "6ce329cfa6bd", 9.72 },
		["And every evening she makes him wait on the step a while before she says yes. The whole street stops to watch. Nobody's ever seen her say no."] = { "26195da2bf15", 9.48 },
		["And every word of it true. Mostly."] = { "dc621f640447", 2.98 },
		["And from under the floor, very faint, somebody says, \"One more.\""] = { "acb4c4ac897d", 4.94 },
		["And if it starts to taste like something from your childhood, stop eating and tell someone you love them."] = { "f3d2bb559e88", 6.37 },
		["And it did! So I had another, to be sure. Somebody started singing. I may have been the somebody."] = { "0ad9d52f644b", 8.1 },
		["And it worked! Woke me up. Woke the whole block up. Woke some people two districts over."] = { "990dc9a96dc0", 6.71 },
		["And my hand was up. Straight up, like a child who knows the answer. I'd like to tell you I don't know what the answer was."] = { "19cffb483097", 8.46 },
		["And my teacher's true opinion of my cooking. And what the baker calls me when I've gone."] = { "e4423469e3a9", 5.59 },
		["And now that I looked up, there were others. Dozens, all gone gray, some tied higher than anyone could reach."] = { "63e76062e498", 7.78 },
		["And on the day I was sure we understood each other, it turned around and walked off."] = { "0c64d180ba3d", 5.17 },
		["And on the day we go home, I am going to set it on fire and dance around it."] = { "d2e2fcc23a0d", 5.07 },
		["And out in the black, this awful honking starts up. Bram had found a horn, and he had no idea how to play it."] = { "0f43832bc632", 7.5 },
		["And right then, from the box, somebody coughed. I took the ham and I left. I've never learned how that one ended."] = { "15ce8e289161", 7.99 },
		["And somebody said, in a friendly and tired sort of way, your room is ready. I walked until daylight, in that rain, and I thanked it for every drop."] = { "c8d1878ed885", 10.89 },
		["And that boy grew up to be Highlord of the Scarlet Crusade, holding Hearthglen. The old man said Taelan was still a good man. He only needed to remember. So Tirion set out to remind him."] = { "0d55f78a28f9", 13.71 },
		["And that's how you go over. It gets under you and takes your feet. To stay on the path, you have to turn and lean right into the thing that's trying to knock you down."] = { "d81a5ad6b991", 9.59 },
		["And that's the tale, more or less as it was told to me."] = { "65d6ebc13d0e", 3.45 },
		["And that's why I always sit facing the door."] = { "6e7b6d7c157f", 2.85 },
		["And the kaldorei were mortal. They knew that was the price before they did it. They did it anyway."] = { "90e877f951a5", 6.48 },
		["And the thing is, I paid. We all paid. It felt wrong not to. I stood in that line getting rained on, and I've never been so glad to be robbed."] = { "9c8b449b95ca", 10.84 },
		["And then decided what to write down. I think about that person more than I think about anyone else in the whole sorry story."] = { "abd17a090204", 7.81 },
		["And then you come to Light's Hope Chapel, and there's grass. Real green grass, an acre or two. I stopped at the edge of it, and I just looked at it for a bit."] = { "f971a193c9d1", 10.5 },
		["And then, very softly, from a good deal closer, the same voice said, that's right. Stay there."] = { "f058075bad42", 7.81 },
		["And they were all correct, as it turns out. You can get there any way you want. That place is a circle. It's the leaving you have to work at."] = { "872232b09175", 9.53 },
		["And we still here, eh? Still laughing. Stay around long enough, and that's all the victory you get."] = { "6ff8d6b5f345", 6.84 },
		["And you can. One long slow breath, in and out, so slow you could fall asleep between them. It's the most peaceful thing I've ever heard."] = { "a5b121691466", 11.02 },
		["Anyone in Lakeshire will tell you about the great pike of Lake Everstill. I laughed at them until I hooked it."] = { "bce94ff02843", 6.79 },
		["Anyone want a story? I've got a good one."] = { "14f2d6371ddd", 3.21 },
		["Anyone will tell you to keep walking through the Cleft of Shadow in Orgrimmar. I had the misfortune of stopping to tie my boot."] = { "f4eebfb114e0", 8.15 },
		["Archimonde reached the tree and climbed it to drink its power. And Malfurion blew the Horn of Cenarius."] = { "df2e82ed9b2d", 6.74 },
		["Armor's the lighter burden. I'd wear twice as much, if I could only stop seeing clearly."] = { "d15a1217a667", 6.48 },
		["Around and around, at about the height a branch would be. I watched for a while. Then I left, and it was still there."] = { "3eab200d0a91", 8.8 },
		["Around midnight, somebody started pounding on the door. A farmer, out of breath, mud to the knees. His wife's labor had gone wrong. Would I come?"] = { "99a80befcb4b", 10.89 },
		["Around sunset, one of them looked to the south and stopped talking. There was a brown wall across the whole horizon, and it was getting taller."] = { "07e53d6604dc", 8.93 },
		["As I came closer, I saw that shirt had a square green patch on the elbow, sewn crooked. My sister sewed mine like that."] = { "3398da947efc", 8.57 },
		["As the world broke, their governor Athrikus Narassin promised a spell to shield them. Instead he trapped their souls in gems and fed on them. Hundreds, Sargath said."] = { "5c1045412c01", 11.73 },
		["Ask any night elf old enough, and they'll tell you: they were never supposed to die. For ten thousand years, the World Tree on Mount Hyjal kept them young."] = { "0a8e703bbe0f", 10.19 },
		["Ask around Ironforge and they'll tell you the city goes deeper than anyone's dug. Go down into the Forlorn Cavern and knock three times on the floor."] = { "86eb83585b85", 9.72 },
		["At Aerie Peak in the Hinterlands, a young gryphon chased a child's kite right off the edge of the cliff. The child was still holding the string."] = { "c51a0eb295a0", 9.25 },
		["At Cenarion Hold in Silithus I watched a quartermaster spend an hour every morning brushing sand out of the door locks. Every morning, the same locks."] = { "141bbb6a4873", 9.9 },
		["At Chillwind Camp in the Western Plaguelands, I was asked to carry a mended coat to a soldier on watch. The only thread they'd had was bright green."] = { "b7a45f4df4a7", 10.06 },
		["At Menethil Harbor, in the Wetlands, a fishing boat broke loose in a storm and started drifting out with a sleeping man aboard. We could hear him snoring from the dock."] = { "bc445beb9d24", 10.55 },
		["At Midsummer, every town lights a bonfire taller than a house. This little one's my favorite, though."] = { "684953cc8068", 6.95 },
		["At Midsummer, folk try to steal a flame from the other side's bonfire. Don't ask me why. It's tradition."] = { "6a596b7a542a", 8.05 },
		["At Refuge Pointe in the Arathi Highlands, I spent an afternoon under a roof being mended, picking up the nails the workers dropped."] = { "3ce9ae885e5b", 8.7 },
		["At Stratholme, Uther refused the prince's order to put the city to the sword, and Arthas called it treason."] = { "b7247d166119", 7.13 },
		["At a crossroads I tried to ask which road she wanted. She heard it as me asking whether she'd rather go on alone."] = { "6c23ee2775d1", 7.5 },
		["At a harvest fair, a prize bull broke out of its pen and went straight down the row of pie tables, with a crowd of children at the end of it."] = { "5588c3cd7004", 9.25 },
		["At dawn I counted again and I got nine. So I counted once more, more carefully, starting from my bedroll. Nine."] = { "9e53b68b9b88", 9.72 },
		["At dawn she gave him a full waterskin and pointed. \"You have until the ridge,\" she said. Then she picked up her spear and waited, and he ran."] = { "a4148c317ba3", 9.87 },
		["At dusk one autumn, I saw a stag at the far edge of a meadow. A fine big one. And the hair stood up along my arms before I knew why."] = { "10ccecf4a3eb", 9.82 },
		["At last I found someone who could read it to me. It was from his mother. The roof was leaking over the bed, and could he come fix it on his leave."] = { "3103da44c4f2", 9.82 },
		["At my first posting, a village asked me to bless their new well. I was young, and I meant it very much. Perhaps too much."] = { "5e45309c8500", 8.65 },
		["At night in the Searing Gorge, you can hear the hammers. They're working down in the Cauldron and they don't stop, hour after hour, in time."] = { "f84cb2dfdecf", 9.06 },
		["At sundown my host came up to check the shutters. Very thorough. Then the door closed, and I heard a bolt slide across, on the outside."] = { "1691a9fca78f", 9.46 },
		["At sunrise, it bowed to me and left. I lost two toes, and I've never been so proud of anything."] = { "520986f2abac", 7.44 },
		["At the Crossroads I borrowed a flat cooking stone from an old traveler. When I was done, I scrubbed it with sand until it shone, and I was very proud of myself."] = { "7f0c7fd7df67", 10.24 },
		["At the Darkmoon Faire, a fortune teller asked me five questions and wouldn't say why."] = { "9d428a91208d", 5.54 },
		["At the Harvest Festival they set out a great feast, and they always leave a few chairs empty."] = { "0fb96a9bdd87", 6.01 },
		["At the Lunar Festival, a goblin sold me what he swore was the biggest firework in Moonglade."] = { "62cd87b5bf3d", 5.96 },
		["At the bottom of the hill, three children were playing in the road. They hadn't seen it. They were busy arguing over a stick."] = { "384598ffd470", 8.15 },
		["At the bottom, a woman was filling buckets. She had her back to the chute, and she couldn't hear it over the water."] = { "76edb46c8faa", 6.84 },
		["At the end of the row it carried an empty basket to the farmhouse door and set it down. There were dozens there already, in neat stacks."] = { "db688fa88ab5", 9.12 },
		["At the end she smiled and said my answers had already told my fortune. I just hadn't heard it yet."] = { "53a9680f779d", 6.48 },
		["At the faire there's a game where you steer a little clockwork tank with a box of levers."] = { "2fb1a854b807", 4.99 },
		["At the inn in Auberdine there was a woman drying five coats by the hearth. It rains a lot on Darkshore, so I wasn't surprised. Then she told me only one was hers."] = { "6cdfc77df55f", 10.74 },
		["At the inn they said not to worry. It only walks with people who are alone, and it always stops at the edge of town. They said it like that was the comforting part."] = { "43c1b874b5dd", 9.9 },
		["At the road he stopped dead and said this was as far as he went. I offered him a coin, and asked how long he'd been guiding folk across."] = { "2b33f7b9ca90", 8.62 },
		["At the scout tower, Grand Inquisitor Isillien stepped out with his Crimson Elites. The Grand Crusader had ordered the Fordrings dead. Isillien struck Taelan down with holy fire, there on the road."] = { "ab7a1c4a4d89", 13.24 },
		["At the second house they served roast mutton too. And on my way out, I noticed the sheep with the black ear wasn't by the fence anymore."] = { "098c76ff8b42", 8.39 },
		["At the top stood one bent, ugly old tree that nobody had ever wanted. I've thought about that tree more than I'd like to admit."] = { "f0b78fa2e04a", 8.52 },
		["Athrikus was up there, ringed by his strongest warlocks. Balthule wanted to wait for Delgren. But Delgren had trusted his messenger to go in alone, so in they went."] = { "979c56af49b5", 11.55 },
		["Back at the tower, Balthule was rattled. A blinding flash had burst from the high room, then screaming, then lightning striking the ground every so often."] = { "e00cb7949370", 11.39 },
		["Back in Goldshire, she pays the baker's girl to read it to her, and tells her what to write back."] = { "24642ea9221c", 5.9 },
		["Bandits grabbed me in the dunes of Tanaris. Took my water and my boots, and tied me to a post in their camp while they argued about what I might fetch."] = { "b187b6ce620b", 9.46 },
		["Bandits stopped the coach I was riding in, on a narrow road with a cliff on one side. Six of them, and a driver who'd already decided to faint."] = { "5ade7fab69b1", 10.06 },
		["Because it hurt just the same. I said you've pulled the wrong one. He peered in, and he looked delighted."] = { "88de1d27da27", 7.39 },
		["Before I change shape, I say my own name out loud. I do it again after. Most of us do. It's not superstition, and I'll tell you why."] = { "b5a6d49569d3", 10.61 },
		["Before anyone turns in, let me tell you one."] = { "69a93bbd840e", 3.19 },
		["Before he faded, he named one more. Athrikus had a lieutenant, and the lieutenant kept a book."] = { "a561646d2e5f", 7.26 },
		["Before she was the Banshee Queen, Sylvanas Windrunner was the Ranger-General of Silvermoon, the high elves' city in the north."] = { "e9ac78c9521a", 8.33 },
		["Before that, he said, it only ever answered with three. He looked at the floor, and he kept his voice very low all the way back up."] = { "7ad22b5c2d9b", 9.17 },
		["Best grazing in the valley, she said. It has been for years. Her sheep are very fat. I've not eaten mutton in Hillsbrad since."] = { "c2e4a1da88fc", 9.3 },
		["Best mule I ever owned. Carried me through two winters and bit everyone who tried to rob me."] = { "05c6890d090f", 6.32 },
		["Best night I've had since I died. I've been keeping that hand a little loose, for special occasions."] = { "91aedf4a8fd3", 6.95 },
		["Best tavern I ever found has a sign out front that reads \"Middling Ale. Fair Prices. The Keeper Is Often Rude.\""] = { "d1c369fcf981", 7.99 },
		["Best work anyone ever did on it. Some days I miss the dents."] = { "065905088634", 4.7 },
		["Bites, he said. Kicks. Lies down in rivers. Will outlive you purely out of spite."] = { "b023cc9c0571", 7.03 },
		["Blue as the twilight and gone in a sip,"] = { "19e19c5830b1", 2.98 },
		["Boar, he said. Plenty of boar around. They've changed a little, on account of the land, but it's perfectly fine eating as long as you don't look at it too long."] = { "3135a05c94b1", 10.55 },
		["Both horns went right into the door frame, and there they stayed. I could neither go in nor go out. They were very kind. They brought me a stool."] = { "31bd1a8b49bc", 10.74 },
		["Bound to a wind lord, then broken in two,"] = { "2febaa1fc695", 3.37 },
		["But I could still hear it. In, and out. It was slow, and it was coming from the wall, where the candle threw his shadow."] = { "e7202836e554", 8.7 },
		["But I stayed. Dawn came up, and nothing had happened, and I took the oath anyway. I've come to think that was the point."] = { "68ad4d394b47", 8.2 },
		["But I think it's what all the other stories are trying to get back to."] = { "8a58a4ecf411", 3.63 },
		["But I'll tell you, that same wind has got to go somewhere. Somebody out there might've looked up from their work that week, and not known why."] = { "3d63820518e7", 9.3 },
		["But a tree is a promise that you'll come back. It's a large thing to say to a hillside."] = { "2122555156a2", 5.41 },
		["But every orc alive today is free because Grom Hellscream walked into that canyon."] = { "d79a2835331c", 5.59 },
		["But it came back out, in the end. Gem, shaft, pommel. Shael'dryn fit them together. Only, a rod is not a rod until it remembers what it's for."] = { "5d622b204948", 11.62 },
		["But no one takes back the knowing. It's been eleven years. Around this time every morning, I still think, somebody ought to feed that bird."] = { "be020e21d5dd", 10.14 },
		["But that tree's in good shape. I looked it over, and I know a bit about orchards. The dead wood's been cut, and the cuts were clean. It's being done each year."] = { "8150518a398b", 10.71 },
		["But that's not why. She was the one who was awake. She was looking at me. That's all it came to, and I've thought about him every day since."] = { "274797268af2", 9.64 },
		["But the dog was still in the yard. Ancient by then, gone white in the face and half blind, and he got up when he smelled me."] = { "936aba08ac45", 8.46 },
		["But the orc was found, and dragged off to be executed. Tirion drew his sword on his own men to stop it, and lost."] = { "be4f892febb8", 8.15 },
		["But the small ones, the ones you build yourself on the road, those are for the people sitting by them."] = { "fbf5be00036b", 6.06 },
		["But the step is wet every morning. Somebody might be looking for us."] = { "268489b98fa9", 4.57 },
		["But there's no moon in a tide like that. It was coming in against the wind, in a straight line, and it had a sound to it, as of something being dragged."] = { "c2cde6000e2d", 11.15 },
		["But there's this tune I hum when I'm working. And sometimes I stop, and the tune goes on for a bit."] = { "60c0fcbfb2a8", 6.71 },
		["But they've never once given me a blister, so I've decided that's a risk worth taking."] = { "3d2b79e101dd", 5.77 },
		["But when the first big snow came, I went up there, took the shape, and crawled into the den beside her. She looked at me. She let out a long breath."] = { "e8c3e80080d2", 9.48 },
		["But when you hear her name, remember the ranger in the forest, holding one more gate."] = { "6ca77b760154", 6.19 },
		["By dusk the cord sagged nearly to the ground, the way it does when somebody's hung a wet blanket on it. There were still only three shirts."] = { "8aad5c29942b", 9.12 },
		["By midnight I'd been everything in the book, and I still hadn't had a single piece of candy."] = { "bec759ef7dc9", 5.41 },
		["By midnight I'd fixed six tables, been bought four drinks, and the whole room was talking to each other about folding."] = { "9ffa6cf178c4", 7.21 },
		["By midnight she had my purse, my cloak, and my horse. She handed back the cloak. She said the color didn't suit her."] = { "920ac7ef27dd", 7.97 },
		["By midnight the spoon stood. So did the stew, out of the pot, holding the pot's shape."] = { "fbf29cf3aa19", 6.84 },
		["By midsummer I knew the beetles by their habits. There was a fungus like a shelf, and ferns growing out of its back. It was the busiest place in the forest."] = { "1f02773a5521", 10.66 },
		["By midweek, I was dizzy and miserable, and she was still swinging her pick like it was spring. She handed me a cup."] = { "7971d45cb901", 8.28 },
		["By morning they were gone. Never learned their name or where they came from."] = { "10ae696415c4", 4.99 },
		["By noon she took pity on us both and stretched her cloak over the top. I thanked the tree loudly, so it would know."] = { "e61617538381", 7.68 },
		["By noon we'd learned the word for tomorrow. It turned out to be the only one we really needed."] = { "330610803015", 6.06 },
		["By noon, forty strangers had shouted forty answers across the plains. By evening, three were arguing about something else. Two had come to blows over a fish."] = { "9417560d3510", 11.02 },
		["By spring, three families in our lane had dug small graves. Nobody said anything about that either."] = { "32d3c28862a8", 6.79 },
		["By sundown I'd filled a bucket. I handed it up and asked how long they'd worked together. Thirty-one years, said one. Married, said the other."] = { "fd5f9c001cc6", 10.29 },
		["By supper they'd made me guide of the hunting party, on account of being the only one who'd seen it."] = { "868fe272c5f3", 5.59 },
		["By the end of the week the map was all smudges. I offered to draw her a clean copy."] = { "c5596c6730f6", 5.64 },
		["By the end of the week, I'd found out how much my employer was stealing. It was astonishing. I had no idea you could do it with paperwork."] = { "b4c39a81b88e", 9.04 },
		["By the second night there weren't many turns left. And up comes Pell, our quartermaster, who had never held anything heavier than a ledger."] = { "c750d81cbd20", 8.8 },
		["By the second street it had offered me a castle, a wedding, and the answer to any one question. I kept walking. I'm not proud of how slowly."] = { "88f5a113f6da", 9.67 },
		["By the third day I'd told him every story I knew, and made up four more."] = { "176d757d5cc6", 4.99 },
		["By the third day he'd set out a stool for me. By the fifth he'd stopped giving directions and started asking about my family."] = { "e354ed6e8264", 7.99 },
		["By the time I could say it right, her hands had stopped shaking. So had mine, which I hadn't noticed."] = { "27d4bb316e12", 6.48 },
		["By the time I was grown it had dragged a boat upriver and eaten somebody's dog. He told it at every meal."] = { "8142abd9d7a8", 7.5 },
		["By the time anyone came looking, the Flintridge house stood empty. A caretaker was selling off the last of their things to pay the taxes. The whole family was gone."] = { "3ecfb912c09a", 11.08 },
		["By the time it passed, we'd lost the camels, the trail, and all the water but one skin. Cenarion Hold was a day's walk off, at least."] = { "fc127b02a0cd", 10.19 },
		["Caer Darrow is a dead place now. But the artist, Renfray, was still there. A ghost, still waiting by his easel."] = { "d903b5aeef80", 8.8 },
		["Carters took to throwing it crusts just to get past. Then the guards did. Then a visiting tax man, and he wept a little."] = { "2f98949f6006", 8.41 },
		["Children in the valley were finding toys in the snow until spring."] = { "2966ffce6197", 3.97 },
		["Children mostly scream at me. I don't take it personally. I'd scream too. But there was one in a market once, too small to have been taught yet."] = { "0d44474dd545", 9.53 },
		["Children's Week, I took an orphan along for a few days. Nobody warned me about the questions."] = { "abf842083111", 6.9 },
		["Cover their eyes and they'll follow you anywhere. So I did, with my coat, then his, then every coat at that inn, one horse at a time."] = { "24c248484723", 10.24 },
		["Crossing the high pass one winter, I kept seeing a second set of footprints beside mine."] = { "4ffd750b55b2", 5.64 },
		["Crows, though. Crows know exactly what you did. They've told all their friends, and they think it's hilarious. I wouldn't ask them, if I were you."] = { "988ae79699a2", 10.14 },
		["Dark enough now. This is the hour for a proper story."] = { "270a732534f2", 4.34 },
		["Death's got a few advantages, you know. I no longer get colds. I haven't slept in years. Saves a fortune on inns."] = { "f0a917c46dfd", 8.2 },
		["Deep in the Badlands they've been digging at Uldaman for years. I shared a fire with a digger who'd been there since the first door was found."] = { "4d88620bc1d5", 8.46 },
		["Deep under the big trees of Feralas, I walked into a camp with nobody in it. A pot over the coals, still warm. Two packs. A bedroll still in the shape of a sleeper."] = { "c2911a77b7e4", 11.91 },
		["Delgren could read orcish, of all things. Know your enemy, he liked to say. The scribbles told him two soul gems were left, held by satyrs at Night Run and Satyrnaar."] = { "82d6833bbcd9", 12.56 },
		["Delgren said he'd never once doubted them. Then he gave his blessing, and told them there were plenty more wrongs in this world waiting to be put right."] = { "307c48f6acb3", 9.4 },
		["Desperate, Grom found a fountain filled with the demon's blood, left waiting for them. With that blood in him, he killed Cenarius, the teacher of Malfurion."] = { "062fcf824388", 11.21 },
		["Did I ever tell you about the time I was bested by a chicken?"] = { "f16fbce9262a", 3.63 },
		["Do you know what Hallow's End is really for? It started with the Forsaken."] = { "df79119fd3bd", 5.17 },
		["Do you know why I learned to open a door across the world? It's the hardest thing they teach. I told my masters it was for the theory."] = { "f73838db3da8", 9.12 },
		["Doesn't matter what it is. You just have to find one. And you always can."] = { "eefee0a997c0", 5.83 },
		["Don't ask for directions at the Sepulcher in Silverpine unless you're ready for the answer. It's a graveyard with a mailbox."] = { "a0f049276fe3", 7.81 },
		["Don't look like that. Empires fall. We know better than anybody. I'm just saying, we've seen a few things come and go."] = { "091fc9252d69", 8.8 },
		["Don't worry. Your secret's safe with me. Stay as long as you like."] = { "d752b9caea56", 5.12 },
		["Down at the bottom I cut the horse loose first, because it was kicking. Then I found the driver, stuck under the seat and very surprised to see me."] = { "4e793f4765fc", 9.4 },
		["Down in Dun Morogh, a bairn learns two things before walking. Which way's the forge, and which way's the ale."] = { "5b7e2eabc13b", 7.99 },
		["Down the coast from Auberdine they call it the Master's Glaive. A blade the size of a hillside, sunk right into the earth."] = { "042f79cb0920", 7.86 },
		["Down we went. One wheel on the rail, then none. Sparks to my shoulders. The thing came down the slope behind me, burning along the ties."] = { "e3f0a3cb8a73", 10.32 },
		["Dry grass and a high wind. We saw the smoke at noon, and by the time we'd got the herd moving, the fire was a wall across the whole of the plain."] = { "9458a3ba02e9", 10.14 },
		["During the Lunar Festival, the elders come back. You'll find them standing in the oddest places."] = { "7adf3f63a34d", 6.48 },
		["Durotar is a hard land. Red dust, thin water, and everything with teeth. It suits us."] = { "f5a5ddaa2826", 8.05 },
		["Durotar's a fine place, mon, and the orcs been good neighbors. But nobody ever taught them how to fish."] = { "997fd5653871", 6.9 },
		["Dusk came. Then night. Then a dawn so cold our breath froze in our scarves."] = { "4192372fc322", 6.11 },
		["Dust past your ankles. Not one footprint. And there, on a ledge, sat a miner's lunch pail."] = { "ed7f8bfe7949", 7.81 },
		["Each begged me to say nothing to the others. Each was sick with guilt. I began to wonder about this goat."] = { "737b465ec299", 7.68 },
		["Eight raiders on one side, six on the other, and the bridge dropping stones into the gorge with every step."] = { "d05f51a76e0e", 7.78 },
		["Either he's very fast, or there are two of him. They decided they didn't want to know which. I think that was wise of them."] = { "659895d7667f", 8.33 },
		["Eleven lamps on that road. I'm sure of it. But down past the last farm, toward Crystal Lake, there was a twelfth one, burning in the trees where no post stands."] = { "c5c6a3afd198", 12.09 },
		["Eleven marks in, the door's coming off its hinges, and my chalk runs out. A nub of nothing. Just dust on my fingers."] = { "c030fad22343", 8.62 },
		["Eleven more notes, all in my hand, all about mistakes I hadn't made yet. I read them very carefully. The last one said, \"Stop reading now.\""] = { "b84a718c63ec", 11.08 },
		["Empty house, roof half gone. Yet there was a fire going in the big stone hearth, burning nice and steady, with nobody near it."] = { "f7944e9afcda", 9.04 },
		["Eventually a boy from Razor Hill came by with a bucket of slop, and the boar trotted off after him like an old friend."] = { "7d08d304934d", 7.55 },
		["Ever met an honest merchant? I did, once. He sold me a mule and told me it was a terrible mule."] = { "445eb357bf49", 7.81 },
		["Ever tried to finish a Darkmoon deck? Eight cards. I had seven within a year."] = { "8e473d16b3fa", 5.77 },
		["Every Hallow's End, somebody carves a pumpkin and sets it on the old wall outside town."] = { "6c9ea697a511", 5.9 },
		["Every Noblegarden, there's one egg nobody finds. I found it once, under an old stone bridge."] = { "ebaad92e7017", 7.21 },
		["Every Winter Veil, Greatfather Winter visits Ironforge and Orgrimmar. Both of them. At the same time. Everybody knows this and nobody thinks about it."] = { "e973d7f27052", 11.08 },
		["Every autumn he walks up the loch to see if she's still about. I asked what he'd do on the day she isn't. He said he'd take down the mount."] = { "7b4c6074c04a", 8.8 },
		["Every bridge looks like the last bridge. I asked one fishmonger for directions, thanked him, walked for an hour, and asked him again."] = { "40b25478c95a", 9.3 },
		["Every evening he walks out and back, slowly, checking each knot. Not one person has ever fallen from it. Nobody's ever needed to cross it, either."] = { "e200ffc501d0", 10.74 },
		["Every fighter should visit an armorer once a year, just to be told the truth about their career."] = { "bdb556bd39be", 6.19 },
		["Every grandmother I've ever met will tell you that the dead can't cross running water. I've had cause to test it."] = { "bcedb283ffe5", 7.5 },
		["Every house was closed up tight, with heavy boards over the doors and windows. People do that when they leave. You board up against thieves."] = { "af996a189684", 9.77 },
		["Every human my age knows somebody who marched off and never came home. My family has three names on a stone."] = { "738003ef14c3", 7.81 },
		["Every morning in Stormwind, I passed a shuttered shop in the Trade District, and every morning its doorbell rang inside, as if someone had just come in."] = { "f4b70d339bf1", 10.08 },
		["Every morning it faced the door. Every evening, the company joker turned it to the wall. Every morning, the door."] = { "2dca074d3517", 7.5 },
		["Every morning she'd walk the edge of the black and find a strip of green that wasn't there before. Then she'd rub out a bit of yesterday's line with her thumb."] = { "92eaf5d8ca4c", 9.48 },
		["Every morning, a little closer. By the end of the feast it was standing at the gate, facing in. Nobody saw it move. The guards say it's still waiting to be let inside."] = { "925bd805f6e1", 10.89 },
		["Every morning, it gets fed first. I've seen what happens otherwise, and so have my boots."] = { "3482a28cab7c", 6.37 },
		["Every night, for months. Goats stopped giving milk. The elders asked him to stop, and then they asked him to at least move downwind."] = { "0c11f1114c93", 9.12 },
		["Every owner they've had came to a bad end, as far as I can trace it."] = { "f18bdafcdc5e", 4.44 },
		["Every proper family in the mountain keeps a ledger of slights. Ours goes back nine generations. The first entry is one ladle, lent, never returned."] = { "3932797c6b95", 10.84 },
		["Every rope was somebody who trusted the wind one day too long. The islanders never untie them. They say the wind should have something to hold, besides the people."] = { "e6d1e2fee514", 10.79 },
		["Every so often she hears about it. Somebody's wearing it in Ashenvale. Somebody's wearing it on a boat. She says it's seen more of the world than she has."] = { "f02c6d06fdcd", 10.48 },
		["Every time I looked, it had moved along the road with me. Never closer. Never farther off. Just keeping pace, about a field away."] = { "755a50dfb5d7", 9.53 },
		["Every year it steals gifts, and every year somebody has to climb up there and take them back."] = { "4729007666c3", 5.9 },
		["Every year my family left one row of corn standing at the edge of the field, unharvested. It was for the birds, my grandfather said."] = { "51ff365fc79f", 9.4 },
		["Every year when love is in the air, I write one letter. I never send it."] = { "046d1db97a11", 4.75 },
		["Every young mage falls in love with the same trick. A little step through nothing, thirty feet in any direction, quicker than thought."] = { "c0ec65956a5c", 9.22 },
		["Everybody I know who has been to the Undercity got lost in the Undercity. It's all rings and canals, and they all look alike, and they're all green."] = { "2352afbc2f2f", 10.42 },
		["Everybody but old Odda. She hauled her water from the bitter one, every day, and we laughed at her for it."] = { "c3df7dc1b7ba", 7.03 },
		["Everybody fears fire, and everyone's in awe of earth. Nobody warns you about the air. Air hears everything and has no discretion at all."] = { "0c4b75a1667d", 9.77 },
		["Everybody loves the sapling. No one loves the rot, and it does all of the work. I've been to a lot of funerals since. I think about that log at all of them."] = { "23881d3abd7c", 10.89 },
		["Everybody wants to know what's behind a door like that, he said. They bring their picks and their theories, and I don't blame them."] = { "ca1b7b9a66fa", 7.5 },
		["Everybody's got a few skins. I just happen to get more use out of the claws."] = { "aa8fd6eff157", 5.22 },
		["Everyone assumes I chose her because she was young, with children. I've let them assume it. They tell me it was the right choice, and I expect it was."] = { "eb0c4443842e", 9.53 },
		["Everyone down here came back without being asked, he said. A bat flies off, it could go anywhere in the world. And then it comes back."] = { "eb798d1f6d4b", 9.64 },
		["Everyone edges a little closer. You can learn nearly all you'll ever need to know from that."] = { "9be560706e6d", 5.96 },
		["Everyone else had run from me, you understand. On every road. I stood very still and waited for him to run too."] = { "5d1feb0e5a73", 8.05 },
		["Everyone knows the Burning Steppes weren't always burning. There are old ruins out there that they say were a city once, with people going about their business."] = { "8500e19db994", 9.64 },
		["Everyone laughs at the ones who pay. But I've watched three people buy it, and every one of them came back the next week in very nice boots."] = { "0c23620ec862", 8.99 },
		["Everyone looked at me. I'd like to say I volunteered. Mostly I was the only one who fit."] = { "2f1d2006d95f", 6.79 },
		["Everyone wants to know what the animals are saying. They look at me all misty, as if it's going to be something wise. Very well."] = { "816d6484f023", 8.52 },
		["Everyone was looking at me. So I stood up and said he was the most generous man I'd ever known. It went very quiet."] = { "72f0feb0787d", 7.81 },
		["Everyone who comes to the old ways thinks it's going to be about flowers. Saplings and fawns. I certainly did. My teacher sat me down in front of a dead log."] = { "5103b7c6af84", 11.73 },
		["Everyone who passes through the Swamp of Sorrows asks how it got its name. I asked too. There's a bog-cutter who lives out past the Misty Reed Strand."] = { "0fb34c0e7445", 10.37 },
		["Everything in Tirisfal has gone gray and sick, except Brightwater Lake. At first light, that water still shines, as if no one has told it."] = { "47cbf1807d06", 10.06 },
		["Everything you've heard about the look of Orgrimmar is true. Red rock, black iron, and a spike on every surface a spike can go. It's built to scare you, and it works."] = { "5be7638c758c", 11.13 },
		["Except once. On a bare patch of the Golden Plains, no water, nothing to eat, she stopped dead and wouldn't be moved."] = { "3f07f2f2aafa", 8.52 },
		["Family's a delicate thing. What's holding it together isn't always what ye'd choose."] = { "fc195b81bdf1", 5.49 },
		["Finally I just got up without saying anything. She nodded and said, there it is. That's the whole trade."] = { "caea416e462b", 7.5 },
		["Finally he said, I've lived in pretty places. Pretty places have smiled at me and taken everything I had."] = { "6aca32c958bf", 7.73 },
		["Finally my shovel hit a chest. My hands were shaking as I opened it."] = { "edc0fccd4418", 5.17 },
		["Fire and water don't get along. Everybody knows that. But nobody tells you that you have to sit between them."] = { "e9829e79e62b", 7.16 },
		["Fire doesn't understand stopping. I'd been told that, the way you're told a lot of things when you're young and there are raiders on the ridge."] = { "e219f8215ad7", 8.65 },
		["First crack went off like a thunderclap. Then the whole sheet behind us started to go, and it was coming faster than we were."] = { "4e1b0f72a269", 8.05 },
		["First morning, the silence after a name was more than anybody could stand. So someone said \"here\" for him."] = { "8037006772d5", 6.84 },
		["First night, every chair in the room got moved against the wall. I moved them back. Second night, same. I moved them back again, and I whistled."] = { "8fc0ec98d4b6", 10.74 },
		["First rule of my trade: nobody ever remembers the plain one. Learn to be dull. It's the finest cloak there is."] = { "6395617d7ed3", 8.65 },
		["First thing they tell you in Darkshire: if something in the trees calls your name, you don't answer it. I thought that was just a thing to scare visitors."] = { "cea999e56a8c", 8.8 },
		["First thing you learn with a fishing spear: the water lies. You look down, you see the fish, you throw right at it. You hit nothing but sand."] = { "1c3c708d1625", 9.59 },
		["First time I traveled far from Durotar, a stranger walked up to me and said, \"How are you?\" I nearly took his arm off."] = { "22c67e03df38", 8.28 },
		["First wagon arrived with a wet crate. Second wagon, he packed it in straw, and it arrived with a burnt crate and a lot of steam."] = { "4a57369607d8", 9.12 },
		["First winter on the road, I ran out of food and pride on the same day."] = { "64225076b9ee", 4.7 },
		["Fishermen in Darkshore say there's a murloc out past the old wreck who speaks perfect Common, but only to complain about the weather."] = { "3d5082ed7fc7", 8.46 },
		["Five pins, five smooth stretches of road. The last one came right as we passed the guardhouse, which I'd hoped to avoid."] = { "dc256c799111", 8.8 },
		["Folk called him mad. Nobody had walked that road in forty years. Who was he lighting it for?"] = { "0b41c81e7bc2", 6.79 },
		["Folk dress up as monsters now and laugh about it. But the first Hallow's End was no joke."] = { "5202375abb61", 6.53 },
		["Folk hear warlock and think I've sold my soul. Please. I've read the contract. I've read it many times."] = { "61741d91fcc1", 7.99 },
		["Folk think the Light makes everything simple. You know what's wrong, and you strike it down. Very tidy."] = { "505e1c378bef", 6.9 },
		["Folk think the anger is something you pick up with the sword and hang back on the wall with it. I believed that too."] = { "9917fcf02448", 7.08 },
		["Folk think we stand well back from the fighting, humming. And we do, right up until the line breaks."] = { "03fa0341b411", 7.31 },
		["For forty long levels you'll walk till you've found"] = { "90ba8a947934", 3.19 },
		["For my first three years, I wasn't allowed to ask the spirits for anything. Not one thing. All I could do was thank them."] = { "ce3e4ab73c4c", 8.39 },
		["For one breath I could see water on every side of the world. It was silent. Then I came down in a thorn bush, and I've never once complained about that bush."] = { "2519c908e8bd", 10.55 },
		["For ten thousand years she kept watch with the Sentinels, and waited."] = { "757c5f374dcc", 4.39 },
		["For ten years my old ram carried me home from the tavern, and I never once had to wake up for it. Finest animal in Dun Morogh."] = { "17b17103462d", 9.12 },
		["For the fallen, they say. The heroes who never came home from the war."] = { "4aa1e1a47f4e", 4.88 },
		["Forty feet of dry rock, and then one morning they found the old one sitting at the bottom of it, dead, with the pick still across their knees."] = { "8560b6d17438", 9.12 },
		["Forty years she'd been saving them. I don't think anything was ever eaten off them, not one meal."] = { "2263eb2a1e7d", 6.66 },
		["Four days. I learned every tumbler in that thing by feel. I could draw it for you now. I wept on it."] = { "bad4404707fa", 7.92 },
		["Four days. She didn't eat or look left or right. When we got there, she walked in among the ribs, and picked a spot, and took a long time getting down."] = { "edce9ef6f8c6", 11.39 },
		["Four days. We didn't camp that night. We walked until we hit the road, and nobody sat down, not even to fix a boot."] = { "5ef8fc104869", 9.17 },
		["From anywhere in Un'Goro Crater you can see Fire Plume Ridge, smoking away in the middle of everything, with the jungle growing right up its sides."] = { "5f2758a318e8", 9.12 },
		["Funny how far you can walk, and find you've brought somebody with you."] = { "8328b57d3b00", 4.62 },
		["Gather round, everyone. I've got one for you."] = { "b1efdaf39ab7", 3.13 },
		["Gnomes built that tram. It breaks down twice a week. Nobody has had the heart to tell the couples."] = { "a3c71fcb6822", 7.39 },
		["Good for the skin, he told me. And I've got to admit it, I came out glowing. I came out with something else too, on my leg, and it's still with me."] = { "c5ea18c4301a", 9.82 },
		["Grom Hellscream of the Warsong clan drank first. The blood made the orcs strong. It also filled them with a rage that wasn't theirs."] = { "83c471ff8476", 9.77 },
		["Groundfolk think of wind as weather. To us it's a neighbor. Sometimes kindly, sometimes drunk, and always in your business."] = { "5a8bbd60f938", 9.06 },
		["Guess what was in the next field. A hundred and forty sheep. We stood at the fence for an hour. They all looked equally disappointed in me."] = { "27f8ab34c982", 9.59 },
		["Half a mile. Arrows in the reeds. You can hear them laughing, that high laugh, and it's getting closer."] = { "849dd667bfec", 7.16 },
		["Halfway there, the crate asked me very politely whether I'd ever wanted to be rich."] = { "edf37d926c19", 5.07 },
		["Halfway through my best one, the one about the fish, he stopped the horses and offered me a full refund."] = { "52d9ddfaa763", 6.56 },
		["Hands don't retire. Nobody tells you that. You can walk away from all of it, and your fingers will go on working without you."] = { "6d6607d5f505", 8.7 },
		["Harvest day at a mill, a boy chasing a ball slipped into the millrace. The water was carrying him straight toward the wheel."] = { "932f356ab367", 8.2 },
		["Have you ever seen the Darkmoon Faire arrive? Nobody has. I tried once."] = { "69274b6186b3", 6.14 },
		["Have you seen the bridges in Thunder Bluff? Rope and plank, between mesas, with nothing beneath them but a lot of weather."] = { "88eca87a555e", 8.83 },
		["He asked me what it was feeding on. I gave him six clever answers. He shook his head at every one."] = { "4ea2554b2caa", 6.79 },
		["He ate with us and laughed with us. By dawn he was gone, and so were our horses, our water, and the youngest of the watch."] = { "4cf81b0ab96e", 8.41 },
		["He blamed the night elves for much of it. But a people must deal with its own evil, he said, and his was Ran Bloodtooth, whose mind was no longer his own."] = { "7810704b2cb4", 10.5 },
		["He came home a man, and the city was built again, stone by stone. Varian at least knew his father was gone. This boy doesn't even get that."] = { "c912ede6677d", 9.9 },
		["He came to see me last week, gray around the tusks. He wanted to know if I'd ever heard of anything that knocks up through a floor."] = { "c9d3e9b539a6", 7.68 },
		["He charges by the minute to lean on one. I've seen grown miners cry. I've paid him twice, and I swear it does feel cooler."] = { "ca59f979146c", 8.93 },
		["He clapped me on the back and said it was marvelous. He gave me a copper, and asked if I did birthdays."] = { "2437fd19d96d", 6.56 },
		["He comes back with bits of armor. A helm, a buckle, half a gauntlet. They come up out of the sand on their own, he told me, after every big wind."] = { "cf14020995e9", 11.08 },
		["He comes every spring now, always with a different onion, and says it's the same spirit. I've read less persuasive theology from my betters."] = { "8daf5bd7b296", 9.59 },
		["He did not come back. And every child in our camp lived to see the rain."] = { "9c7dab77bd08", 4.94 },
		["He did not come back. Lothar was the closest thing to a father Varian had left. When Varian had a son, he gave the boy that name."] = { "9a38fa9e52f2", 9.35 },
		["He didn't even look at me. \"Ye don't know that,\" he said, and went on ringing."] = { "8d012ff3bc1d", 5.17 },
		["He didn't finish. There were a lot left when he died. We burned what remained along with him, and no pup in our camp has begged to touch a cord since."] = { "109f5a664e3d", 10.37 },
		["He didn't say anything. He just looked at me. I got my coat."] = { "d62857e75b01", 5.07 },
		["He didn't say whose it was. He only brushed the dust off it, the way you'd straighten a collar, and walked on."] = { "eaedb2f867a0", 7.5 },
		["He doesn't like you, the handler told me. I laughed and asked how you could possibly tell. He told me I'd find out."] = { "cbc9054525a3", 7.73 },
		["He drove his axe into Mannoroth with everything he had left. The demon died, and the curse in the orcs' blood died with him."] = { "d7bc7bd05082", 8.23 },
		["He gave two coppers to the poor box, so I blessed the onion. He won the wager."] = { "dcd2d7b86fb7", 5.77 },
		["He got rid of the boat. Then he moved inland, as far from the sea as a troll can go. Bone dry out there. Nothing but dust and scrub for miles."] = { "dcae481bcb64", 10.29 },
		["He got very excited and offered me a whole silver for it. I held out for two. We shook on it."] = { "efb95d7ddc47", 7.03 },
		["He grabs my arm and says, the goat. It was the goat all along! He laughs till he cries, turns around, and walks back into the dark."] = { "501c313648b0", 9.48 },
		["He had a son. Taelan. Just a boy when his father was cast out. Tirion stayed close all those years, watching him grow up from a distance."] = { "dba9a08c833b", 10.66 },
		["He had a succubus at his side and called up voidwalkers when he could. They say it was a hard fight. But his tome came back to Maestra's Post."] = { "63d2669d7139", 9.46 },
		["He had the best orchard for miles, and I thought that was a lucky accident until I was much older."] = { "91f8875c4262", 5.77 },
		["He had the cloak, beautifully mended, and a bill with interest. His grandmother had also lost a large bet with the whole street that I was dead."] = { "0e734597ec0c", 8.93 },
		["He had this same scar, you know. I didn't think about it until later. Now and then I catch myself packing for Tanaris. I know exactly what I have to say."] = { "30a6e98da240", 10.89 },
		["He handed me a lovely sketch. It was me, looking annoyed, standing next to a very accurate rock."] = { "51280d29c94e", 7.5 },
		["He held his son, and swore over him that this would not go unanswered. The Silver Hand would rise again. And from that day Tirion Fordring was its Highlord."] = { "804e44d7339f", 10.79 },
		["He kept it on his belt for the rest of his life. He never did learn how to smile right. He didn't need to, after that."] = { "a57fc7c3abef", 7.81 },
		["He kicked it apart without a word and left me a heap no bigger than a hat."] = { "26ac5dc407da", 4.39 },
		["He killed Cenarius. He killed sentinels defending their own forest."] = { "15ed290f96ee", 4.88 },
		["He knew every one by name. He'd check their wings and scold them for being late. I've seen mothers be less gentle."] = { "0ba3c3081591", 7.68 },
		["He laughed until he coughed. Then he said, pup, I've run from a hundred fights. That's why you get to hear me say this."] = { "d43b2c42b149", 8.46 },
		["He leaned down and said, what's the password? And I stood there, thinking fast, with no plan at all. So I said, password."] = { "c63c8bd50a66", 10.19 },
		["He looked at it and asked why his collar was crooked. I pointed at his collar. He fixed it, and I fixed the picture."] = { "e828d28dc437", 7.21 },
		["He looked at me, went pale, and shouted into the back room. \"It's true! Grandmother, the customer came back!\" Forty-one years, it had been."] = { "a4e1ac1ad9b3", 10.92 },
		["He looked out at the desert, and it went on farther than I could see. Then he picked up his sack and asked me if I wanted to come along tomorrow."] = { "fd5f2cac187f", 8.8 },
		["He mended it himself, with big ugly stitches. When anyone asks about that war, he shows them the stitches first."] = { "efe708d83360", 8.46 },
		["He moved away that winter, though. Because the next dawn, every scarecrow in the valley was facing his house."] = { "b78bd842682d", 7.44 },
		["He nodded at the dust and the rocks. Nothing here lies to you, he said. When this land wants to kill you, it tells you up front."] = { "ed0c2e7a0744", 9.46 },
		["He offered to hold a spot for me. And I'm told that he did, for a while. I got a very polite letter about it."] = { "d5b9099e250f", 8.33 },
		["He paid me back that week, every copper. He said it seemed only fair, given what I'd been willing to do to collect."] = { "648639ae679b", 7.99 },
		["He paid me, thanked me, and walked off without the portrait. I'm told he's courting now."] = { "de3942799441", 7.26 },
		["He planted it, though. Out of spite, I think. Twelve years on, his springs run all summer. He tells everyone a shaman made it rain. I let him."] = { "060f8649b592", 10.89 },
		["He pointed. One arm went left, one went right, and a third went up toward the ceiling, and I swear he gave it real thought."] = { "b9ec588045c5", 8.8 },
		["He poured one ladle on the ground at each, and went on. Nobody told him to. I still do it, when I drink alone."] = { "4d5ade4d7b56", 8.83 },
		["He put one candle on it. Then he charged me for three, because three was the smallest box he sold."] = { "dc45b5d345a3", 6.9 },
		["He read the letter and frowned. He'd been fighting those cultists at Ordil'Aran, and he thought one of them carried a soul gem that held the secret of their power."] = { "0ddf31db6a47", 10 },
		["He refused. He was angry that she had made him bleed for every mile."] = { "7edfcb10298d", 4.86 },
		["He rode in on his horse Mercutio and marched to the keep with a crowd behind him. He told the boy king Anduin to run, then faced Lady Prestor. She laughed and called it treason."] = { "ea8eb5f2dff6", 12.46 },
		["He said a big fire, everyone stands back from. A small one, they have to sit close."] = { "48a4537ef072", 6.61 },
		["He said an empty chair isn't a missing person. It's a promise there's still room for them."] = { "301ab37271cf", 5.64 },
		["He said he had heard ordinary talk through the dome. Someone asking about supper. He had liked to stop and listen."] = { "4f827774889a", 7.5 },
		["He said if he stopped for a week, the locks would seize, and then it would take a smith and a hammer to open them."] = { "4bcd54609422", 6.71 },
		["He said it had turned cold. I said he could have asked. He asked how he was supposed to pick me out from all the fish."] = { "d8d5a8ccdab4", 7.68 },
		["He said it sharper the second time. By the third, he was waiting for what most people do next, which is give up and call him friend."] = { "0af9970a720b", 8.8 },
		["He said only one person needed to know, and fast. His master, a paladin, a long way south."] = { "905018a318f2", 7.44 },
		["He said that was definitely worth two silver. I've never seen anyone so happy to be bleeding."] = { "1ef45ee78412", 6.43 },
		["He said, \"So I have! Well, now I can see the right one much better.\""] = { "7d9240b31796", 5.72 },
		["He said, I sharpen them out every night. I won't carry those fellows around with me. Some nights I wish I'd learned that sooner."] = { "a65a7faa1b8e", 8.8 },
		["He said, the road my grandchildren will walk. Then he pressed a coin into my hand and was gone."] = { "c61bd98002d7", 7.16 },
		["He said, there's nothing here. It's mud and fog and rain, and there's nothing here to look at. So what does a person think about, walking through it?"] = { "9d7741cda77a", 10.42 },
		["He sat down in the ash and had himself a think. And the next week he was back in business, with the empty crates all stamped ONCE HELD ICE."] = { "b2f5c09daf73", 9.04 },
		["He sat down in the middle of the lane like a big, confused dog. The farmer came running, far more worried about the bull than about any of us."] = { "8a1b790ca358", 8.8 },
		["He saw me looking, and he looked at me until I walked on. I never told anyone at home, because I don't think they'd know what to do with it."] = { "2e07d7aa9dda", 8.46 },
		["He sent it the winter he marched out. It arrived the week after the letter that said he wouldn't be coming home."] = { "39ba05200ad3", 6.56 },
		["He showed me his newest find. Not a beast. A boot, a good leather one, with a buckle, and a little of the traveler still in it."] = { "534fa871b83a", 9.9 },
		["He showed me his own, then crouched, knees cracking, and showed me a small crooked one by the ground. A child could have reached it."] = { "7e47eec7dc47", 8.46 },
		["He smiled the kind of smile that tells you he's already counting."] = { "c1c493f538ef", 3.5 },
		["He sniffed me for a long time. Then he let out a big sigh, and lay down across my foot the way he always had. I can't feel that foot. I stayed until dark."] = { "6347d26b31d1", 11.73 },
		["He sniffed me. He got a second one to come and sniff me. They talked it over, and then I was carried down a tunnel, not roughly, and put in a tub."] = { "a43759074488", 10.24 },
		["He still comes out with me every morning. It takes a while. I find him a sunny place under a tree, and he watches the woods like he's in charge."] = { "0d75e1eaea2b", 9.17 },
		["He still couldn't cook, mind you."] = { "237443e25546", 2.01 },
		["He still counts every night. He still stops at six, and stands there a while with the torch, before he lets them close the gate."] = { "e30a48bd8751", 7.97 },
		["He stirred the pot for a while. Well, he said, that depends on the boar. Then he asked if I wanted the part with the extra leg, as it's the most tender."] = { "7a0fc5a106c3", 10.06 },
		["He stopped in the middle of his sentence. Forty years he had lived under that roof, and he had never been on top of it. He sat down. He didn't say anything else."] = { "0edbdd555a6a", 10.32 },
		["He swore it was lucky. It could tell fortunes, he said, if you asked it nicely."] = { "8eba3d038bce", 5.36 },
		["He talked about the door for some time. How old it was. How huge. How nobody was sure who could have built it, or how anyone ever opened it."] = { "7dfc30dfd4c9", 10.42 },
		["He tells himself he miscounted. A few nights later, he starts to wonder about the cook. About his brother, who came to dinner and looked at the spoons."] = { "c928df52f3f2", 9.77 },
		["He thought about it and said, \"Since I got lost.\" Then he walked back out across the marsh. I looked at the mud behind me, and the only prints in it were mine."] = { "7ad5f649661d", 10.89 },
		["He thought about that for a long time. I could hear it happening. And then he stood aside and opened the gate."] = { "6234b62f8aa3", 6.97 },
		["He thought about that for a long time. Then he agreed, and charged me for the potatoes."] = { "5828ed2b373c", 6.71 },
		["He told me it was his. Its name was Tiny. It does that to everyone, he said. It likes the company."] = { "2b7925d8e7ac", 7.68 },
		["He told me the whole town sends strangers that way at harvest. It keeps the inn from filling up."] = { "2853acd2feb5", 5.96 },
		["He told them he'd lived on dreams of his father for years. He was done dreaming. Take me to him, he said. And the guards of Hearthglen heard every word."] = { "3b4ed6c05d58", 10.66 },
		["He took a pinch of dirt and showed me how black it was. Where do you think all this came from? he asked. It's the best soil in the world. The fire made it."] = { "9eb1751172c5", 11.39 },
		["He took some time over that. Then he took a small dried flower out of his coat, and it was from some meadow, from home, I suppose. He looked at it, and put it back."] = { "72e11f4b81f6", 11.21 },
		["He took the pole back without a word and leaned on it gently. The ferry slid forward, straight as a road."] = { "685a4a67d893", 7.68 },
		["He tucked the earth back down and patted it, then went to see who else was up."] = { "6fd16a8acd65", 4.47 },
		["He turned his back to it and rowed with his eyes on his feet. Birds went around that mountain, not over it. I noticed that after a while."] = { "f1aa24417ed5", 9.64 },
		["He turned it back and blamed the wind. Next morning, a little further. Day by day, it came around."] = { "01dcc317824d", 7.31 },
		["He turned it over and said, this will never be a good shoe. Then he heated it, gave it three taps, and handed it back."] = { "42b0f510677d", 8.1 },
		["He wakes up, and he finds it. And he looks at me like, did you see that? Did you see what I found?"] = { "0693d169d5c8", 6.84 },
		["He walked straight up to an old woman's gate, where a bucket of oats was waiting. She looked up and said, \"You're quiet tonight.\""] = { "81cd4c138772", 8.1 },
		["He was furious. He'd dropped his trowel, and he wanted to know why I hadn't caught that too."] = { "bf9d874d2e2f", 6.11 },
		["He was not joking."] = { "0b6c24ddd3c1", 1.52 },
		["He was taking the point off one spike. Only one, the lowest on the rail, right at the height of a small child's head."] = { "b31fba02d358", 8.28 },
		["He was terrible at it. Children ran from him. He'd stand at the gate and smile at people as if he were about to arrest them."] = { "a00e9697e21f", 8.57 },
		["He was very happy with it. He had the other one on underneath."] = { "3107fe4d40b8", 4.05 },
		["He wasn't. He was Tirion Fordring, once Lord of Mardenholde and a paladin of the Silver Hand. Stripped of it all at a trial in Stratholme and sent into exile, for defending an orc who saved his life."] = { "f16c766a5fbf", 13.43 },
		["He wasn't. He was untying them. He'd say something under his breath, a description, a face, and then he'd work the knot loose. It took him days, each one."] = { "f9b9b2f05822", 11.02 },
		["He went down those steps with a borrowed shield, and he held them longer than any of us. Longer than I'd have believed."] = { "f7354711496e", 7.68 },
		["He went in his sleep, one clear night in spring. I went up and rang it anyway. Just in case he needed to find his way somewhere."] = { "88e0da942123", 8.88 },
		["He woke up, caught the rope, and tied it off half asleep. We hauled him in. He swore he'd had a dream about a flying boot."] = { "84e03930633c", 8.83 },
		["He wrote it in the ledger just the same as the old bones. Name unknown. Came a long way. He said the tar doesn't care what age you come from."] = { "6193fc89a2b3", 10.74 },
		["He wrote that she had mocked and betrayed him. She'd done neither. She had just never thought of him the way he thought of her."] = { "689f02421841", 7.26 },
		["He'd asked her to, she said. His hand still went looking for that pocket all day long. He liked it to find a flower instead."] = { "066355690acc", 8.65 },
		["He'd gone hunting for a gem. The gem was meant to power a rod, made long ago by a wizard named Dartol. An evil man, and long dead, but his rod might slow the furbolg raids."] = { "9e403958b681", 13.9 },
		["He'd had those books by heart for forty years, every word. He had never needed them read to him at all. Nobody needed those evenings but me."] = { "cb7f5b2e4b28", 9.3 },
		["He'd hidden it after the trial, so no one would see it. Behind another painting, one of the twin moons, deep in the Scarlet Bastion of Stratholme. Someone had to fight their way in to bring it out."] = { "1ab3865d14dc", 13.24 },
		["He'd lost a finger to a scorpid, and he seemed fond of the scorpid. He was in no hurry to answer. Nobody out there is."] = { "5436e6a30136", 8.46 },
		["He'd only shake his head and say the bees live in it."] = { "a8b70d04297f", 3.27 },
		["He's an old man now, with a bad knee and more grandchildren than he can name. One day each year, I go to his town and buy something at the stall across the square from his door, so I can see him."] = { "513d7276de0c", 13.3 },
		["He's been gone for four winters now. Somebody has to keep it up."] = { "ac72c773b6c3", 4.39 },
		["He's done it every morning for twenty years. Says it's opened twice. He won't say what was inside, but he hasn't paid for a drink since."] = { "d75f30d225ae", 9.3 },
		["He's got them stacked behind the hold in long, neat rows. No two alike, from every side and every age. I asked what he'd do when he'd collected them all."] = { "4d22ec1b30fd", 10.89 },
		["He's never paid out a single refund. Everyone who asked for one was introduced to him."] = { "72d1abec5204", 5.77 },
		["Heard of the Greench? A big green beast up in the Alterac snow that hates Winter Veil."] = { "4339f84aeabe", 5.96 },
		["Her father, she said. That's when I understood. She hadn't dared let it run, because whatever was left in that spring was the last of his winding."] = { "6d60194f9a4e", 10.24 },
		["Her granddaughter lived. But they say that pale girl still rises whenever someone opens something of his. I don't think she's angry. I think she's waiting for someone to tell her it wasn't her fault."] = { "0ed5b81ae7d9", 13.01 },
		["Here's one I heard in a tavern years ago, and I've never forgotten it."] = { "2fec892eb3ee", 4.23 },
		["Here's the thing every young one gets wrong the first time they walk the cliff paths in a real crosswind. Everything in your body tells you to lean away from it."] = { "5eaffe6a8a9a", 9.64 },
		["High up in Redridge I met a lookout who'd tended a signal fire for six years. His job was to light it if he saw raiders, so the next tower could pass the word."] = { "8166e976dba2", 10.42 },
		["His Warchief, Thrall, caught him, and with a human sorceress's help they burned the demon's hold out of him. Then the two of them went looking for Mannoroth."] = { "fd699d99277e", 9.59 },
		["His cart was stuck in the mud. His pony was panicking. And the water was already over the wheels."] = { "dd48ea43b9b6", 6.97 },
		["His name was Eitrigg. He was tired of war. He had walked away from it. They fought anyway."] = { "84d44a52f49a", 6.79 },
		["His wife used to read on that bank while he fished. He said a man can't just sit by a lake staring at nothing. People would worry."] = { "4725d3739cb6", 9.04 },
		["Hob claimed the front half and did all the feeding. I'll let you work out what that left me to deal with."] = { "4c4dd83631d6", 6.37 },
		["Hold on to your people, friends. That's all I've got."] = { "586eee14f446", 3.55 },
		["Honor is knowing what you'd die for, he told me, and refusing to die for anything less. I've kept that with me."] = { "4a543dd33254", 8.15 },
		["Hoofprints. But they started in the middle of the field, in fresh snow, with nothing leading up to them. As if something had come down out of the sky."] = { "20e8bb8fba25", 9.95 },
		["Hot pipe under my left hand, spinning teeth to the right. I got the wrench on the bleed valve and it sheared. So I hit the boiler plate until something gave."] = { "930ad206fbb1", 10.55 },
		["Humans who had fled across the sea, under Jaina Proudmoore. Orcs, under Thrall. Night elves, under Tyrande Whisperwind."] = { "74a7518272ae", 9.35 },
		["Hunters in Winterspring say if you camp alone above Everlook, you'll wake to find your name written in the snow outside your tent. Spelled right."] = { "01b05db80706", 9.3 },
		["I always did. I make a great fuss. I'll keep making it for as long as there's a morning."] = { "d199c6e50db1", 6.37 },
		["I am not. But I'll take it."] = { "53b04011dcc5", 2.53 },
		["I argued that most of it was fish, and fish live in the river, so they ought to travel free."] = { "639d39b682af", 6.01 },
		["I argued until he gave me the other two. We ended up eating the cake together, behind his counter."] = { "7851f9079cc3", 6.61 },
		["I ask them if they're the same at home, at market, and at their mother's. They always go quiet."] = { "624d3e7e765a", 6.19 },
		["I asked a farmer once what the weather would be. He looked at me as if I'd asked him the price of the moon."] = { "2674dbff8123", 6.53 },
		["I asked a gardener about her. He said she'd been sitting there every evening since the Temple Gardens were planted."] = { "483ccebdb66f", 6.53 },
		["I asked a sailor what the word for dry was. He had to think. He called over a friend, and they had a long talk."] = { "454cfffa9481", 7.92 },
		["I asked a tall, pale fellow with a shovel how far it was to the nearest safe place to sleep. He looked me up and down, very slowly."] = { "a281faafd191", 9.22 },
		["I asked about it down at the fire. Somebody told me, in a low voice, that his son fell from the old bridge that used to hang there. He built this one the spring after."] = { "999a971f4823", 10.89 },
		["I asked again, louder, with feeling. An old miner walked over, handed me a hammer, and pointed at a thin white seam in the rock."] = { "94b5ee30281d", 9.87 },
		["I asked an old hand at Marshal's Refuge if it worried him. All this green and all these flowers, and this huge thing that could go up at any time."] = { "50119c4b74d0", 9.4 },
		["I asked an old-timer at Razor Hill why anyone would choose to live in Durotar. The plants have thorns. The bugs have stingers. The sun has a grudge."] = { "5f3e7e765f53", 10.66 },
		["I asked at four inns. Three looked at me like I'd lost my wits. The fourth asked who sent me, and I've been trying to think of an answer ever since."] = { "5340a39bc566", 9.87 },
		["I asked her once if the thanks made any difference to the animal. She said, no, child. It makes a difference to you."] = { "dee4c8db7b91", 8.05 },
		["I asked her once why she doesn't open it. She said as long as it's wrapped, he's still got one more thing to say to her."] = { "51138b710445", 7.97 },
		["I asked her what I'd done there. It took her some time to answer, and she told me without blinking. I thanked her."] = { "00c6b0abba8c", 7.5 },
		["I asked her why once. She said everyone's somebody's child, it's late, and you can't tell the rest by looking."] = { "c6e4a7020f91", 7.92 },
		["I asked her why, around the ninth month, in what was not my most respectful voice."] = { "8054a5120b4f", 5.77 },
		["I asked her, when I came back through, why she hadn't explained. She said people don't believe you until they've needed it."] = { "30d1f2a064fe", 7.68 },
		["I asked him afterward how he'd done it. He said he had spent thirty years telling armed people no."] = { "560e9f6f8c10", 6.66 },
		["I asked him to say it slowly, and said it back to him until I had it. It took a while. He sold a lot of things while I stood there."] = { "eeb397d7a5fc", 8.8 },
		["I asked how he did it. He said I was pushing against the river. He was pushing against the bottom. The river was going where he wanted anyway."] = { "efde4e9e7056", 9.04 },
		["I asked how long he'd been there, and he told me. I asked if he ever got tired of it, staring at a place where nothing will ever grow."] = { "0f36bcc6eaf6", 8.57 },
		["I asked how old the newest one was. He said he'd cut it that spring. He was eighty, easily, and his hands shook."] = { "329cf96cab5a", 8.46 },
		["I asked how she could stand to do it. She pointed out how thick and green the grass was on that slope, compared to all the others."] = { "f3c33d14058d", 8.46 },
		["I asked how she knew when it was right. She tapped it against the anvil and listened. A good blade rings. A brittle one clicks."] = { "bc819032f51a", 9.12 },
		["I asked how she stayed so cheerful, with a shelf like that. She said a failure is the only thing you ever really get to keep."] = { "0a508b77e19d", 8.15 },
		["I asked how you can tell. Easy, she said. Ask how far they've come. The first kind tells you the miles. The second changes the subject."] = { "fe3cbfaf3fa8", 9.9 },
		["I asked how. They all looked the same to me. Gray, wet, and very discouraging."] = { "f43645d619a7", 6.71 },
		["I asked if anyone had ever answered it. He said his grandfather did, once. Knocked four back, for a laugh."] = { "9bcb6dc754f2", 7.86 },
		["I asked if he wasn't afraid. He said he'd buried most of them himself. They weren't wicked, he said. They'd only forgotten where they live."] = { "b6ed4f5bcac0", 9.12 },
		["I asked if it changed what she knew about the place. She said no, not a thing."] = { "e0eaa8a6c294", 5.9 },
		["I asked if it would get me where I was going. She said, did the last one?"] = { "2742dd625ff7", 5.28 },
		["I asked if she always got her coats back. Nearly always, she said. But her favorite never came back. It's been going up and down the coast for two years now."] = { "6d59e4cc9c2b", 10.08 },
		["I asked if they'd seen the lake. Oh, yes, one of them said. That's why we came out here, twenty years back. Then she poured me more water."] = { "a96f0c703ea1", 10.74 },
		["I asked it nicely for three days. It told me nothing. Then it ate my best fishing lure."] = { "d5d19863c19c", 6.43 },
		["I asked the baker next door. She said the old clockmaker who had it never once missed opening, and he wasn't about to start now."] = { "531554d14970", 8.39 },
		["I asked the locals whose it was. I got four answers from four people. A giant, a god, a demon, a very old mistake."] = { "daf7f9ed1056", 9.9 },
		["I asked what happens if you don't pay up. The keeper pointed at a very clean spot on the wall, and asked if I'd like another round."] = { "f914e66357e2", 8.46 },
		["I asked what he meant by changed. How many eyes are we talking about, I said, just out of interest."] = { "70b34b4ac805", 6.79 },
		["I asked what she was making. A chair, she said. It would need two hundred years, give or take, and she'd be back to adjust it every spring."] = { "7790855493f6", 9.48 },
		["I asked what the point was. She said the stone knows. And so does the next mason who takes that wall apart, a hundred years from now."] = { "c7f77af1d865", 8.99 },
		["I asked what was up there. He said he didn't know, and that he intended to keep on not knowing. He'd known some folk who found out."] = { "6eedf3f3536f", 9.12 },
		["I asked what would happen if he didn't. He said he couldn't say. The fellow who could was the one who used to run the place."] = { "794bb27d86c1", 7.55 },
		["I asked whether he missed it now the barrier was down. He said he still heard the talk if he stood in the right place."] = { "a8ae8f3af37b", 7.44 },
		["I asked why anyone would do that. She said it was the only place on those stairs where people looked down at their feet."] = { "291431cfea77", 7.31 },
		["I asked why he bothered, since he had no shortage of other things to do. He looked around at the dripping walls."] = { "1f884b5dba06", 7.63 },
		["I asked why he bothered. He said people leave meaning to come home, and someone ought to keep count of it."] = { "e4fa94124ec5", 7.21 },
		["I asked why he bothered. The sand would just blow back in by noon. He agreed it would."] = { "cb430678652d", 6.53 },
		["I asked why not. The guide looked over at that lovely clear line and said, they know who lives there. We kept to the trail."] = { "de3857e159e2", 9.72 },
		["I asked why. Wasn't once enough? She said once makes it hard. Twice makes it hard and keeps it from shattering."] = { "2f3d3b599daa", 9.3 },
		["I ate better that month than any month in my life. I've never been so ashamed of a full stomach."] = { "6c36bc6860e4", 6.32 },
		["I blew my lantern out. The green one kept going for a while. I sat on that plank in the dark until morning."] = { "616bf562a345", 7.92 },
		["I bloom by the roads of the young, gentle land. What am I?"] = { "3e8e04136b76", 4.75 },
		["I bloom where the land has been burned to the bone,"] = { "c90ae7210c94", 3.32 },
		["I bought a retired courier's mare, cheap. Sweet old thing, with one fault. She stopped at every door on her old route and would not budge."] = { "d94b178febb1", 10.32 },
		["I bought a secondhand lantern from a peddler outside Dalaran. He said one word to it, very quietly, and it lit up a lovely soft blue."] = { "b5c9d591e1ca", 9.82 },
		["I bought a walking staff in Feralas from a woodcarver, good straight wood. After the first rain, a little leaf sprouted from the handle."] = { "3dbe0432820b", 9.48 },
		["I bought a wooden practice sword in Lakeshire. The seller swore it would survive anything an apprentice could do to it."] = { "e5612276345c", 7.26 },
		["I bought all three at the next market. Don't ask me why. I've asked in every town since, and nobody knows that handwriting."] = { "125792d62f56", 8.33 },
		["I bought it anyway, because a man that truthful surely had to be joking."] = { "fcea1abca8dc", 4.75 },
		["I bought the cheapest candles in Darkshire. The seller warned me they smoked. I said I only needed them to see by."] = { "44eb955f89cd", 7.68 },
		["I bricked over that cellar myself, that same week. It's back in its corner now. It does as it's told."] = { "ad92da6e3dec", 8.15 },
		["I bring the arrows and the plan. It brings the teeth, and judges the plan, and generally improves on it."] = { "191b78209e8d", 7.16 },
		["I broke all three in one week. I have the scars, the debts, and a very frightening landlord to show for it."] = { "ee96845f8061", 7.58 },
		["I broke it on the first swing."] = { "064837a71c39", 2.01 },
		["I brought both pieces back for a refund. He looked at them and said I was clearly no apprentice, so the promise didn't apply."] = { "049c2cb869e0", 7.97 },
		["I burned the copies in the end. I can draw that mark perfectly now, but only with my eyes closed."] = { "4f8b8e841344", 7.13 },
		["I called and called on the spirits, and nothing came. I asked her why it was so empty."] = { "3302ee3d808f", 6.19 },
		["I called her cruel, to her face. She said, the day you lose that arm, you will not have time to start learning."] = { "cb38a5217e8a", 8.2 },
		["I called it down and walked in. Up the ladder, a child under each arm, down again, and out, saying the words the whole way. I reached the last line at the door."] = { "f0674b860761", 12.59 },
		["I called it up in the middle of the road. It filled the road. The bandits shot at it, then tried to walk round it, and found out there wasn't any round."] = { "f4df5b1fc259", 9.72 },
		["I called out, quite a few times. The jungle doesn't echo. It just takes your voice and keeps it. So I sat down to wait, and found a journal by the fire."] = { "0253f1e5c0d8", 10.79 },
		["I came back every day. I watered it, talked to it, moved it into the sun. It didn't grow any faster for any of it."] = { "fd7843d85ef4", 8.1 },
		["I came back in the morning, in my good robe, to buy their traps. They let them go quite cheaply. Nobody would look me in the eye."] = { "fd755c49af67", 8.57 },
		["I came to Mulgore angry once. Someone had wronged me, and I'd walked a long way, planning what I'd say to them."] = { "3400dcf4a979", 7.44 },
		["I came to the gates of Dire Maul, deep in the green of Feralas, because somebody told me there was treasure. There was an ogre on the door, and he had a very big club."] = { "2bf11f1d71ad", 10.74 },
		["I came up on the far bank behind them, while they were leaning over the edge looking for a body. I tapped the nearest one on the shoulder, dripping. Kept all my boots, too."] = { "06e29915d8b3", 11.21 },
		["I camped there anyway. I counted the stones at sundown, for no reason. I do that, I count things. There were eight."] = { "d048b6d61d38", 9.53 },
		["I can tell you about every day of this one."] = { "b41c6da644a3", 2.56 },
		["I can't say when it started. I've been gone from her table for more than half my life."] = { "3d91ce302401", 5.49 },
		["I can't sit in a room with a person who taps their fingers. I know it's not their fault. I just get up and leave."] = { "c336f2fecee2", 7.26 },
		["I can't stay anywhere long where the air is still. It feels as though the whole world is holding its breath."] = { "89ece364985c", 7.03 },
		["I can't tell you a thing about that day. I could draw you that crow."] = { "db4feba1893f", 4.75 },
		["I can't tell you what it was. I've heard people make all kinds of explanations, and I don't argue."] = { "9be958b1a260", 6.19 },
		["I carried it a mile down the road and I left it there. It beat me back to camp. I gave up after the third time, and I'll admit I got fond of it."] = { "4a9effea1ee5", 10.29 },
		["I carried it for years. I think I wanted it to be a secret plan, or a great love. Something that would make all of it mean more."] = { "8e6df6bdd833", 9.22 },
		["I carried it there myself, a month's ride. The brother read it twice, and then went out to look at the fence."] = { "d3edde08361e", 7.31 },
		["I carried it to Light's Hope Chapel to be sent on. They asked if I wanted to add a note. I couldn't think what I'd say."] = { "735f86596c40", 8.52 },
		["I carry a rope like that now, when I'm leading. I've never once had to climb with it."] = { "b54c1bc3c0b1", 5.88 },
		["I chased that seller for a month and never caught them. Mostly because I was on foot, very slow, and hatless."] = { "5958eda5bfb7", 7.58 },
		["I climbed down soaked and shaking, with leaves in my teeth. It gave me a look of deep contentment, and it sneezed again."] = { "99935cba98b4", 8.39 },
		["I climbed down to Frostfire Hot Springs in Winterspring, half frozen, in the middle of a snowfall. There were already two others in the water."] = { "f27c02e01fb2", 9.64 },
		["I closed it up, and told her it was a very delicate mechanism and best kept still. It's the only lie I've ever told about a machine."] = { "a74372d3ed9b", 8.8 },
		["I cooked for a week. On the last night, a very hungry stranger read the sign. I've never been so happy to lose."] = { "d9db10d2c785", 8.93 },
		["I could have sent for his sister. Instead I got out my pen. I'm not proud of it. I did check his work."] = { "7ecbe563f8ea", 7.63 },
		["I could name every face I looked at. So I named them, one by one, in my head. And I only ever got to six."] = { "8a1eaf9a21ee", 8.2 },
		["I could see the far ridge. I could see a nice clear line straight to it. So I asked why we couldn't just walk straight there."] = { "9c2198712919", 8.75 },
		["I could smell stew. I told myself that I was hungry, and that was all it was. Then behind me, I heard the creak of a door, where there isn't one any more."] = { "2fea183a72b8", 10.84 },
		["I could've melted it down. I keep it instead. Whenever someone offers me a very good deal, I take it out and have a long look at that old king's face."] = { "bfb6b9f975a6", 9.9 },
		["I couldn't outrun that water, and I couldn't swim it. But there was a fence along the bank, and fence rails come loose if you want them badly enough."] = { "e4d7e046fcec", 9.04 },
		["I couldn't reach her. But I could reach the lever that switched the chute to the other track. I pulled it with both hands and my whole body."] = { "b0ecf8ec6cd3", 8.46 },
		["I couldn't sit on it, so I used it to hold my sewing bowl. It was exactly the right height to keep the thread out of my supper."] = { "1c50c44638c0", 8.46 },
		["I couldn't stop a wagon that size. But I could turn it. I caught the tongue as it swung past, threw my whole weight on it, and steered it into the ditch."] = { "c3f3086a5350", 10.08 },
		["I counted, for something to do. I got to ninety before the trees closed in again."] = { "1e126f124e18", 6.01 },
		["I crossed the woods of Ashenvale at night, which was my first mistake. An arrow hit the ground an inch from my left boot. No sound. It was just there."] = { "5d3a8dcc5afe", 10.24 },
		["I cut the pony loose and swam it to the far bank with the rope. Then we tied it to a tree and hauled the cart across, one heave at a time."] = { "2bec575e66e2", 9.04 },
		["I danced at her wedding. I held her first grandchild. She kept getting smaller, and I kept looking exactly the same, and she teased me for it."] = { "60db267ac924", 10.29 },
		["I did my washing in the Alterac Mountains once, in a stream below the old ruins, and hung three shirts on a cord between two rocks."] = { "aad12d091caf", 8.33 },
		["I did that road for four years, and I made more from silence than I ever did from fruit. Good apples, too. It's a shame about the hills."] = { "f3e679d7b3b2", 9.82 },
		["I did the mule. I'm not proud of it, but nobody ever lost that animal on a dark road."] = { "eeff10472df0", 6.14 },
		["I did the sums out loud. At her pace, she would never see that valley green again. Not in her whole life."] = { "7856f163de31", 8.05 },
		["I didn't carry it over. I split it with my knife and swung it round by the neck, spraying a line across the floor like sowing seed."] = { "e782b10ad278", 8.93 },
		["I didn't catch the word. I paid anyway, thinking how hard can it be, and spent the whole evening trying every word I knew on it."] = { "0515b40bd79c", 8.88 },
		["I didn't cough again until I was well out of Deadwind Pass. I held it in for two days."] = { "dbae21b69137", 6.14 },
		["I didn't feed her. We don't. That isn't how it's done. I'd have told you I understood all that. I've taught it to others."] = { "1ccdc9f8be18", 8.99 },
		["I didn't have water. I had a cloak, and the sentinel beside me had a shield. That would have to do."] = { "20ae822ef3e2", 7.16 },
		["I didn't jump so much as refuse to stop. I hit the far side with my chest, my boots kicking over nothing, and I hauled myself up by my fingernails."] = { "e340e66f24ab", 10.08 },
		["I didn't look up for a long time. When I did, the shadow's head had turned on the wall, though the man's had not."] = { "ad076b11ec66", 7.81 },
		["I didn't look up for long. What I looked at, and I've told very few people this, was the shadow I was casting on the road."] = { "b1c546830c58", 8.33 },
		["I didn't need to count. It's one of the few advantages of my condition, so I like to make the most of it."] = { "4dcf2aa7e872", 6.74 },
		["I didn't sleep. By morning we were six again, and nobody mentioned it. But there were seven bowls by the ashes, all scraped clean."] = { "0f98e67000a4", 9.67 },
		["I didn't turn around. I just said good evening, very politely. It said it back."] = { "260d73216fc3", 6.19 },
		["I didn't understand that one until years later."] = { "844a377c9c40", 3.08 },
		["I do birthdays now. The pay is very good, and no one has tried to kill me at one yet. Don't tell the other scholars. They all do birthdays too."] = { "b5f5c51f03a1", 10.74 },
		["I do miss the taste of a pear, though. I eat them now and then, just to remember the shape of it."] = { "f150f9158f43", 5.77 },
		["I don't believe it. Rocks are rocks. But I sent a letter to somebody the day I heard it, somebody I'd been meaning to write to for years."] = { "19c1b21362ab", 9.64 },
		["I don't judge a stranger by where they sit. But I do count my horses."] = { "9747eb032fea", 5.22 },
		["I don't know how it knew the hour was up, but it knew. I reached high ground with a few breaths to spare, and I turned and thanked it, loudly."] = { "36e9295a75d0", 9.35 },
		["I don't know if it's true, about the wind. I'm not a fool. I said it anyway, all of it, out loud, and it was snatched away before I'd even heard it myself."] = { "561cff1cfed5", 11.39 },
		["I don't know if you've ever been dragged across a frozen lake on your belly. It's fast. Much faster than you'd like. The reindeer did not slow down for the ice."] = { "039e5581d44c", 11.34 },
		["I don't know what came over me. I said, excuse me, the right head has a point. The left head was very hurt. It asked the right head if I was a friend of his."] = { "0a90da7ce10d", 10.42 },
		["I don't know why I did it. I took the paddle and tapped it on the side of the boat, just the same way."] = { "f9049e6cdfcc", 6.32 },
		["I don't recommend camping on a rock. But when a pack comes up around you at night, a rock is the best furniture there is."] = { "4d732bddb88e", 7.92 },
		["I don't remember all of it. I remember climbing a fellow's shoulders. Someone made a fortune betting on me that day, and I'd still like to know who."] = { "b9fbd2ef4e0c", 9.67 },
		["I don't remember deciding anything. I remember running, and then I was on the seat, hauling on the reins, and then the reins came off in my hands."] = { "17bc091243bc", 9.35 },
		["I don't remember the name of that village. But there's a little girl somewhere tying up a gate with my father's hands."] = { "dd0455fbd266", 7.08 },
		["I don't suppose it's anything you could prove."] = { "ae6fa15763b2", 2.61 },
		["I don't think I was ever making anything. But I've thought through a lot of bad nights with this in my hands."] = { "ca4c0f1be8d1", 6.53 },
		["I drank it. I sweated, the way she did, and I felt cooler for it. I still don't understand it. I just drink the tea now."] = { "edfa136ea3a7", 9.53 },
		["I drew it very badly. She asked about every line anyway, and by the end that corner was the most useful part of the map."] = { "d2e4fcbbc5af", 8.1 },
		["I drew water from a well on an empty farm in Redridge. There was a white pebble in the bucket. I tossed it into the grass and lowered the bucket again."] = { "65f3644f1c5f", 10 },
		["I dropped a spoon near the Dark Portal, in the Blasted Lands. It rang on a stone. Then, from somewhere inside that great empty frame, the same ring came back."] = { "8e1f366d5840", 11.86 },
		["I dropped my kettle off a ridge in Ashenvale, and a root reached out and caught it by the handle. I thanked that tree. Very sincerely. At length."] = { "f3ac0e6d996f", 10.42 },
		["I drove a cart of apples through Hillsbrad, right between Southshore and Tarren Mill. That's a road where everyone wants to know whose side you're on."] = { "39d01bf21c14", 9.48 },
		["I drove my totems in as the mud came up to my knees, then my waist. I was shouting the old words with rain in my mouth. A whole shed went by me."] = { "cde269ee85ee", 10.37 },
		["I dug for an hour. I was very upset. And I did get a boot back, you know, only it wasn't mine. It was a left one, a good bit older, and it wasn't my size."] = { "c3bf48211c8d", 10.29 },
		["I dug in my heels and hauled, hand over hand, with no idea who was on the end. Morning came, and there were nine of us. I still find that dust in my teeth."] = { "0309f487cef3", 11.39 },
		["I dug this out of the snow in the ruins of Alterac. Old silver coin with a crowned head on it. I thought my luck had finally turned."] = { "cf07b878eea6", 9.46 },
		["I expected visions. Golden light and a voice from above. Mostly, my knees hurt and I needed to relieve myself."] = { "afc99ce205a6", 8.33 },
		["I explained I had died. He had a look in his papers, nodded, and read it out to me. Repayable over the term of the borrower's life."] = { "c8d36079c2c1", 9.64 },
		["I figured there'd be a tale. A drowned queen, some old curse. I bought him a drink so I could get him talking, and I asked him straight out."] = { "7cdb8e2dc64d", 9.46 },
		["I fill up a caster before the spells slip. What am I?"] = { "6ecd6a7e923d", 4.34 },
		["I fill up the wounds that a blade has left hollow. What am I?"] = { "8a40c8b6ee5b", 4.21 },
		["I finished it myself, and it looked at me. She said only, \"That's what a bad shot costs, and you're the cheap end of it.\""] = { "c573bb5389be", 8.28 },
		["I finished the work on the fifteenth day. Clean and quiet, and I was paid on time. I have no complaints to make."] = { "9829ec588096", 8.28 },
		["I fly from a string and I never come back."] = { "56ac1cab2fa4", 2.95 },
		["I found a chip of carved stone in Shen'dralas, no bigger than my thumbnail, and took it to a scholar working in the old ruins."] = { "7e6944eaf938", 8.15 },
		["I found a letter in a farmhouse in the Eastern Plaguelands, sealed and never sent. It told someone's brother the harvest would be the best in years."] = { "e18de9320e98", 9.48 },
		["I found a mitten on the road out of Kharanos, in Dun Morogh. Good wool, packed full of snow. I shook it out to carry it to the next inn."] = { "a32bf1739da0", 9.48 },
		["I found a spoon in mine. A big, old iron one. The keeper was thrilled. They'd been looking for it since before he was born."] = { "bd3e6c8cc4e7", 8.65 },
		["I found her a week later. She read the letter twice, then asked me how he was. Was he well. Was he eating."] = { "8ef58ccd3037", 7.99 },
		["I found him in a ditch in the first snow. Nothing to be done for him, and he had a good coat. I was cold. He wasn't. So."] = { "1410e3becf36", 9.48 },
		["I found my druid that evening and did it his way. Two words. It went over much better than six pages would have."] = { "80af49abc386", 8.65 },
		["I found one on a lonely hill, looking out over nothing. I bowed and asked what he was watching."] = { "90f696a359fc", 6.79 },
		["I found one on the worst day of my life, between Ratchet and nowhere, with my tongue stuck to the roof of my mouth."] = { "6b1653db5be3", 7.5 },
		["I found out later he'd spent the whole afternoon on the bank, watching the water, looking for the handsome one."] = { "e6f681ce888a", 7.08 },
		["I found sand in my bread last month. Baked into the bread, at an inn on the far side of the world. Nobody else there had any. I checked."] = { "755dc9c28420", 10.48 },
		["I froze. It raised its wings and did a sort of little dance. Very stately. Lots of shoulder."] = { "7c324ea029f2", 7.97 },
		["I gave up and turned back, and the village I'd left was an hour behind me, as if it had waited. I still wonder who tied the high ones, and how long it took them to grow tall enough."] = { "594679175a68", 12.04 },
		["I go back each spring. The boar has a family now. By my reading of the deed, they're my tenants, and they have never once paid on time."] = { "57c7bdb6e409", 10.42 },
		["I go up there sometimes and listen. You can hear the machines. Still running, after all this time. Which is odd, if you think about it."] = { "e4bbfa07b043", 9.77 },
		["I got halfway across on my feet. The rest I did on my hands and knees, with my eyes closed, reciting the names of everyone I owed money."] = { "8baa0b1f3d8b", 9.95 },
		["I got her ankle. Barely. I pulled her up, and she was furious with me, because she'd let go of the string."] = { "11040e74538d", 7.37 },
		["I got into the trees, and I stopped, and I looked back. They'd come as far as my camp. Then the water drew back again, all at once, and it took the whole beach with it."] = { "6fd4ea920eae", 11.68 },
		["I got lost in a salt marsh with night coming on, and a fellow with a lantern came along and told me to walk where he walked."] = { "70b883f8e9f9", 7.92 },
		["I got one with an elbow, and then the net came down, and the rail went, and I dropped straight into the lake wearing every bit of iron I own."] = { "b2a345ee8231", 8.65 },
		["I got out. These days, when somebody's sitting in the sun and says, oh, it's a nice bit of shade coming, I'm already gone."] = { "64d2ee3f5de8", 8.83 },
		["I got the words out with him halfway down. He slowed like a leaf, still shouting, and drifted the rest of the way into a hay cart."] = { "6b073987f45e", 8.39 },
		["I got up and walked out of it. It stayed on the grass behind me, a cool dark shape about the size of someone lying down."] = { "773e52cd5fb6", 8.15 },
		["I got up, and we left, and the ogres went on arguing. I like to think they're still at it. I never did find out what happened to the rabbit."] = { "b2401880f2ea", 9.04 },
		["I grabbed the first scale I saw, and the ground lifted. It wasn't the ground. I ran with fire behind me, through reeds that went up like torches, and I didn't stop for a day."] = { "6371a71d61da", 11.86 },
		["I had a dog as a child. Ugly thing, one ear. She slept across my feet every night of her life, and she died when I was twelve."] = { "36d5f66f3079", 9.53 },
		["I had a little brother with a cough that wouldn't stop. The healers had all been very kind, and they'd all stopped coming. So I went to the old books."] = { "b9fc494b6c3f", 9.82 },
		["I had a partner who'd share her last waterskin with anybody. Anybody. One day it was the wrong somebody."] = { "5428d12de139", 7.55 },
		["I had a workshop there. I left a kettle on. It's a silly thing to think about, but I do. All the time."] = { "644a5446a883", 7.81 },
		["I had carved my name on a bench in Auberdine that morning. I walked back and looked at it. Then I sat down on it and had my lunch."] = { "3cc5211c79de", 8.39 },
		["I had five Boulderfist ogres behind me that night, and the wind trying to peel me off the stone. Ahead of me there was just a lot of dark."] = { "b0250d80d93a", 9.06 },
		["I had my ears cleaned, and the fellow held up the cloth and asked where I'd been. I cracked an egg, and I'm not joking. There was sand in the egg."] = { "56e761c58028", 9.95 },
		["I had no other plan, so I followed it. Through the ferns, around the tar pits, past something I won't describe. It never hesitated. Not once."] = { "c5465026bd90", 10.74 },
		["I had nothing. I told a story about a goat I'd once owned. It had no ending. The goat just sort of wandered off, and so did the story."] = { "57875f35405b", 10.74 },
		["I had one tested. It's water, a little rosewater, and a label that says go on, ask them. Half her customers come back married."] = { "b0cd80442983", 9.95 },
		["I had time to think how nice it was. Then I looked up and it had wings. Black ones, and a long way across."] = { "e6217fe7badd", 7.92 },
		["I had to ask. I said, so was that really the password? He shrugged. Dunno, he said. Nobody ever guessed before."] = { "679e8d003eb5", 8.93 },
		["I hang on your back and I'm never enough."] = { "51b42429a66d", 2.66 },
		["I hauled myself over the top and lay there, laughing. They couldn't reach me. I'd won. The whole Steppes burning below me, and me on top of it."] = { "976424dc3a63", 9.77 },
		["I have a shape for exactly that. Long legs, light bones, and no room in its head for anything but running."] = { "876a4305cb52", 7.39 },
		["I have it still. I haven't spent it. I did count it, though. She'd shorted me by two silver."] = { "0f1c7322236d", 6.84 },
		["I have used what's in it just once, on someone who deserved it. It worked very well. That's the part I've never found anyone to confess to."] = { "cb618819ba34", 9.77 },
		["I hear it's quite popular now. They sing it in places where I'm still wanted for questioning."] = { "19c7e67499db", 6.3 },
		["I heard it, once. And what bothers me is that I found myself counting, and it was counting back."] = { "9b00024ad6f9", 7.21 },
		["I heard some once, on the root road, far past any lamp. Behind me, slow and heavy. I stopped walking, and they went on for one step longer."] = { "5848d1a71b71", 10.89 },
		["I held a footbridge for four hours once. Me, a cracked shield, and just enough width for one thing at a time to come at me."] = { "342b048224a5", 8.99 },
		["I held it to my ear a hundred times as a child. Never heard a thing. I told her so."] = { "1ec532c8841a", 6.61 },
		["I held my hands out, as you would. They got colder. I moved closer, and they got colder still, until my fingers ached."] = { "4f717b150989", 8.88 },
		["I helped her finish it. It took all afternoon. That pile was still standing a year later, when the neat ones around it had all come down."] = { "3d3212aeb9b0", 9.46 },
		["I hiked down from the high parts of Stonetalon into the logged-out valleys. You come over a ridge from green trees, and it just stops."] = { "61f55ffa7341", 9.64 },
		["I hired a guide to take me through Deadwind Pass. He charged extra for conversation, which I paid gladly. I thought it meant he'd tell me stories on the way."] = { "833a159e46a3", 10.66 },
		["I hired an old guide to take me through the Hinterlands. We'd go a mile out of our way, then two, winding around through the thickets on these faint little trails."] = { "7dda25a6ac74", 10.08 },
		["I hired an old kodo out of Bloodhoof Village to carry my things across Mulgore. Good animal. Never stopped for anything."] = { "500089bc2f57", 8.46 },
		["I hit a cairn with my shin. From there, if I crawled straight, I could find the next one. That's what they're for. They're spaced just so."] = { "ee582f1ea17f", 10.24 },
		["I hit the mast with both arms and held on, and tied off with fingers I couldn't feel. They came along that rope one by one, all nineteen of them. Afterward I couldn't stop laughing."] = { "cb72977f2ecc", 13.4 },
		["I hung it on the first fence post I came to. Somebody had lost it, and from the look of things, they were still wearing it."] = { "2cab1f9938d4", 7.08 },
		["I jammed it between the spokes. The whole wheel groaned and stopped, and the boy fetched up against it like a leaf against a stick."] = { "9b40899ce5c7", 8.65 },
		["I keep it talking. It keeps me company. Each of us believes we're the one holding the leash."] = { "5dd259dacc19", 6.48 },
		["I keep meaning to send it. But then something else happens, and it seems like they ought to hear about that too."] = { "88ec709e53d0", 6.53 },
		["I kept it in my pocket the rest of the way across. Whenever the gray got to be too much, I'd take it out and have a look."] = { "96f766216285", 7.97 },
		["I kept it. It's in my pack still. A promise, I suppose, that the faire always comes back."] = { "4eaf35f1bf3e", 6.79 },
		["I kept my back to the drop until they were safely past. I hope the rest of their road was wider."] = { "0a9fe785a719", 6.48 },
		["I kept the first one's name, though. I already knew it, you see."] = { "fa3da4c8ab71", 4.1 },
		["I kept the flower. It's been through three coats now."] = { "d3d3fe55559d", 3.79 },
		["I kept the rope, though. I've never managed to untie that knot."] = { "08ccf98fb0c0", 4.1 },
		["I knew a trapper who looked at everyone's shadow before sharing her fire. A shadow always leans away from the flames, she said."] = { "4fcaa780fc8b", 8.2 },
		["I knew better than to follow it. I sat down and ate my own dry ration, very loudly, so whatever it was would know I wasn't hungry."] = { "b8f7aacea5d7", 9.12 },
		["I knew what stands in those fields now. I'd walked through them to get there."] = { "453aa46d0581", 5.22 },
		["I know a few stars. I couldn't find one of them in that bowl. Not a single one."] = { "ddffe5d6f197", 6.19 },
		["I know a spell that turns a creature into a sheep for a short while. The important words there are short while."] = { "7e255487f78c", 6.71 },
		["I know an inn where the stew has been on the fire since the keeper's grandfather's day. It's never once been emptied. They just keep adding to it."] = { "fbc9d09d8822", 8.83 },
		["I laughed and took it. I figured she was cracked. Then I read the front of it."] = { "2ac923fd4f67", 5.72 },
		["I laughed at her. Then I tried it."] = { "9ccedb26d4d6", 2.61 },
		["I laughed at that, going in. Black trees, green sludge, deer that don't run away from you. Who could like that? I spent the first few days with a cloth over my mouth."] = { "2f6773bdbf6d", 12.04 },
		["I laughed it off. A week later I came to a fork, and I took the left. It cost me a lot. I won't go into it."] = { "9d975918cd68", 8.28 },
		["I laughed until I had to sit down. It got me through. When I reached the far end, I found a sharp rock and went back a mile to add one of my own."] = { "78077d936ec8", 10 },
		["I laughed. All that forbidden lore, and she's on about breakfast. But think how people really come to this work. At the worst hour of the worst night of their lives."] = { "816dc5b5e20a", 11.81 },
		["I laughed. I build things that last a season and I'm proud when they do. I asked her who she expected to sit in it."] = { "179305734fad", 8.46 },
		["I lay down to rest in Mulgore one hot afternoon, under the shadow of a single passing cloud. Lovely and cool."] = { "5fb0c7cf68b6", 8.75 },
		["I left a cloak with a tailor to be mended once, in a human town, and told him I'd be back for it shortly."] = { "191f5a1de94f", 7.31 },
		["I left a perfectly good kettle at that camp. I have never wanted a kettle less."] = { "0b1755ac7c25", 5.59 },
		["I left the cord behind. It was a good cord, too. But whoever was drying out up there needed it more than I did."] = { "c58bfa8cc86f", 7.55 },
		["I left the next morning. Three days down the road, I hear boots behind me, and here comes a fellow from the tavern, out of breath."] = { "33af2516e5c7", 8.88 },
		["I left the spoon where it was. The soldiers at Nethergarde told me later they leave things there on purpose, to see if anything answers. I didn't ask what they do when it does."] = { "308d5254b358", 11.31 },
		["I let go and ran. It kept the pack and my rations. I'd say it earned them. Nothing else in that marsh has ever done me such a favor."] = { "15ce7e55dc35", 9.04 },
		["I like to think it's still trying to go places."] = { "3439e5469c1e", 2.98 },
		["I lit the torch, turned around, and found the keeper standing there. Holding a bucket."] = { "3432159a40e6", 5.69 },
		["I looked back from the road. It was at the window."] = { "db0edd61fa34", 3.55 },
		["I looked back. Lightning was walking along the top of that ridge, one strike after another, right where I'd been standing."] = { "9cf41c5442bf", 8.41 },
		["I looked over at the corner. The corner was empty. And it sounded so sensible. I was halfway to the stairs before I knew I'd stood up."] = { "1c9e38cb4eed", 8.15 },
		["I looked, of course. I won't tell you there was anything to see. I'll only say I've rowed that stretch myself since, and I look at my feet."] = { "fd74ec6e08a6", 9.17 },
		["I lost eleven gold to a woman who turned out to own the boots, the boat, and the fellow."] = { "d9bfac3a8ecd", 5.64 },
		["I lost my left hand in a card game, once. Not as a wager. It just came off, in the middle of a very tense round."] = { "c3655c69f0f5", 8.15 },
		["I lost someone a few years ago. I spent a long time leaning away from that, as hard as I could, and I kept on losing my footing."] = { "85f2f1a6fdea", 9.12 },
		["I made it in an hour. The trouble is, you arrive as a big spotted cat panting in the healer's doorway, and you can't explain a thing until you change back."] = { "e5aca555cb8c", 10.32 },
		["I measured both. Same. I measured again. Still the same. By then half the inn had turned round to watch."] = { "ccc45b91d8d9", 8.57 },
		["I met a goatherd outside Dalaran who remembered where its violet barrier had stood. He showed me a line of grass that still lay flat."] = { "0edb8b80edc7", 8.8 },
		["I met a human child once, six years old, who wanted to know if my ears hurt. We became friends. I can't really say why."] = { "83f4ac11d47a", 9.64 },
		["I met an old sentry on a ridge in the Blasted Lands. Red rock in every direction, and a red sky above it. There was nothing to guard that I could see."] = { "b97670322be9", 10.24 },
		["I missed an elevator up Thunder Bluff because I was busy thanking a tauren for letting me go first. He let me go first on the next one too."] = { "e91ac09f0ee4", 8.83 },
		["I missed. It sailed past and hit a yeti, right in the chest. A big one. I hadn't seen it, because they're the same color as everything."] = { "4ecf626c99ac", 9.67 },
		["I never asked who the other half of the bench was for. But I stopped cutting through that part of the garden."] = { "7fe48e1bf4fc", 6.37 },
		["I never did find out who. Whoever they are, that's the second time I've lost them."] = { "9dcdd977af8b", 6.01 },
		["I never found out how. Some say Greatfather Winter just knows. I'd rather not know, honestly."] = { "7b597209eeca", 7.86 },
		["I never learned my letters, and neither did my mother. So when I send word home, I pay a clerk to write down what I say."] = { "bc5621dd92a3", 7.73 },
		["I never learned their name. They left before dawn, and took the road I didn't."] = { "ec3edf62b4cd", 4.7 },
		["I never learned who they were. I may have met them again since, across a field somewhere. I hope I was too far away to tell."] = { "3f3a220afc53", 8.52 },
		["I never mentioned it, and neither did she."] = { "a9a2a0bec75e", 2.61 },
		["I never said a word. But the next morning, the button I'd been missing for a month was back on my own coat."] = { "d22dc291b25f", 7.31 },
		["I noticed one bridge had rope twice as thick as the others. Three times the knots. It only went out to a small empty ledge, too, and no one had any use for it."] = { "aa2f13c8022b", 11.21 },
		["I noticed one jar that was empty, with the label half written. There was no name on it, only a date. It was the next day's date."] = { "78fd28d6cf23", 9.3 },
		["I noticed something when I got to Zephras Isle. Nobody there wears a hat. I took it for the fashion. I had a good hat, and I wore it down the path, feeling rather smart."] = { "5d516c5186f3", 11.91 },
		["I offered to tell her what was out past the last mark. She handed me the pen instead."] = { "53e992fc4919", 5.72 },
		["I once bought a secondhand coat with a hidden pocket in the lining. Good work. Then I found a little flower stitched right across the opening."] = { "99dc0d222ecc", 9.46 },
		["I once brought a ruined horseshoe to a smith at the Great Forge, wanting it mended. I'd walked a long way, and I'd put a lot of hope in that shoe."] = { "2ff6cb4a147b", 9.59 },
		["I once built a device that translates chickens. People laughed. Let the record show that it works. Let the record also show that I regret it."] = { "8c35067db2e0", 10.08 },
		["I once built a device to wake me up in the morning. A very simple thing. Forty gears, two springs, and a small charge."] = { "5da16c4c59d5", 9.3 },
		["I once complained in Kharanos that my mug held less than the fellow's next to me. Loudly. The keeper handed me a measuring cup."] = { "a62391a6cae7", 8.62 },
		["I once designed a quick-release buckle. One tug and it lets go, for getting out of a harness in a hurry. Beautiful drawings."] = { "8329feaaa98e", 8.93 },
		["I once followed a map for six days before I noticed I was holding it upside down."] = { "1abaad34d3d7", 5.22 },
		["I once followed a so-called fearless knight for two days. He'd told the whole inn about the monster he'd slain."] = { "1af000d4a92c", 7.21 },
		["I once had to open a prison wagon from the outside while it was moving. Bumpy road, six guards, and a friend inside who owed me money."] = { "d8622041b8cf", 9.12 },
		["I once left my clothes with a friend while I went swimming in another shape. When I came back, he was wearing my coat."] = { "bef626c985ee", 7.92 },
		["I once met a cook from Nethergarde Keep, who'd been feeding soldiers in the Blasted Lands for some years. I asked how anyone could find food in a place like that."] = { "3c60db25dfa0", 10.24 },
		["I once offered to make someone's portrait out of an illusion. He asked if it would be flattering. I promised him it would be perfectly accurate."] = { "785e7b82208a", 8.52 },
		["I once sat with a frightened traveler who asked me for a prayer. I offered one of mine. She shook her head. Wrong one."] = { "7dce9daa8a7c", 8.62 },
		["I once served beside the finest fighter I ever saw. She'd stood alone against things that still give me bad dreams. I asked her secret."] = { "86f6fbeb972e", 9.77 },
		["I once showed a visitor around Zephras Isle. I kept pointing at the sky, and she kept looking at the path. I thought she was bored."] = { "c1ad01da68e4", 9.12 },
		["I once told a camp I'd seen a monster as tall as three trees, just past the firelight. I only wanted someone else to take the night watch."] = { "13970f5c7a0e", 9.22 },
		["I once traveled with someone whose language I barely knew. Between us we had words for water, danger, and splitting the bill. We managed fine."] = { "8ddc012f9afd", 10.42 },
		["I once tried to impress a druid in Moonglade by naming every tree we passed. I know three trees. I made them go a long way."] = { "397fb4f254b0", 9.12 },
		["I once watched a mason in Stormwind spend a whole day carving one stone for the Cathedral. Leaves, vines, a tiny bird. It was beautiful."] = { "b130d86fb3c3", 10.74 },
		["I opened it up. Nothing wrong at all. Lovely work, and the spring was still half wound. So I asked her, who wound it last?"] = { "cda1f8ebd30d", 9.77 },
		["I ordered the stew. Something came up to the surface of it, looked at me, and sank back down again. We understood each other."] = { "afc413cf82d0", 8.33 },
		["I own forty-one rocks. I'm fairly sure that makes me a merchant in their eyes."] = { "4607a15d507e", 5.46 },
		["I owned half a horse for a year. I couldn't afford the whole thing, and neither could a fellow called Hob."] = { "92d7114df0cb", 7.21 },
		["I packed up then and I left, without breakfast. I've not told anyone what I answered when they asked me, and I'd rather you didn't ask me either."] = { "270ddf72ec1c", 9.4 },
		["I packed up, not fast, and I didn't look at them while I did it. When I was well out on the grass, I heard stone grind on stone behind me."] = { "25ed061e2add", 9.25 },
		["I paid for both. Cheapest thing I've ever bought."] = { "a9cb12851218", 3.5 },
		["I paid for the cup. I paid for everybody's supper. I take my meals outside now, where there's nothing to drop."] = { "7631a2e77feb", 7.68 },
		["I paid for two teeth. He offered a discount if I'd like a third, so he could see the whole row."] = { "a981a58f8086", 6.71 },
		["I paid him again, to be safe. Then I walked the long way around. It took three days. I'd do it again."] = { "56cd49020afb", 7.63 },
		["I paid it. Who wouldn't? He wrote it down, stamped a receipt, and told me the kingdom thanked me for my contribution."] = { "85a10ea36b24", 8.65 },
		["I paid ten gold for a treasure map once. Spent a whole summer digging where it said."] = { "8ce60b485627", 5.72 },
		["I passed one at sunset, all rust and loose bolts, walking the rows of a field that hasn't grown a thing in years."] = { "3ded5449efcf", 8.41 },
		["I passed that way again at harvest. The fence was standing straight, and the gate was propped wide open with a soup ladle."] = { "35b1e0bb53e9", 7.97 },
		["I passed that well as a grown orc, and got to talking with an old one who'd lived nearby for years. That well had only a dipper's worth by morning, the old one said."] = { "953fea3e8635", 11.08 },
		["I passed through a town I'd worked, years back. The man I robbed and his brother still don't speak. Nobody ever taught me how to count that."] = { "8ab56ef4977f", 9.12 },
		["I passed through what's left of Andorhal in the Western Plaguelands once, and I wish I hadn't. At the edge of the ruins, a dog came out to meet me."] = { "c65e29f5bc13", 9.67 },
		["I picked it up and tipped it myself. It spilled just as you'd expect. I set it down again, and the water went level again."] = { "e39f337a8efa", 8.15 },
		["I picked it up, tucked it under my arm, and asked whose turn it was. Everyone folded."] = { "51a2bf478743", 6.11 },
		["I plant on that hill every year. I don't call it making up for anything. I just can't find anything else to say to that hill."] = { "d9babacb2ef5", 8.39 },
		["I planted a row with her before I left. I don't know what came of it. I hope someone sits under it one day and wonders who."] = { "accfb21612a6", 8.33 },
		["I planted it. She said, \"Now you don't water it. If it lives, let it live on what's here. That's all I'm asking.\" She was gone by the thaw."] = { "68071e3fc771", 11.31 },
		["I pray before I do either. I'd be worried about any priest who only prayed before one."] = { "ec44134eb29b", 5.83 },
		["I prayed. I truly did. And what I finally said was, \"I have eaten worse in the service of the Light.\""] = { "3ed4d3d35c79", 7.92 },
		["I pried a corner off the nearest door. I looked at the marks on the inside of it. Then I hammered that board back on and went home with nothing."] = { "d4773a0d8f3d", 9.3 },
		["I pulled it back up. The stone was gone. The rope was coated in red dust, and on the end was a new knot, very neat, the kind sailors tie."] = { "5fc75e2f208e", 10.32 },
		["I put a month's wages on a race out on the Shimmering Flats. Goblins on one side, gnomes on the other, and all of them insane."] = { "1a9e3ada9436", 9.3 },
		["I put it on at the next stream. I spilled supper down it that same evening."] = { "1ebbdd3b649c", 4.94 },
		["I put it right back where I found it. Some eggs aren't meant for baskets."] = { "560601a360b7", 4.94 },
		["I put my things next to theirs. Nobody spoke, and the snow kept falling. After a while, one of them held out a flask, and I took it, and I passed it along."] = { "ecac8dca8f96", 10.29 },
		["I ran alongside and cut the reins with my knife. The driver came loose and rolled into a drift. The dogs pulled up at the very edge, but the empty sled went right on over."] = { "90d96f675395", 12.23 },
		["I ran for the Golakka Hot Springs and went in up to my nose. It's as hot as soup in there. I'd rather be soup than the other thing, I thought, and I stayed in."] = { "245839ffa7bd", 10.24 },
		["I ran for the rope and missed it. All I got hold of was a sack of grain dragging along behind."] = { "3e0ee6db5135", 6.79 },
		["I ran the rest of the way, and I run very well. At the gate, the guard took one look at me and went quiet. There was a wet handprint on the back of my cloak."] = { "18650550470f", 10.55 },
		["I read the prayer through to the end, for both of them. I told the family he'd gone peacefully, and I asked them to keep a lamp in that room."] = { "aa453a9fa266", 9.04 },
		["I refused. It offered to stop insulting my hair for a whole week. I agreed far too quickly, now that I think about it."] = { "5b74cf158053", 8.41 },
		["I remarked on that to a traveler at the crossroads. A fire can't burn that long. Not on wood, or on anything. There can't be anything left in there to burn."] = { "7d49016b8654", 10.66 },
		["I remember every one of them, though. That's why I don't sleep near graveyards."] = { "d90be252b56f", 4.99 },
		["I ruled that the fence should go right where the sheep used to stand. It seemed only fair to the sheep."] = { "1efe06c4ee36", 6.19 },
		["I said I'd meant a map. He pointed out that I'd asked for a drawing."] = { "143b538afcc5", 4.44 },
		["I said a lower drum wouldn't carry as far. She said a drum nobody can reach doesn't carry at all."] = { "c8a9691a6f6d", 6.61 },
		["I said he looked like a man who missed her very much. That was true. It just wasn't all of it."] = { "aa9219785583", 6.19 },
		["I said it was a very young pine. She said it was a very old bush. Several hundred years, she thought."] = { "7d507186c597", 7.39 },
		["I said no. I don't know why. I picked up my things and walked out, not quickly, the way you would around a strange dog."] = { "cb8c648183df", 9.06 },
		["I said nothing. I just wanted to look at it. She nodded as though that was the most sensible thing anyone had told her all season."] = { "29e8a821f84e", 8.05 },
		["I said one good pair was enough. She just smiled and wouldn't take them back."] = { "b6397051bf53", 5.36 },
		["I said that sounded very nice. He looked up at the ruins, all those beautiful broken towers among the trees, and said that they'd thought so too."] = { "07f87f688a5d", 9.9 },
		["I said the handsome one would have been a safe guess. He took the coat off and handed it back without a word."] = { "1cef3fa3b6fe", 6.66 },
		["I said, keep your guard up. She knocked me down again. Day two, the same thing. For a month."] = { "029e907fd444", 8.33 },
		["I sank to the thighs, an arm's length short of a big fellow on the other side, who had sunk just as far."] = { "11ef56576234", 7.37 },
		["I sat and ate my lunch up there. It does have a good view. I'd like to say more for it than that, but I can't."] = { "58d96a92c8c9", 7.58 },
		["I sat up all night on a hill above the field. Empty grass. Not a wagon in sight."] = { "864536258253", 6.32 },
		["I sat. Looked up. Saw it. Looked across. The one sitting there was an ogre."] = { "51b69820ac09", 7.21 },
		["I saved for months for a new shirt, then kept it wrapped up in my pack. I was waiting for a day clean enough to deserve it."] = { "b9f0186535f0", 8.23 },
		["I saw an old cow on the road once, heading that way. I was going in the same direction, so I walked along behind her, out of curiosity, and I'm not proud of it."] = { "b20ea0a3274b", 11.39 },
		["I saw him one evening, leading something slow and stumbling back through the gate by its sleeve, talking to it quietly."] = { "0c395e24a3ff", 7.86 },
		["I saw my grandmother. She told me to drink some water. There was no water. A very large fellow handed me a pepper, as a cure."] = { "ef5d40598a0c", 9.17 },
		["I saw myself, all right. And beside me, close enough to touch, someone sitting with their head on my shoulder. Someone I had never seen before in my life."] = { "4c1cbee468fd", 11.15 },
		["I saw old stone walls, an open gate, and went through it at a full sprint without asking what it was for."] = { "e212edf7e95e", 7.03 },
		["I saw the Twin Colossals rising above northern Feralas, two vast towers of rock. From beneath them, everything I had climbed before looked small."] = { "f8dcd5761ccd", 10.29 },
		["I say their names before I sleep. Everyone I've lost, in the order I lost them. I started when there were only three."] = { "693b40cc462f", 8.8 },
		["I served on a workshop safety board, back home. A fine body. Seven members, and we met in a specially reinforced room."] = { "1876a8903968", 9.67 },
		["I set the mug down very carefully. Rolled up my sleeves. And started making snowballs of my own."] = { "c9d78108c1fe", 6.9 },
		["I set them all out on what remained of the table, and I sat there a while. I'm dead, and that's the whole of what I've learned from it. Use the good plates."] = { "b0f64d24813b", 10.5 },
		["I shared a room with the most brilliant student of our year. I envied him so badly I could taste it."] = { "eb2f8e0f87bf", 6.53 },
		["I sheltered in a ruined doorway in the Burning Steppes. Ash lay an inch deep on everything there, except the bottom step, which was swept clean."] = { "0f6bcf9849b4", 9.77 },
		["I should have ended up somewhere awful. Instead I walked into a village in the middle of a harvest feast."] = { "be94d734f2dc", 6.48 },
		["I should've let it go. Instead I held on, and the wind took my feet out from under me. Then we were both off the ledge, me on one strap, her on the other."] = { "f528ad2f3271", 11.21 },
		["I shut the book and put it back. It's still there. I'd give a great deal to know what's on the next page, and that's what frightens me."] = { "4210b346ca98", 8.2 },
		["I sing into stone with each patient stroke. What am I?"] = { "4621cd3f6024", 4.75 },
		["I sleep in the hillside in veins green and brown,"] = { "2f14058ca44c", 3.5 },
		["I smelled fresh bread on a lonely road in Felwood. Warm, buttery, just out of the oven. There's no oven for twenty miles in Felwood."] = { "cfacf09ecab0", 9.95 },
		["I sometimes wake in these bright, loud cities and have to remind myself that the sun is not angry with me."] = { "4a81154df05a", 6.66 },
		["I spent a night in Pyrewood Village, in Silverpine. Lovely people. A good supper, a warm room, and they asked me all about my travels."] = { "8dc86ac7627f", 10 },
		["I spent a week mining in the Searing Gorge, where the air is hot enough to cook your breakfast. Every morning, the old miner beside me drank a cup of hot tea."] = { "c9c1f59b2e94", 9.77 },
		["I spent a week on Mount Hyjal helping a surveyor map the burned ground. We drew it in charcoal, because there was charcoal everywhere."] = { "48c424cdbcae", 8.7 },
		["I spent a week sorting rubble at Uldaman, in the Badlands. Mostly rocks. Then I found a little clay hand with a thumbprint pressed into the palm."] = { "795b1eaf9380", 10.14 },
		["I spent a whole week on Teldrassil before anyone mentioned the ground. I'd walked its hills, drunk from Lake Al'Ameth, slept in the grass at Dolanaar."] = { "e3429d058f1b", 10.06 },
		["I spent a whole year as a servant at a nobleman's house. He spoke to me daily, and never once learned my name."] = { "10312f042cc3", 7.81 },
		["I spent four years preparing to bind a creature of pure and ancient malice. I gave up sleep. I gave up my friends. I was ready for anything."] = { "b421fd6885c9", 10.66 },
		["I spent most of one summer as a bear. There was a good reason for that. There was also a great deal of honey. But a summer is a long time."] = { "5987b4dc87a0", 9.77 },
		["I spent one whole night trying to keep a campfire going in the rain. By morning, I'd apologized to both of them."] = { "e595afbd943f", 7.81 },
		["I spent ten years sure that the next hill would be the one worth writing home about."] = { "df235177dbe3", 4.75 },
		["I spent the whole festival running from wild animals with flowers in their teeth."] = { "967cf55ae1c8", 4.75 },
		["I spent the whole of it under a table with my drink, going from table to table as they broke. I never spilled a drop."] = { "953ef48cace9", 7.81 },
		["I spent three weeks in Menethil Harbor trying to dry one pair of socks. They were on that inn's hearth for eleven days. They got damper."] = { "d2773b246520", 8.93 },
		["I spent years earning the trust of the winds. I wanted warnings of storms and armies. I got those. I also learned what my neighbors think of my singing."] = { "6c05dc9ce86a", 10.29 },
		["I spoke the oldest word for winter known to any living scholar, in front of forty guests, over a jug of very ordinary white."] = { "c0fa7c9e4950", 8.62 },
		["I staggered into town at last, and there he was on a porch, eating a pie. He looked at me and asked how the shortcut was."] = { "9440e709ca10", 8.39 },
		["I started the greatest tavern brawl of my life with a sneeze. It went right down a big fellow's collar, and he blamed the fellow behind me."] = { "b7f165dd43c3", 8.57 },
		["I started to apologize. She stopped me and asked, very quietly, what I'd used. I said sand, and a good hour."] = { "ec5eac3793e2", 9.22 },
		["I started to ask if he knew whose it was. Then I saw his face, and didn't."] = { "43b1a3295c5f", 5.54 },
		["I started to call after him. My mother laid a hand on my arm. No one at the fire looked up, and he did not look back."] = { "104c7019d82c", 8.2 },
		["I stayed about an hour and it never changed. I walked all around the place to check, and from every side it was the same. It only blows one way out there."] = { "e8cef3408ee8", 10.79 },
		["I stayed at an inn once where every single table wobbled. I asked the keeper for a wedge of wood, and he said he was all out. Very sorry."] = { "e20a9e10fb59", 9.64 },
		["I stepped back from it then. And there wasn't any draft in that room, I'm sure of it, but the flames leaned over toward me."] = { "78024736bfc3", 7.68 },
		["I stepped off a boat in Booty Bay and a goblin handed me a bill. Docking fee. I said I don't own a boat. He said, you were on one."] = { "5c78a0343941", 10.42 },
		["I still get it wrong, more often than I'd like. But I've started checking which way the river's going before I push."] = { "8f1d76b35c47", 7.03 },
		["I still have it. I've been plenty of places with color since. I still take it out sometimes, just to check it's blue."] = { "8072d194e2e2", 8.33 },
		["I still read from it at services. There's a dent in the cover, right across the word forgiveness. Nobody has ever asked."] = { "590045e75d73", 8.65 },
		["I still stop there when I pass through. He charges me full price for the room, and when I get up there, he's already brought two chairs."] = { "5cd359e254d4", 9.17 },
		["I still think about the one about the king. I'm still not sure I answered it honestly."] = { "e35173e4a88c", 5.41 },
		["I stood there until it got dark. Nobody came out. No reason they should."] = { "4937e98e9caf", 5.49 },
		["I stood up and said that was my story. He said it was his now, he had a receipt, and would I like to buy it back at the current price."] = { "d3fd304e1da5", 8.88 },
		["I stopped for a meal in Brill once, at the Gallows' End Tavern. The name should have told me all I needed. I asked what was good."] = { "f4fcac516d3e", 9.3 },
		["I stopped. It was raining sideways, and that chimney was the only cover for miles. I sat down with my back against it and tried to get warm."] = { "8905d1499561", 9.59 },
		["I tested it on a toolbox. I tugged. Nothing. I hung off it with my full weight. That buckle held on like a grudge."] = { "c8443e63e2c0", 9.12 },
		["I thanked him. He turned back into a bear and went to sleep."] = { "267e6f0691bf", 3.87 },
		["I thanked the rain. I thanked the mud. I thanked a rock that had just broken my toe. I felt like the world's greatest fool."] = { "3308e7ef7bdb", 8.57 },
		["I think about that face more than I should. Whoever they are, I hope I meet them. And I hope I'm glad when I do."] = { "7560f0aae2fc", 7.99 },
		["I think about that knot a good deal. Most things I've tied in my life, I tied the first way."] = { "d624946b362d", 6.71 },
		["I think about that one more often than I'd like to admit."] = { "a8d81a67b37c", 3.27 },
		["I think it was the laughing, myself. But they're soldiers. They needed a practical reason."] = { "8232198c2efb", 6.53 },
		["I thought I'd join in. I'm a seasoned adventurer. I've tracked beasts across mountains."] = { "4e077038c717", 6.3 },
		["I thought back. Nobody had fallen behind, nobody had wandered off, and I'd heard every story the slow ones had to tell."] = { "97136a60bef5", 8.62 },
		["I thought he'd be embarrassed. Out there, you want to look like mud. His friends told me later it was the first time he'd laughed in weeks."] = { "603deeb695e0", 8.99 },
		["I thought it was a charming custom, until we turned the cards up at closing. The chair had three queens."] = { "8a8db6c9a87e", 7.03 },
		["I thought she was mad. I was drinking cold water by the barrel and sweating it out as fast as I could pour it in."] = { "d41722829390", 7.26 },
		["I thought someone must have bought the place. Weeks went by. The shutters stayed shut, and the bell kept ringing, right at opening time."] = { "46f2f865f3a0", 9.22 },
		["I thought someone must live nearby. I sat on that step all night with my back to the door frame, ready to apologize."] = { "7c95a19e5c33", 8.41 },
		["I thought that was only something clever to say. Then the city fell. I saw her weeks later on the road, with no shelf, no bench, no tools at all."] = { "943cefdf9352", 10.55 },
		["I thought that was the wisest thing I'd ever heard. I carried it through my first real fight."] = { "39f1a40cc843", 5.72 },
		["I thought they were for climbing. Then I saw the ends. Not cut. Frayed out, long ago, and the knots at the posts still tied tight."] = { "4c825a46bc7d", 10.24 },
		["I thought, it's one of ours, someone new at this. So I lifted a hand and waved. After a moment, it raised one foreleg and waved back."] = { "01b6c86e5c81", 10.97 },
		["I threw it off a pier. I found it in my pack again that same winter. I haven't opened it. It hasn't been later yet."] = { "1bc96414fba0", 7.73 },
		["I threw myself into a dry wash just as the rocks where I'd stood turned orange. The heat took my eyebrows and my pack, and I crawled that gully for a mile."] = { "45e185e1b8a7", 10.08 },
		["I threw the vine. First throw, it caught a branch above her. Second throw, she caught it, which is the part that matters."] = { "aa18e611292b", 8.57 },
		["I told a crowd in Booty Bay about the time I escaped a raptor. A goblin offered me a silver for the story. I took it before he could change his mind."] = { "ab235e796d27", 9.72 },
		["I told a joke at the Scarlet Raven Tavern in Darkshire. It's a good joke. It's got a goat in it."] = { "e4c33418ef70", 6.56 },
		["I told a sentinel about it. She smiled and said yes, that's the tree, it's a thing visitors love to do."] = { "85c568d8ecb2", 7.81 },
		["I told her she had it backward. Surely the good straight wood should go where it's safe and dry, at the bottom."] = { "892b002b00a0", 6.97 },
		["I told her the truth. I said, you look six."] = { "c42be3f4e8ad", 4.39 },
		["I told her. She stood there a while, and put a hand over her mouth, and faded. I've wondered ever since what I should have said instead."] = { "061f5eabe746", 9.3 },
		["I told him as gently as I could. He kept feeding the fire. He said he'd known since his first winter."] = { "9e0e1dbf337a", 7.16 },
		["I told him he'd spelled it right. He looked at me, then at the list, and stopped tying the rope."] = { "8829e6298e84", 5.96 },
		["I told him the sky doesn't take coin, but plant that hill and wait ten years. He called me a fraud and took back his silver, very loudly."] = { "9da2c302de59", 9.95 },
		["I told him, and I'm ashamed of this, \"Not now. I'm waiting for a sign.\""] = { "2363e5b0feab", 5.07 },
		["I told him, as politely as I could, that he'd never see that one strung. He said of course not, and that he'd shot staves cut by a man he never met."] = { "cf130831778b", 9.77 },
		["I told it the whole thing, start to finish, things I'd not told the living. It didn't do anything. It only stayed."] = { "e0ad2f1b68b6", 8.52 },
		["I told myself it was an echo off the stone. So I whistled, to prove it. Nothing came back. I shouted. Nothing."] = { "e21f3484594e", 8.39 },
		["I told no one. And if you ever visit my people, you may hear the tale of the great storm that the kodo saved us from. It's a very good story."] = { "a571407347f5", 10.42 },
		["I told the Light plainly I'd stay on my knees until it spoke. One word, or I'd leave the order in the morning. I meant it, too."] = { "7c4b947bda2b", 9.04 },
		["I told them yes. That's what I'd been thinking. We looked at it for a bit longer, and then we went our separate ways without saying much else."] = { "6d1730a20c00", 9.06 },
		["I took a letter off one of theirs, after a fight in the rain. I couldn't read a word of it. I don't know why I kept it. Everyone kept something."] = { "814f80229719", 8.93 },
		["I took a room in a haunted house once, because it was half the price. Haunted, I said, is just another word for quiet."] = { "8d09d73a9bde", 8.33 },
		["I took it to a money changer, and he laughed so hard he had to sit down. There's nothing that coin can buy. There's no one left to honor it."] = { "e251609ab8f4", 9.3 },
		["I took it to her the next morning. She tapped it with a knuckle, said it was very nearly right, and used it to prop her door open."] = { "f6a659b91d19", 8.83 },
		["I took it. I can finish the fish one here, though. The rates around this fire are much better."] = { "d2890a3ce26d", 6.48 },
		["I took one plainstrider egg for my breakfast on the plains of Mulgore. One. There were lots. I was hungry and I didn't think anything of it."] = { "f5215d9eed96", 10.08 },
		["I took one step and the second arrow hit by my right heel. So I put my hands up and spoke to the trees. I said I was lost, and I meant it."] = { "3d0a3dda5b93", 10.29 },
		["I took shelter from a dust storm in a farmhouse south of Sentinel Hill. Nobody home, and nobody for a long time by the look of it."] = { "f6c5ace9e9d9", 8.75 },
		["I took that for nerves. I'm a talker when I'm nervous, so I kept up a stream of chatter, to myself, about nothing. And I was starting to notice less and less sky."] = { "fb73bd4d3f18", 11.49 },
		["I took that for superstition. Crooked wood's no good for anything, so why not clear it and be done?"] = { "5f72e626a3c1", 6.37 },
		["I took the hint. I've never been so politely thrown out of anywhere."] = { "35ec012f39f6", 4.81 },
		["I took the machine apart that evening. I've been buying my breakfast from a very distant farm."] = { "90c0e5832f9a", 5.9 },
		["I took the outside, by the drop, so they could keep to the rock. As we squeezed past, the wrapping slipped, and I saw it was only a bundle of small clothes."] = { "0e61bea28f4b", 10.32 },
		["I took the reins and backed the coach two miles to the last village, with the voidwalker walking backward in front of us the whole way."] = { "11375ee5579a", 8.1 },
		["I took the shirts down, and the cord stayed sagging. Something heavy and wet was still hanging there, and I couldn't see it."] = { "bbecca75b475", 7.81 },
		["I took these from a bandit who no longer needed them. He'd taken them from a soldier, who'd won them at dice."] = { "53c6797be1da", 6.79 },
		["I took up her sword and her debts. And I took up never offering anyone anything without a good long look first."] = { "2d6149a4046f", 7.39 },
		["I touched it. It was warm."] = { "69dd43897633", 2.53 },
		["I trained with someone who ran with the stags of Ashenvale for a season, and then another. The most gifted of us. A year went by, and we went to look."] = { "2024c774dbfc", 10.24 },
		["I tried honest work once. A whole week as a clerk. Very respectable."] = { "673c53591696", 5.69 },
		["I tried it myself. Walk, and there it was. Stop, and it was gone. I must've done that a dozen times out there, feeling very clever."] = { "96bb6c47bfb6", 10.48 },
		["I tried it once with a partner. They climbed, I kept watch, and we got past three guards and a very unhappy dog."] = { "9ca27668480a", 8.41 },
		["I tried it once. Crept in at night with a torch, quiet as a cat."] = { "929b63a4dfcb", 4.81 },
		["I tried three different openings. Halfway through the fourth, the bear opened one eye, turned into a very tired old druid, and said, try starting with the thank you."] = { "e93da8d76b30", 11.26 },
		["I tried. I gave it a big smile. Then a bigger smile. By the end it had more teeth than I do, and I have a lot of teeth."] = { "aa9becc573f4", 9.87 },
		["I turned around and there were six of them. Dwarves. Grinning. Arms full of snow."] = { "41413e5493c1", 5.96 },
		["I turned my practice partner into a sheep on the first try. I was so pleased that I ran to fetch the master, and I left the gate open."] = { "60bbdbe64bc8", 8.46 },
		["I use it every time I pass. He doesn't smile much, for reasons of jaw. But he always gives me the good candles."] = { "a1e93c4ba14b", 8.39 },
		["I used to carry a great deal more than this. Then I met a woman on the road carrying nothing but a wooden spoon."] = { "bc1ab6e7f2d8", 7.03 },
		["I used to think it was the cold. Then one night, on watch, I decided to hold still along with it. I wanted to see what it was like."] = { "6d34cd7ba850", 9.3 },
		["I used to think that made these nights small. An old trapper set me straight."] = { "9f2b785014dd", 5.07 },
		["I used to think that was nonsense. Then one night I sat there myself, and something breathed on my neck. Warm. Patient."] = { "059c20104ce5", 9.12 },
		["I used to think that was sad. Then an old soldier told me otherwise."] = { "a0dd1d40e60e", 5.07 },
		["I visited Orgrimmar once and got hungry on the Drag. There's a woman there with a cook pot the size of a bathtub. I asked for something mild."] = { "c80cb5f5f02a", 10.14 },
		["I visited him, years later. A little room with the shutters nailed shut. He didn't know me. He sat rocking, holding a dead crystal, whispering numbers."] = { "60a65e8c5327", 11.21 },
		["I wait by the water while you stand on the land. What am I?"] = { "728d9e1208f2", 4.52 },
		["I waited in a line in Darnassus once, behind someone very tall and very still, with no luggage. I stood there a quarter of an hour, politely."] = { "c3f387a3da4b", 9.9 },
		["I waited until I saw who came. Then I left without a word. Some people deserve to keep the version they're mourning."] = { "a1e970caf16d", 7.78 },
		["I walked back with a replacement I'd bought at market. It sat on it and looked at me anyway. I don't eat eggs now. It still knows."] = { "66c366c1286b", 8.52 },
		["I walked him out along the riverbed and up the bank. He thanked me twice. The second time was after he'd had a proper look at me, which I appreciated."] = { "df04ecef20c3", 9.64 },
		["I walked his land for three days. He'd cut down a whole hillside for more barley. What water came ran straight off, and took the soil along."] = { "65a83fcf6b0c", 10.66 },
		["I walked in by the broken gate, and there was a little old clerk at a little old desk, in the rain, with a ledger. He looked up and said, toll is one copper."] = { "63688343c137", 10.74 },
		["I walked into a bank of fog in Silverpine and heard rain. Heavy rain, drumming on leaves. I stepped back out, and it was a dry, still night."] = { "7beb72b991a4", 10.42 },
		["I walked out of that inn a skeleton. Bones and all. My own horse wouldn't come near me."] = { "5b75af594d0f", 6.06 },
		["I walked out there past Razor Hill with my whole savings in that paper. Red dirt, one cactus, and an angry boar."] = { "149b8d41dd65", 8.15 },
		["I walked out to him on top of the flood. The water bucked under my feet like a nervous horse. He climbed on my back with a goat under each arm."] = { "d7de88f8bddc", 9.64 },
		["I walked out to see it. There's only a chimney left on the mill road. I go every year now and clear the weeds from it. It doesn't help, and I don't expect it to."] = { "0e29509c067b", 11.34 },
		["I walked over to him at last and pointed behind him. He'd been standing on it. He thanked me, and shouted the news to everyone anyway."] = { "d9a1dd186819", 8.93 },
		["I walked until dark. There was no oak. There was no river. I've since crossed deserts and mountains without once losing my way."] = { "b45052810f59", 8.88 },
		["I wanted to be famous. Then I wanted to be rich. For one bad winter I wanted to be warm, and that was the best of them."] = { "4b725ed3b995", 8.05 },
		["I wanted to be sure she heard. She always did complain that I mumbled."] = { "568aca0e4858", 5.04 },
		["I was buying thread at a crossroads in Tirisfal when an old woman saw my face. She backed away, and she called me something. \"The one from the mill road.\""] = { "2a4632685317", 10.42 },
		["I was crossing Silithus with a trader when a sandstorm caught us in the open. We tied a rope between our belts so we wouldn't lose each other."] = { "26cd394e9d1e", 8.75 },
		["I was crossing a ford in the Riverglades with a peddler when the river rose in a rush, brown and fast. Rain upstream, he said. We were halfway over."] = { "c987a4ba0fd2", 10.08 },
		["I was crossing it at dusk. I saw a tower, and the shapes of a street, all perfectly still, and it was very beautiful. I got down on my knees to look."] = { "de6a0fd9b0da", 11.62 },
		["I was delighted. Then there were two leaves. Then a twig. By the end of the month I was leaning on something with opinions about where the sun was."] = { "ae0ea555f405", 10.14 },
		["I was eight when I went round the back of her hut and saw it. One big crab, in a bucket, and six little pots of paint."] = { "44c30069f9d4", 7.99 },
		["I was gone twelve years. When I came home at last, I walked out to look at the spot, not expecting anything. And there was a knot in the grass, fresh that spring."] = { "54f33be98de9", 11.68 },
		["I was grown before I understood what that humming was for. It was so I wouldn't hear the water. I can't listen to that song, mon. Not even a little."] = { "356e8b3d52b7", 9.82 },
		["I was helping a drummer carry his big drum through the Valley of Strength in Orgrimmar when a cart rolled into him and pinned him against a wall."] = { "a689ec0b4f77", 8.41 },
		["I was helping a farmer in Westfall carry flour up to his loft when the latch on the door below lifted, very slowly. He put a finger to his lips."] = { "a854ccaa9606", 9.46 },
		["I was helping a logger in the Stonetalon Mountains when the brake gave out on a log chute. A whole trunk came screaming down the slide toward the river."] = { "1fea22f5a5fa", 9.12 },
		["I was helping a scholar sketch a carved archway in Shen'dralas when one of the old columns started to lean. She was sitting right beneath it, drawing."] = { "d5f99cf7c8f0", 9.35 },
		["I was hungry and foolish, which is the best way to enter a contest. I won by one spoonful."] = { "0a5fdc1f6998", 6.74 },
		["I was impatient. I had my own studies. I skipped things. Whenever I did, he'd wave one finger and make me go back and read that part again, slowly."] = { "93a7a2fdf4f0", 10.5 },
		["I was invited into a very small tavern once, by very small and very friendly people. I ducked. I did not duck enough."] = { "6e91f4b44067", 9.46 },
		["I was near the Crossroads when a fellow on a hill bellowed out, asking where the Wailing Caverns were. Just one simple question."] = { "c594e052bae3", 8.39 },
		["I was on a ledge at Windshear Crag in Stonetalon, with a wind that wanted me dead, when a harpy came down out of the sun and grabbed my pack."] = { "a08a77271a14", 9.48 },
		["I was on my feet with my hand at my belt before the pieces stopped spinning. I don't know what my face was doing. The whole room knew, though."] = { "d13dc9cc02a8", 9.46 },
		["I was one dent from losing. The other fellow's tonk was chasing mine round and round a barrel."] = { "77f2efaeebc8", 6.56 },
		["I was out on a high ledge, leaning on the gale like you'd lean on a wall. Everyone does it. It's a wonderful feeling. And then, all at once, there was nothing to lean on."] = { "bdb3403f446b", 12.38 },
		["I was out past the hives with an old guide, and he stopped to fix a strap, and the hum stopped too. I thought nothing of it. Then he started walking, and it started."] = { "bee117f16cf1", 12.04 },
		["I was out with one of them when his net came up heavy. Fish, weed, an old boot. And sitting right in the middle of it was a silver goblet, shining like new."] = { "f805a99a807c", 11.39 },
		["I was over the edge with the sea coming up. Then the wind came back, from underneath, and it threw me. Up past the cliff, past the gulls, higher than I've ever been."] = { "ce2640d9c317", 11.08 },
		["I was riding a supply lift down from the high forge in Ironforge when the rope started to fray. I could hear it, strand by strand, like someone tearing cloth slowly."] = { "8d411ab77317", 10.61 },
		["I was sitting by Lake Elune'ara in Moonglade one evening when it started raining on the far side. I could see the drops on the water. Not a cloud overhead."] = { "9871733e89d4", 9.72 },
		["I was sitting on the bank there one morning. A figure in a long cloak came down and stood at the edge, not breathing, and I kept my hand near my weapon."] = { "ecd1f9ac54f7", 9.64 },
		["I was so hungry once that I walked into a stranger's funeral for the food. Then they asked if anyone would like to say a few words."] = { "f8787d22689b", 7.99 },
		["I was twelve years old. All I did was hold the lantern."] = { "2dfcbac7565b", 4.34 },
		["I was up on Thunder Ridge when the sky turned purple and every thunder lizard in Durotar started running. Straight toward me."] = { "0fd6e4591741", 7.99 },
		["I was walking a plank path through Dustwallow Marsh after dark, and I happened to look down. My lantern's reflection in the water was burning green."] = { "14ce4ead07c9", 9.64 },
		["I was walking the ruins at Ameth'Aran, and a pale figure in old-fashioned robes fell into step beside me. Friendly enough. See-through, but friendly."] = { "ca6468641bd2", 10.08 },
		["I was walking under the scaffolding of a chapel being mended when a mason lost his footing on the top boards. A long way up."] = { "722c6587e3ca", 7.99 },
		["I was walking up the hill out of Goldshire when a farm wagon came down it backward. No driver, no horse, and a load of pumpkins piled higher than my head."] = { "420012e76e58", 10.92 },
		["I was wearing it. I looked down to check, and I was wearing it."] = { "3e94146c9d51", 3.81 },
		["I was young, so naturally I counted. And at the very end of the line walked someone on two legs, slowly, with a kodo harness over one shoulder."] = { "fc2219f26378", 10.06 },
		["I was, I thought. A small errand came up in the south. When I returned, the shop had a new sign, and a young man was minding the counter."] = { "36cf506cc948", 10.42 },
		["I wasn't anyone to her. A stranger in muddy boots, from nowhere she'd have cared about. But I must have looked at that pole a certain way."] = { "3f0bd43a4b5a", 9.72 },
		["I watched a woman tie a new one on. She told me there's one for each person a family has lost, or who's gone so far that it comes to the same thing."] = { "892c7bedcc06", 10 },
		["I watched it go for most of an afternoon. I could have caught up at any moment. That's what stung."] = { "a23b2eb4c995", 6.61 },
		["I watched like a hawk. Pointed at the middle one. He lifted it. Empty."] = { "7a2c77fd9921", 5.72 },
		["I watched one go down to the shore one morning. Big fellow. He waded in up to his waist, looked that sea right in the eye, and he started yelling."] = { "3c0a9ba36958", 10.61 },
		["I went after him and cut the cloth off the pole while he shouted at me for ruining it."] = { "48eb8fccf39e", 4.99 },
		["I went around. It took two hours. I recommend it."] = { "3137c867f39c", 3.79 },
		["I went back and asked the seller if she knew. She said she'd sewn it herself, the year her husband gave up stealing."] = { "eda81c6e7c75", 7.16 },
		["I went back for more. He'd put the price up. Turns out half the town buys them, and nobody lights them indoors."] = { "6aef9a694261", 8.52 },
		["I went back in the spring, and I left a good pair of shears hanging on the lowest branch. By summer they were gone."] = { "dae7cec952b9", 7.37 },
		["I went back last year and laid my hand in it. There isn't one strong blow in the whole of that groove. Only a great many mornings."] = { "22c2d0aa19b0", 9.06 },
		["I went back out into the storm. Say what you like about choking on dirt. Nobody's ever saved a place for you in it."] = { "0440346785fb", 7.78 },
		["I went back out over that sill very politely. I closed the shutter after me. I don't know why that seemed important, but I'm sure it was."] = { "6f9feae09244", 9.35 },
		["I went home after six years, and my sister ran out to the gate and threw her arms around me. Nobody had held on to me like that in a long time."] = { "ca55ae8fb785", 9.59 },
		["I went home, a few years back. Walked for a month to do it. I had a whole speech ready."] = { "8f25978e3a54", 6.53 },
		["I went into a sea cave once to gather salt. Black water at the back, flat as glass. I hadn't said a word. I hadn't even unpacked."] = { "c957318b8c97", 10.08 },
		["I went into the mire to my waist in Sundown Marsh. The more I fought it, the more it had me. Up to my ribs inside a minute."] = { "379528f5eaa8", 8.52 },
		["I went looking for my own grave once. Out in Tirisfal. I wanted to see what they'd said about me."] = { "3a6624af9af5", 6.74 },
		["I went looking through what's left of the house, after. The roof's gone and the walls are mostly gone, but I found them in the cellar. Every plate, without a chip."] = { "59ddfcd3a3fe", 10.24 },
		["I went over the load cutting ropes. Off with the kegs, one after another, to lighten her. Thirty. Twenty. I think I wept at twelve."] = { "fc76aa373531", 10.92 },
		["I went there alone. It was a still sort of evening. I sat with my back against a rock, a long way from the drop, and listened to it mutter."] = { "5ffef5fb5c18", 9.87 },
		["I went through a skylight in a shower of glass and came down in the center of a long table, in somebody's very nice dining room."] = { "f51c552d99de", 7.5 },
		["I went through it all again. And again. I was still at it when the sun came up."] = { "6069bad8b10c", 5.59 },
		["I went to Moonglade to thank a druid who once saved my life, and I'd written a speech. Six pages. I rehearsed it by the lake, to a sleeping bear."] = { "d6a5a87f157f", 10.84 },
		["I went to his daughter's wedding in the end. Never did find the Trade District."] = { "569a95b19e12", 5.41 },
		["I wiped the frost away with my sleeve, and there was a window, far down in the top of that tower. There was a small light in it, very warm and very steady."] = { "5dd3d0d683b4", 10.48 },
		["I wiped the glass. Still green in the water, yellow in my hand. So I held it closer to the water to get a better look."] = { "7581d4ebc4eb", 8.05 },
		["I woke up by the same stone, still sitting just as I'd been. But my water was gone, the moon was the wrong shape, and it had been three days."] = { "4f3450ffb560", 10.74 },
		["I woke up cold in the gray before dawn. I was on my feet. Boots laced, gear on, facing north."] = { "343ba378b4ef", 8.15 },
		["I woke up in the morning a mile from town, with no silver and no hat. But I had a blanket over me, and that pig was asleep at my side."] = { "d7a4ea2c02ab", 9.77 },
		["I woke up standing to my knees in that lake, soaked and freezing, facing the island. My bedroll was a long way behind me."] = { "1fc57b5ef081", 8.8 },
		["I woke up the next morning in a stall at Amberstill Ranch, wearing a ram's blanket, with no memory of the walk."] = { "3043196284aa", 7.55 },
		["I won the bet. And I've still got the scale. It's been ten years and it's still warm, and I'd say that some nights lately, it's been getting warmer."] = { "bd74c5deaf57", 9.17 },
		["I wrapped it round him and dragged him out. The banner came home with a tear down the middle, and so did he."] = { "6fb7e687ecdc", 6.53 },
		["I wrote FAILED across the drawings. A miner saw them over my shoulder and asked if he could buy a dozen."] = { "741f8eddd4bd", 6.66 },
		["I wrote it down, with her blessing. I've left room under it for the next one somebody teaches me."] = { "bef037926edf", 6.71 },
		["I wrote to tell her. The letter came back with one line on it: \"Good. Come back next winter and we'll do your eyes.\""] = { "9d8b7c1b8f02", 8.33 },
		["I wrote. I expect they did too. The roads have a way of eating letters."] = { "197395c8efd4", 5.54 },
		["I yelled at it. I said I'm fine, I've got plenty of water, go find someone else. It looked at my waterskin, and then it looked at me."] = { "53b49f1063c2", 9.46 },
		["I'd already had two bowls. I thought it over. It was a cold night, so I had a third."] = { "58ba977e106f", 6.79 },
		["I'd been asked to judge the pies. I had crumbs on my tabard and nothing in my hand but a fork. So I did what I was trained for."] = { "d3b73f41b418", 9.12 },
		["I'd been on that coast a month. I'd heard the noises they make. How hard could it be?"] = { "f62abd950c2d", 6.53 },
		["I'd camped on the beach at Southridge, on the coast of Azshara, and I woke in the night with cold water around my ankles. Just the tide, I thought. I'd misjudged it."] = { "048e7f1e721a", 11.62 },
		["I'd camped on the far shore, a long way from it. I'm not a fanciful person. I heard the bell in my sleep, and I thought nothing of it."] = { "9156f62dc4f6", 8.83 },
		["I'd carried a little mace for nine years and never hit anything with it. I couldn't find it. What I had was the Book of Mercies, brass at the corners."] = { "35ac61c3078c", 10.37 },
		["I'd come up that path. Nobody had come down it to look. I didn't stay for supper, and I didn't follow the path back the way I came."] = { "8cd70c25a57f", 9.12 },
		["I'd followed a raiding party in Ashenvale to get back a satchel of seeds they'd stolen. Then the whole party stopped right on top of me to argue."] = { "b91c39be9f25", 9.06 },
		["I'd got to thirty-one by that first night. It was twenty-nine by the time I left. I don't find it restful any more."] = { "eb94607fc417", 8.33 },
		["I'd just eaten the best fish supper of my life, so I stepped on the scale and he charged me nearly double."] = { "77c723df49ae", 6.84 },
		["I'd like you to think about that. I had just spent three days trying to get out of the mud. I'd lost two boots to the mud. And he said this mud was special."] = { "d7a377f18c28", 10.79 },
		["I'd started talking to whoever it was. Then, three days past that last one, another stone: \"Nearly there was a lie. Sorry. Keep going anyway.\""] = { "1e1447f41a2c", 11.73 },
		["I'd walked all morning. I sat down against a stone for an hour. Only that. I remember how soft the light was."] = { "d908d28256d3", 8.52 },
		["I'd walked past that hollow for years. It has the best view of the sky on the whole island. I'd never once sat down in it."] = { "5c207964f7ec", 8.57 },
		["I'd walked past that next tower on my way up. Roof gone. Nobody had been there in a decade."] = { "af2cac5b63fc", 6.95 },
		["I'll admit it, I sold them all. That's how I paid for this armor."] = { "59922bc8e084", 4.75 },
		["I'll be here all night, friends. Unfortunately for you."] = { "573873acdaea", 3.81 },
		["I'll bind up your wounds when you're too hurt to stand. What am I?"] = { "dd764473a022", 4.86 },
		["I'll let you guess what I hear these days."] = { "756c6c6d2f9b", 2.53 },
		["I'll say this for it. In six years, not one bandit ever worked that road."] = { "fae6ca194efe", 5.69 },
		["I'll say this, though. I've never had faster service. Nobody at that inn had slept in years."] = { "3e75168e3d72", 6.74 },
		["I'll tell you about the worst healing I ever did. It worked perfectly."] = { "3bf6a5b61532", 4.88 },
		["I'll tell you what kept him up at night, though. All those years, and nobody had asked who closed it, or which side they were on when they did."] = { "9e816c33ec83", 8.46 },
		["I'm a long way from there now. Colder places than I'd like. But some nights, when I'm camped alone and the wind's up, I feel a weight settle on my ankles."] = { "d8cabcf2c48f", 10.92 },
		["I'm beginning to think it isn't left over. I think it's following me. I'd go back and apologize, if I knew what for."] = { "45c54d72d3bb", 8.52 },
		["I'm cloth that is torn so a wound can be bound,"] = { "1741820c39e8", 3.74 },
		["I'm empty by morning, by nightfall I'm stuffed. What am I?"] = { "962c3be2662f", 4.81 },
		["I'm never once drawn in a fight or a fray,"] = { "0b27e159a841", 3.03 },
		["I'm not a sailor. Neither was anyone I was traveling with. We moved our camp that night, a good long way from that crack."] = { "19a9d2fa2ddc", 8.33 },
		["I'm not saying I've won. I'm saying that one of us is going to be very surprised, and I sleep quite soundly."] = { "2e10a64aca45", 7.39 },
		["I'm still not sure how we got out of that one."] = { "7831cc6abce3", 2.56 },
		["I'm still wearing it. Two lefts. I've got a limp now, in a circle. I've come to think of it as store credit."] = { "3d03de3dbfbe", 8.05 },
		["I'm sure it wasn't you. But if it was, you should know the mule and I made up. We're very happy."] = { "deb4f71f081b", 6.61 },
		["I'm the friend that a warrior will carry and keep. What am I?"] = { "e13d226fa862", 4.75 },
		["I'm told I lasted nine rounds. The pig was very gracious about it."] = { "7c4697175afe", 4.94 },
		["I'm torn from the foes that a warlock has overthrown. What am I?"] = { "96e599651cf3", 5.07 },
		["I've a line but no words, and a hook but no hand."] = { "d20a245a90e5", 3.81 },
		["I've asked every druid I know. Nobody's missing. Nobody was out that way. I don't wave at deer anymore."] = { "9d02ee636a8c", 8.46 },
		["I've asked soldiers on both sides. Each says it must be the other lot, and they laugh at the notion, and they all take an apple as they pass."] = { "1c4a14f5d552", 9.12 },
		["I've bargained with things older than the sun, and she's the only one who ever came out clearly ahead. It does wipe its feet."] = { "df4ed378d1c0", 8.15 },
		["I've been carving this for six years. It started off as a chair leg. It was going to be a horse."] = { "c1826b6e2bae", 6.74 },
		["I've been dead for five years. I've walked through things you wouldn't believe. I don't mind telling you, I ran."] = { "1d8381a03df7", 7.44 },
		["I've been down to the Undercity, and I've walked through the Apothecarium. People ask if it's the smell that stays with you. It isn't."] = { "2a56cf3d4214", 8.93 },
		["I've been let down by a lot of things that promised me the world. Never once by that keeper."] = { "4fdcff1e68c5", 6.11 },
		["I've been paying three silver a month. Honestly, it's nice having someone out there who still expects to hear from me."] = { "a2129e0af6d0", 7.55 },
		["I've been that tree a few times in my life. Useless, as far as anyone could see. I've been very grateful for the people who remembered the bees."] = { "987836fc2893", 9.64 },
		["I've been writing this for three years. Every town, I add a little more."] = { "37904c419ae4", 5.59 },
		["I've booked the next two years with him. I hate to waste good candles."] = { "80a0ee9a51d8", 4.39 },
		["I've carried a spare loaf ever since. Handed out more bread than I've swung swords, some years."] = { "4c6368feb841", 6.56 },
		["I've carried a spare skin ever since. Nobody has ever thanked me, and nobody's going to. I find I like that about it."] = { "40739e00f14d", 8.2 },
		["I've carried that bowl through many doors. I've only spilled it twice. I remember both names."] = { "cd38275efc61", 7.03 },
		["I've climbed a lot of stairs since. I still look for the missing one. It's surprising how often there is one, if you watch."] = { "6d31f66ce08e", 8.2 },
		["I've done a lot of work since that nobody saw. I don't mind it the way I used to. I like to think somebody will find it, eventually."] = { "fbb774c9dbc4", 8.88 },
		["I've drunk in a lot of taverns since I came down from the mountain. Not one has poured a proper pint. I keep checking, mind."] = { "f754dccb97c7", 8.62 },
		["I've got a lot of respect for it. I woke up in a drift, and it was standing over me, hooting and clapping, and waiting for me to go again. They do like to play."] = { "cadf71dddd08", 11.44 },
		["I've got no idea who. I've asked. The nearest person I could find was at Scrabblescrew's Camp, and he only wanted to know if I had any spare food."] = { "b392226cd58e", 10.08 },
		["I've got no such gift. But I still touch the walls wherever I go. It seems rude not to say hello."] = { "639f0bb7f600", 8.23 },
		["I've got that tree still. It has six branches now. I've stopped asking it to hurry, and it seems happier for it."] = { "c72be797e681", 8.39 },
		["I've had it nine years. It has threatened to devour my soul only twice. It has mentioned the sleeping arrangements every single night."] = { "604296d5882e", 8.99 },
		["I've learned the tune since. I still stumble on that note. I practice it outside, in case somebody's listening."] = { "482d05c92e78", 8.05 },
		["I've made a few adjustments since. It's only destroyed one bed this year, which is a great improvement."] = { "66b695f502f8", 6.71 },
		["I've made one or two bad things since. I don't cry about them. I just find a nail."] = { "31d06d7c4372", 6.14 },
		["I've met a lot of people since who were only tempered once. You can hear it when they get knocked."] = { "fcb89de81841", 5.49 },
		["I've named him Councilor. He doesn't say much, and he takes more than he gives. I was charged extra for him, as it turns out."] = { "d6023c896760", 8.8 },
		["I've never been sorry. I want that understood. The price was exactly what they told me it would be."] = { "1bae4ff8b563", 7.16 },
		["I've never found the Hobbs place, though. Some nights I still think about it."] = { "9f550c38d691", 4.75 },
		["I've only been asked back once. That was when I told the host that what was in her pantry wasn't mice, and was about the size of a pony."] = { "94c19881708c", 7.99 },
		["I've outlived four warlocks much cleverer than I am. Not one of them could cook."] = { "e64ac02f807f", 5.59 },
		["I've sat a great many vigils. You learn to keep count of a sleeper's breath. It tells you when to send for the family."] = { "0c28be41b801", 7.73 },
		["I've sat at all kinds of fires, with all kinds of folk, and they all do the same thing the moment night comes on."] = { "e06df9518438", 7.21 },
		["I've seen a lot of country since I left Elwynn, and every bit of it is trying to kill me. Elwynn only ever tried to feed me."] = { "bf86d63d9cf9", 8.28 },
		["I've seen what happens to those who stop thanking. They get very good at killing, and then they're not much good for anything else."] = { "58071c7ef80e", 7.81 },
		["I've started cutting a stave every spring, though I can't work wood to save my life. They're for somebody."] = { "4f8be29df7aa", 7.08 },
		["I've still got it. I keep it in my pack, and I've never yet tried it in a door. I worry about the day I find one it fits."] = { "e56afe14cf25", 8.99 },
		["I've stood where each of them lies. One on a quiet hill, one in a canyon that still smells of smoke."] = { "8a086987a4e9", 7.03 },
		["I've used that more than I'd expect, far from any swamp. When a path is too smooth, I go around it."] = { "f0b4f8a2104d", 7.5 },
		["I've walked past a thousand good hillsides since. Fine soil, clean water, a kind slant of sun. Every time, I've stopped and thought about it."] = { "9c67a978ddc5", 10.89 },
		["If the meal tastes of nothing, thank me. If it tastes of something, don't ask what."] = { "e064d1e89c24", 5.54 },
		["If you can hear them, they aren't ours."] = { "f8df0a6f75cf", 2.48 },
		["If you ever run dry on the Gold Road, look for a flat rock that doesn't match the others. There's sometimes a waterskin under it."] = { "fd46f520ea59", 8.57 },
		["If you hear anything tonight, it's probably just the wind. Probably."] = { "ea11d9aa9e0a", 4.81 },
		["If you look at the walls in the morning, when the ash is thin, there are shapes burned on the stone. Dark outlines, and pale ones. They look like people."] = { "4489679a167a", 10.74 },
		["If you stand on the hills in the north of the Eastern Plaguelands, you can see Stratholme. And you'll see the smoke. It still goes up, after all these years."] = { "7fe6618d869b", 10.24 },
		["In Astranaar there's a woman named Raene Wolfrunner. She had an old friend called Teronis, who went out into Ashenvale to help the Sentinels against the furbolgs. He never came back."] = { "ca25ebf38e28", 12.33 },
		["In Brill, I ordered a little cake for the day I woke up as myself again. The baker asked how many candles. I said I'd stopped counting."] = { "eef215e3c52b", 8.83 },
		["In Brill, a man paid me a silver to carry a letter to a woman on a farm outside Tirisfal. He asked one thing: if she asked what he looked like, I wasn't to tell her."] = { "876b0592483d", 11.55 },
		["In Darkshire they say a ghost in a fine old coat leaves a single rose on the windowsill of whoever's sleeping alone at the inn."] = { "2d16d07db6b1", 7.81 },
		["In Darnassus there's a moonwell in the Temple of the Moon, so still it's like a mirror. I leaned over it one night to see my own face in the silver."] = { "efb2f20dc595", 9.77 },
		["In Gadgetzan you can hire an umbrella by the hour. I hired one at noon. The goblin asked when I'd bring it back, and I said when the sun went down."] = { "783b37ee1778", 9.12 },
		["In Lakeshire they told me the family who dug that well gave each child a white stone on their naming day. I've still got it. I don't know whose it was."] = { "7ae8bb618550", 9.64 },
		["In Moonglade a cart horse spooked and bolted for the lake, with a child tangled up in its lead rope."] = { "f93037d6e9cf", 6.74 },
		["In Mulgore, we say that the wind is the Earth Mother breathing out. Stand in the tall grass at dusk, and you'll feel it."] = { "5025de31dad3", 8.15 },
		["In Shen'dralas I copied a strange mark off an old stone, so I could ask a scholar what it meant."] = { "db1c6d2d1e7d", 6.48 },
		["In Teldrassil I asked an old druid to teach me how to grow a tree. She gave me a seed and told me to come back when it had a branch."] = { "77115b03edd2", 8.65 },
		["In Thelsamar I asked the cook how you know a stew is thick enough. She said a spoon should stand up in it on its own."] = { "843153548db9", 7.37 },
		["In Thousand Needles I let a rope down a crack in the rock to see how deep it went, with a stone tied on the end. Fifty feet down, it stopped."] = { "6422e12b9aca", 9.9 },
		["In Un'Goro Crater, you feel a devilsaur before you see it. There's a thump in the soles of your feet. Then birds go quiet, all at once, and you've got about a minute."] = { "9f4ce7f4a12e", 11.02 },
		["In a book from the deep shelves, I found a note beside one formula: \"Carry the seven, you fool.\" I thought nothing of it. My work there was fine."] = { "bda6aa333bc2", 10.32 },
		["In my fifth year, I decided I had made a mistake. All that prayer, and nothing had ever answered. So I went up to the little chapel to wait for a sign."] = { "029e60e75600", 10.37 },
		["In the Eastern Plaguelands, on the bank of the Thondroril River, there's a little hut. An old man lives there, fishing, keeping to himself. Most folk took him for a hermit gone a bit soft in the head."] = { "caba1260c1a4", 12.98 },
		["In the Riverglades I helped two neighbors put up a fence between their farms. They'd been arguing over that boundary longer than either could remember."] = { "7f972cee7cfc", 8.8 },
		["In the Second War, every army of the Alliance followed him. Near the war's end, at Blackrock Spire, he was cut off from his men and met Doomhammer alone."] = { "8c386843a375", 10.55 },
		["In the Stonetalon Mountains I met a woman planting saplings in a valley that had been cut bare. One at a time, by hand, from a single basket."] = { "dde917aa1fd3", 9.53 },
		["In the Swamp of Sorrows I set a bowl of clean water by my bedroll for the morning. At dusk I looked in, and it was full of stars. The sky was solid cloud."] = { "4de7329cef9f", 11.55 },
		["In the Wetlands I walked with a guide who could tell, just by looking, which mud would hold you and which would swallow you to the waist."] = { "d91e9464e9a6", 8.39 },
		["In the end I planted it beside the road. It's a proper tree now, leaning very slightly toward the road."] = { "2e5898082868", 7.16 },
		["In the end he picked me up, set me in the lift, got in after me, and said there. Now neither of us went first."] = { "aaa1e0996629", 7.68 },
		["In the fight, part of the old tower came down and knocked Tirion senseless. Eitrigg could have finished him."] = { "b552cfcb055a", 6.9 },
		["In the middle of the wall was a mount with nothing on it. Good wood, nicely carved, and empty."] = { "2e3b8e950377", 6.71 },
		["In the morning the water was clear and ordinary. I poured it out on the ground anyway. I didn't fancy drinking somebody else's sky."] = { "1445d735abc3", 8.99 },
		["In the morning, one of our number had left his boots by the fire and walked away. There were bare footprints heading to the cave, and the stride was unhurried."] = { "e73310fdac8c", 9.59 },
		["In the ruins of that schoolhouse there was an old footlocker, and in it a letter he never sent. To his old headmaster, proud as a boy, telling him how well he was doing."] = { "af206ad8122a", 10.97 },
		["Inside was a wooden button. The very one that fell off my mother's coat the winter I left home."] = { "18099c63854b", 6.11 },
		["Inside were a hundred more treasure maps, and a note: ten gold each, you know where to find me."] = { "4c9b87dfe13e", 6.9 },
		["Instead he pulled Tirion out, tied him to his saddle, and sent the horse home. Tirion told his people the orc had been dealt with, and kept the secret."] = { "a96f17d6b0fc", 9.9 },
		["It blew a gale by noon. The old fisher found me holding onto a fence post with both arms."] = { "a8952f4911df", 6.56 },
		["It bought a comb. A very fine one. Every morning it leaves the comb beside my bedroll, without a word."] = { "e6f767de0366", 7.99 },
		["It burned all afternoon, and it smelled wonderful. That's what nobody warns you about."] = { "93f367474159", 6.24 },
		["It came after me across the moor at midnight, tall and thin and quiet, and it was gaining. I ran till my lungs burned, straight for the stream."] = { "50fdccbdcabd", 10.42 },
		["It came back at dawn, limping, dropped down beside me, and gave me a long look. As if I'd miscounted on purpose."] = { "c6b432743e6f", 7.86 },
		["It came down to drink, right beside me. I could've counted its teeth. It's got more than you'd think. Hot water was slopping into my nose from each swallow."] = { "53eb2e03fa71", 11.08 },
		["It came out of the pines at full charge. I hit the ice running, and I could hear it behind me, closer every stride. Then I heard the crack."] = { "de333a4cd6b3", 9.82 },
		["It came roaring out of the ferns and had the back of my coat before I'd reached the first branch. So I left the coat. I went up like a squirrel."] = { "83cbbdbf6151", 9.12 },
		["It climbed too. It climbed for an hour! I kept going, past where the branches got thin, until there was nothing above me but the sky."] = { "c328cc574195", 10.08 },
		["It did pass. I went back a month later to look. That post was clean, and there was a ring on the next one along, a little closer to the road."] = { "6a4455603418", 10.42 },
		["It didn't see me, or it didn't care. It yawned, and I felt it in my teeth. It stayed there until nightfall, and I've never lain so still in all my life."] = { "807cdfe29302", 11.96 },
		["It doesn't have any sorrows of its own, he said. You bring them. I was four days getting out of that swamp, and I can tell you he was right."] = { "83d11be9a6e2", 9.48 },
		["It doesn't work like that. They aren't servants, and they don't come when called. I asked for her for ten years and got nothing at all."] = { "a62ab5f3ea55", 8.46 },
		["It doesn't work. But I keep buying pears. The merchants in Tirisfal must think I've got quite the appetite."] = { "fddbabc35e01", 7.68 },
		["It dropped me to free up its fists. As I left, the left head was shouting about something from years ago. It didn't sound like my fault at all."] = { "30a548e7feb4", 9.95 },
		["It dropped the net. It stared at me. Then it screamed, and every murloc on that beach came running."] = { "21b7f2285d9d", 7.44 },
		["It echoed. Hippogryphs took off. Across the water, somebody dropped something. Every head on the terrace turned, very slowly."] = { "072d8df02589", 9.72 },
		["It faded by morning. The mages I showed it to said it was residue, nothing more, and it would pass."] = { "4080f46927cd", 6.9 },
		["It gave up at dusk. And I sat there with the whole forest under me, and the sea on one side, going gold. That's the best view of my life, and I owe it to a yeti."] = { "aa7cb8e65e6d", 11.39 },
		["It gets cold in the Burning Steppes at night, if you can believe it, up on the black rock. I woke with something warm curled against me in my bedroll. Very nice."] = { "7b29a9f4bfc2", 10.66 },
		["It had my rod in its jaw. Also two other rods, a small anchor, and a helmet. I got my rod back. Nobody claimed the helmet."] = { "aab7507ab02c", 10.5 },
		["It had six leaves. My companion pointed out that I was mostly sitting in the sun. I said I was encouraging it."] = { "7c31d98eca63", 7.63 },
		["It had to do with something I'd done that week, under orders. I'd thought the orders would be enough."] = { "c660c1e025a7", 6.53 },
		["It had walked me out there to keep me from the farmer. I've had worse friends, and most of them could talk."] = { "4b2721565582", 6.01 },
		["It happened in the half-dark. The shields gave way on the left, and something big came through, heading straight for my wounded."] = { "780b76ccf06b", 8.2 },
		["It has no malice, you understand. I went up afterward, and the ground was still warm, and it wanted to know if I needed anything else."] = { "d57e9bbbc651", 8.65 },
		["It hasn't passed a single law. Folk there say that's the best record anyone's ever had."] = { "59f32653923d", 5.96 },
		["It helped for nine miles. It helped the raiders, and the orchards below them, and the two farms we'd meant to protect. It was so pleased to be asked."] = { "fa07e1917edb", 9.59 },
		["It kept that thing for over a year. It went green, and then it went hard. Neither of us has ever mentioned it."] = { "e8c72a5a9f88", 7.31 },
		["It knit in an instant, strong as oak and crooked as a dog's hind leg. Undoing it meant breaking it again, and he wouldn't have that."] = { "78a7f33564ac", 9.48 },
		["It landed on the table, still holding three kings. Nobody said anything. A big fellow across from me went a remarkable color."] = { "dc692f92be0b", 9.48 },
		["It listened. I felt it lean on me, like an ox leaning on a gate. Behind me the last carts came down, then the elders, then the goats."] = { "06b76e19bbf6", 10.19 },
		["It lit my fires. It cooked my meat. It was the best camp I ever kept, right up until it worked out what my boots were made of."] = { "eea341aea144", 8.99 },
		["It looked at me, blinked, and flew off without paying. I felt much better. I think about going back."] = { "ae79648f5562", 7.73 },
		["It looked at that smudge. It looked at me. We both knew. I bowed as low as I've ever bowed, and after a long moment it left by the door they'd opened for it."] = { "56a8a1fa8e69", 11.15 },
		["It looked down at its chest. It looked at me. And then it bent over, very slowly, and it scooped up a snowball about the size of a wagon wheel."] = { "cd6097ca87a7", 9.77 },
		["It looks me right in the eye while it does it. No shame at all. I've shouted at it. I've moved camp. It finds me."] = { "5c20de0f108e", 8.83 },
		["It lunged and clamped down on my pack. I held on to the straps, because that was all there was. It thrashed, and it hauled me out of that mud like a cork."] = { "04df61e5822a", 10.5 },
		["It marks the night they broke free of the Lich King's voice, and found their thoughts were their own again."] = { "8870559a9ab6", 6.11 },
		["It meant he would let me tell mine. Silence was the ordinary rate."] = { "57b1f093b7ac", 4.81 },
		["It parted all at once. I came up with half the sea in my chest, and saw a gray fin turn around, slowly. I never swam so well as I did for those forty yards."] = { "4c7a7b3f965c", 10.61 },
		["It passed unanimously, at a temporary location, by the five of us who still had the eyebrows to look serious about it."] = { "0815711a5ae8", 7.63 },
		["It rained on him. I'd have told him, had he asked me back. Nobody ever asks me back."] = { "a692d8b1cb3f", 6.37 },
		["It seems I did that. During the senior elder's remarks. For some time. I'm told I also sniffed a visiting delegate, thoroughly, and sat down on the floor."] = { "3a84a4ed2e62", 11.49 },
		["It should have been one day's walk between two villages. By the second evening, I passed a lightning-split tree I was sure I'd seen that morning."] = { "3cb170e43f73", 8.83 },
		["It stayed just as far off all afternoon. But by evening it had led me straight into a camp of salt cutters, and they gave me water and asked no questions."] = { "71533d00a837", 10.08 },
		["It steered me. I don't know how else to put it. Around the bad streets, away from the sounds. It took me clear out to the far side of town, and there it stopped."] = { "4ab2268a8a6d", 11.86 },
		["It still works. The earth doesn't care about art. But a whole generation of children believe I worship a duck, and I've stopped correcting them."] = { "d6279c51b9d8", 9.4 },
		["It stopped at the gates of Ironforge, right in front of Greatfather Winter, as if it had meant to go there all along. He thanked me for walking it home."] = { "e2381fee79b8", 10.08 },
		["It takes a good while now. Last week I got to the end, and I had the feeling I'd skipped someone."] = { "3f4d30b01423", 6.71 },
		["It took all morning to sort out, with a lot of pointing, and one of us close to tears. I won't say which."] = { "b0baf7e410b8", 7.37 },
		["It took all night. Every one of those stones was somebody I'd never meet. I went back in spring and added two."] = { "7fa47822259e", 7.97 },
		["It took four days. There was a bog. There was another bog inside the first bog."] = { "316970ea63a6", 6.24 },
		["It took its time and looked around. It looked right at me, I swear, and saw one more rock. When it left, I climbed out the color of a boiled crab, and I lay on that bank and cried."] = { "690e38f53625", 12.88 },
		["It took me a while to see what was wrong. You board up to keep thieves out. These doors had heavy bars across them on the outside, the kind you use to keep something in."] = { "255b6589a248", 12.41 },
		["It took me a while to understand they were the solution to the problem I'd been stuck on for six years."] = { "250c1cbb466b", 5.72 },
		["It took me far too long to remember my first lesson. It still blows just as hard, but I'm not falling now. Some days, it even holds me up."] = { "c504cb3b0868", 10.84 },
		["It took me nineteen years. The day I got it right, I told no one. I put on a clean robe and opened it on the first try. Same table. Same blue jug."] = { "7e3648a6b06e", 11.13 },
		["It took me six years to learn that. It's the most useful thing I know. There is nowhere to mention it at a dinner party."] = { "f9056a022a4f", 7.73 },
		["It took me too. Off the boat, under the water, moving fast, with coral going past my face and my arm trying to leave my shoulder."] = { "9914c90eb39c", 9.67 },
		["It took me years to work out that he wasn't only talking about fires."] = { "f78c06709d86", 4.21 },
		["It took three days. There's no lesson in it, and it did nothing for the balance of anything. I just didn't want her to have the last of it alone."] = { "bed73d9fa5d7", 9.25 },
		["It took two days to find a carpenter. By the second evening, people had begun hanging their coats on me."] = { "bce6ae87e7bb", 6.56 },
		["It towed my boat clear across the lake, past anyone who might have helped, and I had to let go of the best rod I ever owned."] = { "d58926abd8f0", 7.97 },
		["It turned back into a bear halfway down the hill, still walking. I think it was too confused to come back up."] = { "363f8a7719d0", 7.44 },
		["It turns out a stair is not a ledge. The stairs have opinions about this. I met each of them personally, and at the bottom I met the soup."] = { "40d3cc400218", 9.67 },
		["It used my old teacher's voice. She'd been gone three years by then. And it said, very gently, \"Are you the one who has been asking?\""] = { "4e506ee39a5f", 10.42 },
		["It was a door key. Old iron. It was tied to my line in a neat little bow."] = { "7a553c7d60ad", 6.24 },
		["It was a dragon whelp. Black, about the size of a cat, and snoring little puffs of smoke. It was also very pleased with itself, and it was sitting on my dinner."] = { "0bf00b34a27f", 10.66 },
		["It was a hook. A really fine hook. I said that's not what I asked for, and he shrugged and went back to work."] = { "5d0a18285a1c", 8.05 },
		["It was a people learning they could choose again. So I choose candy. And a good fire."] = { "2042255e888a", 6.37 },
		["It was a pup who went down to bring up the body, one of the ones who'd laughed loudest. For no reason anyone can name, that pup swung the pick a few times. Two more feet."] = { "a882cbb4a297", 12.17 },
		["It was an outrage. A committee has been formed to consider the log. I'm told they hope to have their first findings soon."] = { "80a2aac0845a", 7.99 },
		["It was evening when I got to the gate. There was a light on, and someone else's washing on the line. Someone inside was laughing."] = { "070fb001c899", 8.46 },
		["It was gone by sunrise, and I got up and found a road. I'd like to go back someday and tell it how things turned out."] = { "6c4809d2b7b1", 7.58 },
		["It was gray. I've washed it since. I've held it up in the sun. I'm told that it's red, and everybody I ask says it's red. I'll just have to take their word."] = { "173097e0c727", 11.86 },
		["It was homesickness. There was a kitchen, a long way off, and I wanted to be able to step into it for supper."] = { "9c3e0fc17106", 7.03 },
		["It was left out of the minutes. But I have to say, that doorframe was perfect. I've been looking for another one ever since."] = { "3c1448e20291", 8.33 },
		["It was my first real snow in Winterspring, up in the Ice Thistle Hills. I was so pleased with it that I made a snowball and threw it at my traveling companion."] = { "11b24c5d58a8", 10.24 },
		["It was skinny, gray in the muzzle, and I couldn't tell you how it had lived there, or if it had. It just fell in by my left side and trotted along with me."] = { "480afca67cdf", 10.08 },
		["It was so cold in Dun Morogh that I took advice. Never take advice in Kharanos. They told me a Thunderbrew would warm me right up."] = { "6404234e1f82", 9.06 },
		["It was standing wrong. As if it had only ever been told about stags. And it was looking at me very patiently. Deer don't look at you patiently."] = { "101342cbeda8", 10.32 },
		["It was the Gurubashi Arena, in the middle of a brawl. Everybody stopped. Then the raptors came through the gate behind me, and the crowd went mad."] = { "24a82c2ea276", 9.46 },
		["It was the dead of winter. The stream was frozen solid, right across."] = { "c9f925af51f0", 5.3 },
		["It was the kind of calm where the stars sit on the water. An hour passed, then my line went heavy. Not a fish. Just weight, coming up slow."] = { "f265634874d9", 10.55 },
		["It was two days before I found the note in the pocket. A list, in someone else's careful hand. Thread. Salt. A blue ribbon."] = { "b3a6de55ae9f", 10.19 },
		["It was walking, and every step it took left a puddle of glowing rock. The only way out was an old ore cart, and I didn't stop to look at the rails."] = { "ca1ab9400750", 9.67 },
		["It was warm. And while I held it, something inside tapped back."] = { "765a58ad7ccf", 5.46 },
		["It was water by supper, of course. I laughed as hard as anyone."] = { "dfa1cf1e363f", 4.7 },
		["It was well kept. Fresh flowers, even. Someone had been coming for years."] = { "df1da1b6efa0", 5.59 },
		["It was wine. It was still cold. The fisherman took it from my hands and he dropped it back over the side, gently, and he said somebody would be wanting that."] = { "f4ca51831420", 9.95 },
		["It was, in fact, a fine shortcut. To a very narrow, very personal understanding of the word winder."] = { "398a0401ccaf", 7.21 },
		["It was. To every stray dog, cat, and boar between the city gates and the coast."] = { "e7b5b4c83a55", 6.19 },
		["It wasn't painted like the others. It was black, with silver lines running through it like veins."] = { "b8a862853e72", 6.06 },
		["It wasn't until I was grown that I saw her do it again, from the side, where the child couldn't see."] = { "c8ade693e907", 6.74 },
		["It wasn't. But when I took my hand away, the ring was on my palm instead, glowing faintly, about the size of a coin."] = { "3e2428b88597", 8.88 },
		["It weighs about what a small child weighs. I swung it from the hip. Twice. The second time I was praying out loud, and not for the creature."] = { "6a64158ab6ae", 10.19 },
		["It went on for twenty-two years. It stopped the evening she died. I reckon he'd only been coming up the lane to fetch her."] = { "d5e164cf354f", 7.99 },
		["It went out while I watched. Then it came on again, at the next window down, and the next one. Something in there was coming downstairs. Or going to the door."] = { "0a02db3f6136", 11.26 },
		["It went sideways. Through a tent, across the lake, and straight into a druid's beard."] = { "3f9a9daaf935", 6.37 },
		["It went to Magistrate Solomon in Lakeshire, then to Highlord Bolvar Fordragon himself. Bolvar wanted proof, so he asked his court's expert on dragons. Lady Katrana Prestor."] = { "1cc9f50a98dd", 12.41 },
		["It went well until I called a bush a pine. She stopped walking and asked me why."] = { "4640f2fb89de", 5.77 },
		["It worked too well. A hunter asked about the tracks, so I drew some in the dirt. Big ones. With far too many toes."] = { "cfb7d08b46ed", 9.04 },
		["It'll go up someday, he said, and take the lot of it, and me too, and it'll be green again before anyone's finished being sad. He seemed to find that restful."] = { "d0b278771ac8", 10.55 },
		["It's a fine lantern. But it goes out whenever I apologize, so I've had to become a very rude person after dark."] = { "1f3585e3813e", 8.1 },
		["It's a sound principle. If you're going to discuss explosions, do it somewhere that can take one."] = { "ed4e2cfb9144", 6.14 },
		["It's almost restful once you've got used to it. I said so to an old prospector, who told me I could learn to count them if I listened for long enough."] = { "ac9159d8bcd0", 8.88 },
		["It's always a little bit evening on Darkshore. Something about those clouds. You stop trusting your own sense of the time."] = { "6f20c91c3a33", 8.46 },
		["It's always autumn in Azshara. The leaves are red and gold, and they keep on falling. They never run out, and winter never comes. I've seen nothing so lovely."] = { "9c79a153c177", 10.84 },
		["It's been holding my coat for eleven years. I've met a few folk since who needed to hear about that hook, and I was one of them."] = { "bbe8d9ce96c9", 7.99 },
		["It's been nine years since I crossed. I like to think I'm still out there in that rope, waiting to be undone."] = { "587e713df274", 7.39 },
		["It's been six years since I was in Silithus. Six years. I've crossed two oceans and been rained on in every country that will have me."] = { "4cc4d45361e3", 8.99 },
		["It's been winning for thirty years. The keeper holds its money in a jar, and that jar has bought the place a new roof."] = { "67c1e7f12a53", 8.23 },
		["It's blowing toward that gate. Even my breath was going that way, when I looked. I went home after that, and I walked the whole way into the wind."] = { "b0653039db78", 9.95 },
		["It's dark and quiet down there, and the water glows faintly. They knelt at the edge and looked in, as you do, and their reflection looked back. Older, they said."] = { "a56193aadd6e", 11.39 },
		["It's for you, he called through the door, quite kindly. Stay in till the sun's up. Then I heard him going down the stairs."] = { "3a88539e9445", 8.83 },
		["It's not an empty dark. It's full. Owls. Moths. Quiet feet. Everything awake and going about its business."] = { "701a5d379842", 10.24 },
		["It's only marsh gas, the boatman told me. But I watched for a while, and they came in a rhythm. Long, short, short. Long, short, short. Like a chant."] = { "ce2d86b6db64", 11.86 },
		["It's packed every night. The place across the road promises \"The Finest Drink In All The Land\" and it's got nothing in it but flies."] = { "5a6fcb4e6d0d", 8.88 },
		["It's painted on a board above the door now, with my name under it. Business doubled. I have never felt so thoroughly punished."] = { "341abbb9e6a0", 8.99 },
		["It's still a very good shirt. I've had a lot of good days in it now."] = { "a36111cf527c", 4.86 },
		["It's still cold, I think, it said. I can't tell. Then neither of us said anything else, and I stayed a bit longer than I had planned."] = { "592b18181813", 8.99 },
		["It's the last good day, he said. It can go on for a very long time. You just can't ever get anything done in it. I left the next morning, though it wasn't easy."] = { "a1a3c2dff721", 11.81 },
		["It's the opposite, friend. The Light shows you everything. Including all the things you'd prefer not to see."] = { "c457afb1cef2", 7.21 },
		["It's the shelves. Row on row of jars, all dusted, every label in the same tidy handwriting. Somebody down there takes real pride in the work."] = { "9593fa8f0af1", 11.08 },
		["It's the whole of what I know about strength. Any fool can spill. What takes a lifetime is to carry all that weight through a room and leave everything standing."] = { "09d02554e6fe", 10.42 },
		["It's to someone I met on the road years ago. We shared a fire like this one, for one night."] = { "951eed18793e", 6.37 },
		["It's very quiet in a Tirisfal graveyard at night, once you've got a crowd of us standing around. We don't breathe, you see. So there's no sound at all."] = { "7ecb2f08f606", 9.9 },
		["It's well over my head now. A very twisted, ugly little oak. I go up every year and sit with it, and I tell her it's still alive."] = { "464a8bac909e", 10.06 },
		["John was the only one of Windsor's men who got away. He swore the Dark Iron dwarves had dragged the marshal off to a prison deep in Blackrock Depths."] = { "3ad3803020d1", 9.95 },
		["Just enough for the skins, if you scraped. Nothing to spare. I stood there a long time. Then I went home, and I carried the water."] = { "4d814dbeb472", 9.12 },
		["Just for fun, I set my thumb against it. Same size. Same whorls, near as I could tell, right down to a little scar I've had since I was small."] = { "90c466fea301", 10.97 },
		["Just sits there. Listening. Doesn't even ask for money. He said it's the most frightening thing a storyteller can meet."] = { "ffabc23a45bb", 8.2 },
		["Keep your answer close. You'll want it some day."] = { "93dacb1e3d24", 3.21 },
		["Keep your backs to the fire tonight. You'll want to, after this one."] = { "9adbd7895d23", 4.99 },
		["Kindness isn't the same as balance. It took me a long time to learn that, and I still don't like it."] = { "aba81ee8a69f", 7.26 },
		["Knife was back in the boat, so I pulled that line up to my mouth and started chewing. A tusk is good for something. Lungs burning. Light going far away above me."] = { "5c32a8b3aa56", 11.39 },
		["Krolg was deeply relieved to meet a kinsman still in his right mind. His tribe had driven him out. At night he could still see their fires."] = { "8da2fd1b0adc", 9.46 },
		["Lake Kel'Theril in Winterspring is frozen clear in places, like window glass. The wind sweeps the snow off and you can see right down. There's old stonework, they say, a long way below."] = { "3a25834479f4", 13.58 },
		["Last spring a child in some village I was passing through watched me do it, and asked me to show her. Took all afternoon. She had it by supper."] = { "ae3939127124", 9.12 },
		["Last spring the clerk asked me, very shyly, whether I thought the baker's girl was married. I said I'd have my mother ask."] = { "6549ae39c53b", 8.65 },
		["Last time we met, we finally agreed on one thing. The next stranger to share our fire would settle it for good."] = { "72968db06361", 7.78 },
		["Last winter, something tapped on the pipe. Short, short, long, short. That's a shift code. I'd know it anywhere, because it was my bench's."] = { "1b5b0ea0d002", 9.48 },
		["Later, he said. That's the word. Later."] = { "3ee10052542a", 3.63 },
		["Later, his grip on the dead slipped. Only for a moment. Thousands in Lordaeron woke with their own minds again, and nowhere to go."] = { "623b0aec17aa", 9.4 },
		["Let me tell you about the sacred calling. In one single morning, I have blessed an axe, a wheel of cheese, and a horse that had already lost."] = { "5f468aa56425", 9.46 },
		["Light it, step back, and look up, he said. So I lit it, stepped back, and looked up."] = { "b421ff7a083a", 6.06 },
		["Lighter than air and gone in a breath,"] = { "aea5933ffaca", 2.53 },
		["Locals will tell you it's only the current. Ask them why they all stay indoors when it starts."] = { "63b5ee601098", 6.37 },
		["Long ago, on the orcs' own world, the warlock Gul'dan offered the chieftains the blood of a demon named Mannoroth. Drink, he said, and you will be strong."] = { "1a2b56250d79", 11.76 },
		["Long ago, the Fordrings sat for a painter on the shore at Caer Darrow. Tirion, his wife Karandra, and little Taelan. His fondest memory, he said. He wanted to know if that painting still existed."] = { "fa9362c5c1d9", 13.24 },
		["Lost in the ruins of Shen'dralas, I paid a traveling artist three coppers for a drawing of the way out."] = { "dd15829dc522", 6.74 },
		["Love is in the Air, and a vendor sold me a perfume he promised was irresistible."] = { "186e7aed600a", 5.28 },
		["Lovely animal. It went lame by the first milestone, and by the second it had eaten my hat."] = { "0444c458f8cd", 7.08 },
		["Machines are all about tolerances, you know. A tiny thing, a hair out of true, and everything goes one way rather than the other."] = { "6ea309c0206f", 8.83 },
		["Machines don't run for years without oil. Something has been keeping up the maintenance."] = { "0fa9c9ad08a5", 5.9 },
		["Malfurion Stormrage had a plan, but it needed time, and three armies bought it."] = { "eb59a501f45a", 5.9 },
		["Market day. A brewer's wagon slips its brake at the top of the hill, with two horses and a full load, and the whole square is right below it."] = { "b478d60d57dd", 9.72 },
		["Marshal Reginald Windsor once led the Alliance in the Steppes, until he rode into Blackrock Mountain and never rode out. Everyone said he was dead. Everyone but Ragged John."] = { "2839a008d31f", 12.04 },
		["Mine has eleven refinements. It folds in three motions, the height adjusts, and it has never exploded. It's quite possibly the best thing I've ever made."] = { "9ba9c7edd862", 10.71 },
		["Mine reads dents like a diary. \"That's a mace. That's an axe, and you were backing up. That's a fall down some stairs.\""] = { "b1b42a83716c", 8.93 },
		["Mine was an old woman with a voice like a dry branch. She said it to me as if it were the plainest fact in the world. So I believed her, and I stepped."] = { "b41003f02972", 10.14 },
		["Mon, my people were building empires when your ancestors were still arguing about fire."] = { "9d9a5ff90cfa", 5.83 },
		["Morning mist on the fields, someone's bread baking in Goldshire, and you'd think nothing bad had ever happened in the world."] = { "570d4d70d958", 7.68 },
		["Most nights it's twelve. Some nights it's thirteen. Nobody I've met has heard the thirteenth, but everyone knows someone who stopped counting at twelve, just in case."] = { "54600c9e4820", 11.62 },
		["Mostly they say \"what.\" Hour after hour, all across the yard. What. What. What. It's less a language than a condition."] = { "5e5260f94c93", 10.89 },
		["Mostly they're up high, where the master could see them. Proper work, proper pride."] = { "742b6fdca827", 6.06 },
		["My aunt used to sing that while she did the washing. She never once told me it was about them."] = { "e991c7d3eda3", 6.24 },
		["My auntie raced crabs back on the islands, mon. Every market day, crabs from all over in every color, and folks would come from miles to bet."] = { "a4205d01beff", 10 },
		["My auntie sat him down and put a cup in his hand. She said, you people cry so quiet. How's the dead supposed to know you came?"] = { "2fc514a0e984", 8.46 },
		["My brother always whistled coming up the lane, so our mother would know to put the kettle on. Two notes, up and down."] = { "12b50cefdac8", 7.73 },
		["My brother decided, one summer, that he was born to play the war drum. He had the arms for it. That's the only part of it he had."] = { "9920939ee7fe", 9.77 },
		["My cloak was ruined. The sentinel's shield was black. The owl, I'm told, now visits that lantern every evening, to make sure it's behaving."] = { "49f49983c148", 10.08 },
		["My cousin, he thought that was funny. He knocked back. And it followed us home, tap, tap, tap, right under the hull, all the way in."] = { "470b07b1a6b7", 10.32 },
		["My elders remember greener places. They speak about them softly. I only remember the camps. This dust is the first home that was ever ours."] = { "094aef11236c", 10.08 },
		["My father cut a notch in the kitchen doorframe every year on my birthday. It was the one job he never forgot."] = { "d6530a166528", 7.39 },
		["My father taught me that one. It doesn't slip, and it comes undone with one tug. I've never seen anyone else tie it."] = { "68b4352674c8", 8.39 },
		["My father took that duty for thirty winters. I sat up with him once and said, there's nobody out there, Da. Not a soul travels in this."] = { "34c2ddadd380", 9.17 },
		["My first captain told me that courage is just fear that's run out of places to go."] = { "6f83f476f41f", 5.36 },
		["My first night out with an old shepherd, I built a blaze you could see from three valleys. I was very proud of it."] = { "8057bb1e110a", 7.68 },
		["My first sermon was three hours long. I'd worked on it for months. There was hardly anyone left at the end."] = { "62f9189698f4", 7.08 },
		["My first teacher tied my sword arm to my belt for a whole winter. I ate with the wrong hand, dressed with the wrong hand, and fought like a drunk."] = { "d2bf7567157c", 9.46 },
		["My first time at the faire, I spent every copper I had and won exactly one prize ticket."] = { "746fd29659fd", 6.37 },
		["My friend Tam knew one joke. He told it every night for nineteen years, in every tavern we ever sat in, and it was never funny. Not once."] = { "bea64880aa3f", 10.32 },
		["My friend isn't here, which I think is to my advantage. I'll tell her it was a fair hearing."] = { "cbea640d7cdf", 6.32 },
		["My friend's stopped looking into water, even a washbasin. I saw them last spring, and I'll tell you, they're starting to look like someone they described."] = { "da33cc09fcee", 9.64 },
		["My grandfather could lay a hand on a rock wall and tell you who'd cut it, and when, and if they'd been in a foul mood."] = { "6042b0658a2c", 7.81 },
		["My grandfather let me miss for a whole summer before he told me. The fish isn't where it looks like it is, mon. It's a little under and a little to the side."] = { "6e32877a8d6a", 9.59 },
		["My grandfather never said a word about it. He only planted the row again. You pay your neighbors what you owe them, or else they come and collect."] = { "2998e4172b80", 9.9 },
		["My grandmother carried this stone all her life. She said if you held it to your ear, it hummed."] = { "f3b15b8cf05e", 6.19 },
		["My grandmother taught me to hunt. She would thank the animal before she drew the bow, and again after."] = { "330a95f81e6b", 6.48 },
		["My grandmother, she got old and slow here in the dust. But every morning she walked down to the shore, filled one bowl with seawater, and carried it home."] = { "97cd0775383d", 10.24 },
		["My hands still have the rope's pattern in them. I show them to the young ones when they won't listen about knots."] = { "998fc7585bef", 6.48 },
		["My head's made of iron, my handle of oak."] = { "0ea735d6deec", 3.13 },
		["My imp once demanded a share of my earnings. I asked what it planned to buy. It said that was private."] = { "83df7f3b04fa", 7.31 },
		["My imp was on my pack, saying what it usually says about villages, when a little girl came running down the road with something wrapped in a cloth."] = { "42ea665c24da", 8.99 },
		["My most glorious charge lasted about forty paces. It had rained for a week, and both lines met in the same bottomless field."] = { "6ef9c34f4b75", 9.12 },
		["My mother held me down low in the hull, and she hummed in my ear. The same few notes, all night, close and steady. I thought she was singing me to sleep."] = { "72804e4124fb", 10.92 },
		["My mother hummed that over the washing. No words to it. I thought she'd made it up."] = { "e2a8822d9708", 5.46 },
		["My mother kept one rule. Anyone who came to our door after dark got fed first and questioned after."] = { "9cc0bc666ab1", 7.39 },
		["My mother owned a set of blue plates, and we were never allowed to use them. They were for company. They were for when things were better."] = { "1b7d638eabbb", 8.83 },
		["My mother taught me to walk through a village as if I had a bowl on my head, filled right to the brim. She made me do it with a real one, too."] = { "a0cce35cb863", 9.4 },
		["My mother tied mine. The wind undoes them by autumn, she told me. That's the point of it. You aren't meant to stay tied."] = { "7062c68052bf", 8.46 },
		["My neighbor keeps one Winter Veil gift on the mantel, every year, unopened. Red paper, gone pink now. It's from her brother."] = { "c99e966cf84e", 9.64 },
		["My old hound can't run anymore. His hips went two winters ago, and his nose is about half what it was."] = { "c3ad4f1d1821", 7.5 },
		["My old master lost his eyes to the work in his last years. So every evening I read his books to him, for hours, while he sat with his tea."] = { "5c8931c8f53e", 9.87 },
		["My old sergeant had one lesson. Day one, she knocked me down. Then she asked me what I'd learned."] = { "3144747cc781", 7.63 },
		["My people can vanish into the shadows if we keep perfectly still. Children learn it as a game. Nobody tells you how hard it is with a satyr standing on your hand."] = { "903665c56bbf", 11.02 },
		["My people walk softly. A child of Ashenvale can cross dry leaves without a whisper. So you learn something early on about footsteps."] = { "1356fb353931", 9.35 },
		["My sermons are shorter now. And I bring soup. Attendance is excellent."] = { "69de8a6c7f50", 5.49 },
		["My sister grabbed the goat bell off its post, jumped on the only horse we had, and rode down the valley road ahead of the water."] = { "2b87e6ec43ca", 8.8 },
		["My teacher could look at what an animal left behind and tell you its age, its health, and what kind of week it was having."] = { "9c845fb3d5d2", 6.71 },
		["My teacher kept a shelf with every invention that had ever failed on her, four hundred at least, and each one neatly labeled with what it had taught her."] = { "b3f26bd3469d", 9.46 },
		["My teacher looked at it for some time, and asked who it was meant to honor. I told her it was the great spirit of the earth."] = { "2a9f3879e1ae", 7.68 },
		["My teacher looked at the leaves and picked up her pack. I said we'd never catch it. She said we weren't going home."] = { "bba9337c3a40", 7.68 },
		["My teacher said I could read it when I stopped wanting to. A fine riddle, I thought. Later I lost someone, and stopped wanting anything, and I read it."] = { "951b57e4c272", 9.67 },
		["My teacher took me to a dead valley once. No birds, no wind, and no water. I'd never felt so alone."] = { "75e0f96131aa", 8.33 },
		["My teacher walked me to a field and told me to sit down until the birds forgot about me. Then she went home."] = { "4710c9331bbf", 7.37 },
		["My teacher wasn't surprised. \"Everyone else turns up only when they want something,\" she said. \"You'd know. You have relatives.\""] = { "e7d679d5c164", 8.75 },
		["My tutor kept a jar with one small flame in it, which he had lit as a boy. It had burned for sixty years."] = { "c919c8674cc1", 7.73 },
		["My uncle Tolly caught a fish once. When I was small, it was as long as his arm."] = { "adf9526cb230", 5.69 },
		["My village had two wells. One sweet, one so bitter it made your teeth ache. Guess which one everybody used."] = { "be083bc62f45", 8.46 },
		["My voidwalker doesn't say much. What it does very well is stand in a place, so that nothing else can."] = { "2425244237d1", 7.31 },
		["My water ran out on the salt flats below Thousand Needles, and I saw a lake. Blue as anything, with reeds. Only a few hours' walk."] = { "2522cf046023", 10.06 },
		["Near Ban'ethil Barrow Den the roots of Teldrassil come up thick as houses. Someone told me that if you put your ear against them, you can hear the tree breathe."] = { "608984864753", 10.08 },
		["Near Dolanaar in Teldrassil, a young owl flew into a lantern at dusk and knocked it into the dry leaves. In a moment there was fire all along the path."] = { "ed17127adf6c", 11.31 },
		["Near dawn I blinked. Just once. And there it was. Tents, flags, music already playing."] = { "302d44efb884", 8.33 },
		["Near the Eastvale camp in Elwynn, I watched an old woodcutter stack logs. She put the crooked ones on the bottom and the straight ones on top."] = { "37e2aa5554b3", 9.53 },
		["Near the end, her eyes had failed. She took my hand and asked me to be honest, because I'd always been honest. What did she look like now?"] = { "9023394a736c", 9.25 },
		["Near the end, one of them muttered that we'd better leave room for a gate. The other said fine, but it needs a latch on both sides."] = { "31a27eecc05d", 8.57 },
		["Near where Dalaran's violet barrier used to stand, there's a fence post with a faint purple ring around it, like a stain. I put my hand on it to see if it was warm."] = { "7937af5a5a64", 11.08 },
		["Neither of us trusted the other with it, so wherever that horse went, we both went. We took turns riding, and argued about who'd ridden more."] = { "57b499f46b90", 9.82 },
		["Never ask for directions in Elwynn. I asked a farmer once, and he put down his rake, which should have warned me."] = { "dbbfee116adf", 7.92 },
		["Never buy a frog from a boy at the Darkmoon Faire. I say this as someone who did."] = { "83d920a7f076", 5.83 },
		["Never run across Iceflow Lake with a bear behind you. That's not wisdom. It's just the only thing I learned that day."] = { "98a395d7dd01", 7.99 },
		["Never take a shortcut from someone who's smiling. A nice fellow at a crossroads told me about a path through the hills that would save me a day."] = { "c8a063610b27", 8.99 },
		["Never trust a slate roof in the rain. I knew that when I went up it. I also knew there were six of the watch on the stairs behind me."] = { "72f2a04d859e", 8.57 },
		["Never trust a track you can't see the end of. I learned that near the Grimesilt Dig Site, in the Searing Gorge, when something made of fire came out of the tunnel."] = { "ccac54770923", 10.79 },
		["Next evening, there it was. There was my rag."] = { "668858ef9e01", 3.92 },
		["Next month I went back to complain, and the boy sold me a second frog to keep the first one company."] = { "e404a7daf5fc", 6.43 },
		["Next morning he came back with a bigger axe. I started leaving him a fish on the rocks, mon. Respect where it's due."] = { "8864279a4402", 7.81 },
		["Next morning, the boat was full. Fish everywhere. He danced for an hour, he was so pleased."] = { "940bedbb0939", 6.53 },
		["Next town, maybe."] = { "032814285f88", 1.52 },
		["Night after a hard fight, I couldn't sleep, and I walked past the long row where we'd laid out our dead."] = { "bd96717cbd08", 6.71 },
		["Nine armed thieves rode into a hill village once, and the only one who didn't run was the beekeeper, a tiny woman of seventy."] = { "1e269b12751b", 8.23 },
		["Nine days. I kept walking. I said all the words and polished the armor, and people thanked me for a comfort I could not feel."] = { "20df35beff76", 8.99 },
		["Nine years later, on a morning with no tracks around it, there was a waterskin sitting at the edge of our camp. It was full."] = { "f5a5c210c8a3", 8.28 },
		["Nine years now. Still got the pack, mind you. I'm not as brave as she was."] = { "f15c29d11ca1", 6.14 },
		["No barnacles. No tarnish. I've seen what the sea does to silver. And when I tipped it, there was something in the bottom of it that wasn't seawater."] = { "e15b1eceb0f7", 10.32 },
		["No guards to speak of. Just me, two drivers, and a merchant who had already fainted."] = { "211745e776d3", 6.19 },
		["No one has ever managed to answer. They just look a little sad, and order another drink."] = { "d9339c34b807", 6.06 },
		["No one warned me that they're warm. Not all the time. Some nights I wake up and the pouch has gone warm against my hip, like a sleeping cat."] = { "89930cdb1fec", 10 },
		["No storm came. On the third morning, I finally looked under its foot and pulled out a burr, as long as my thumb. The kodo got up and walked on."] = { "c4d4f60868fb", 10.61 },
		["Noblegarden. Painted eggs hidden all over town, and every child in the valley out hunting them."] = { "81bce8ab3a34", 6.95 },
		["Nobody at the bar so much as looked up. The keeper poured a full mug, carried it to the cellar door, set it on the top step, and shut the door."] = { "c35b3a4014d2", 10.74 },
		["Nobody came. But in the morning there was a fresh line of ash across the step, right where I'd been sitting, and the rest was swept again."] = { "9ffa7387384b", 9.46 },
		["Nobody complained. You don't, in a small village. Then the elder sister died, and that week the soup was perfect."] = { "59bd3270ef78", 8.33 },
		["Nobody could reach him. The boat was moving too fast, and the water was too rough for swimming."] = { "9fbaa5e34f91", 6.56 },
		["Nobody cut it. Forty years of frightened recruits did that, one bad swing at a time."] = { "61523b735b6f", 6.71 },
		["Nobody ever came. Around noon, the enemy simply packed up and left. To this day I don't know why."] = { "99411be585fd", 7.73 },
		["Nobody has said a word to either of them. There's a betting pool. It's up to forty gold, and the forge has never run so warm."] = { "e03f1f6266d8", 8.7 },
		["Nobody minded. She told me that's how every teller starts. With a goat and no ending."] = { "8828b6e89a39", 6.84 },
		["Nobody names their farm that. Nobody ever stood in a good field in spring and said, let's call this the Withering."] = { "cc3263e756c9", 8.15 },
		["Nobody sings about feet. Forty verses on the glory of the charge, and not one about the march that got you there."] = { "6dbc1d02f55e", 8.15 },
		["Nobody tells the children, but the magic is a kind of thirst. A little is wonderful. And the people who have gone furthest into it aren't all right."] = { "13671b5f1cfd", 10.14 },
		["Nobody warned me about moonkin. I came around a bend above Auberdine and there it was, a huge feathered bear of a thing, looking right at me."] = { "e9a35fcef973", 9.87 },
		["Nobody warns you how much of this calling is blessing farm equipment."] = { "adfc5468b2e9", 4.44 },
		["North of Auberdine there's an old Highborne tower, Althalaxx. The way I heard it, Sentinel Elissa Starbreeze had a scout watching it. Balthule Shadowstrike. One day he simply stopped reporting in."] = { "e68937f0bd1e", 14.13 },
		["Not every story ends well. That one didn't."] = { "b862c2a46a7a", 3.37 },
		["Not long after, he went back into the Dream. This time, he hasn't come back, and the druids won't say why."] = { "8bc53ba0f2a9", 7.81 },
		["Not long before, all three had been killing each other in Ashenvale. On that mountain, each held its ground until there was nothing left to hold."] = { "48a758323564", 9.48 },
		["Not one soul drowned. Afterward they asked how she found the courage not to stop."] = { "fb8381ecb059", 6.11 },
		["Not worth a copper and never once sold,"] = { "ab08c0734d50", 3.27 },
		["Nothing else happens, they say. It's just there. One fellow told me it was the neatest handwriting he'd ever seen, and that was the worst part."] = { "5b76bd8f9e4b", 9.4 },
		["Nothing happened today. Nobody chased me. Nothing burned. I sat on a wall for a while and I ate a pear."] = { "0ed1e4a7c373", 8.28 },
		["Nothing in Desolace has any color. You know that before you get there. Gray ground, gray sky, and everything else somewhere in between."] = { "ceb3d4634d8d", 10 },
		["Nothing worked until I stubbed my toe and said something I won't repeat by a fire. It lit right up."] = { "7050073a630f", 7.16 },
		["Nothing, for the longest time. Only leaves. I never saw a shape. I never heard a breath."] = { "abfbaa7eaa2d", 8.05 },
		["Nothing. Not a cough. Somebody in the corner sighed, though I think that was about something else."] = { "b5657f088b28", 7.5 },
		["Noticed something strange this morning. I was sitting here with my tea, and I looked down, and I was holding the cup the way my mother did."] = { "3e28c3bc6156", 8.83 },
		["Now I make a little noise at that hour. Poke the fire. Clear my throat. It seems polite to let it know I'm not listening."] = { "a8264cdc3b60", 8.57 },
		["Now he had all three. All he needed was a way into Hearthglen."] = { "117c0d016ff0", 4.86 },
		["Now when I'm furious at someone, I stop and ask myself whether the rider just hasn't reached me yet."] = { "bf58d9d40283", 6.43 },
		["Now, in the real story, my old partner took the left and I took the right. We worked it out without saying a word."] = { "82aa923bd164", 8.1 },
		["Now, the thing about having no need of breath is that a lake is merely a long walk. I cut the net and set off along the bottom, past some very curious fish."] = { "ce50f9fe016b", 11.39 },
		["Old spellbooks are full of notes from everyone who had them before you. Arguments, corrections, a lot of rude drawings. I always read them."] = { "be67c3824850", 10.08 },
		["On Hallow's End I asked an innkeeper for a treat. She smiled and said, how about a trick instead?"] = { "33c13c95fd69", 7.16 },
		["On Mount Hyjal I spent a day helping a stranger clear a fallen trunk off a path. I grumbled about the weight the whole time."] = { "0a9afbbe1224", 8.15 },
		["On Mount Hyjal the ash lies deep in places, and it can slide like water. I was carrying two buckets up a slope when the ground gave way under my friend."] = { "2f7ee8705873", 9.95 },
		["On Mount Hyjal, where everything burned, I found a sapling about knee high and sat down under it to rest in the shade."] = { "7bfe51e36872", 8.15 },
		["On Spirit Rise in Thunder Bluff, there's a pole hung with feathers, more than you could count. The wind keeps them moving all day."] = { "fe0bc9bf12dd", 9.25 },
		["On Taelan's seventh birthday, Tirion gave him a tiny war hammer. A perfect copy of his own. The way I heard it, the boy carried it everywhere."] = { "0d810ff8cf75", 10.14 },
		["On Zephras Isle a shepherd's boy slid off the cliff path onto a ledge far below, and it crumbled a little more every time he moved. No path down. No time to fetch rope."] = { "bb9f0417451a", 12.64 },
		["On Zephras Isle, everyone tests the wind before they head out. I watched an old fisher lick a finger and hold it up, and I copied her exactly."] = { "70eb4c7379b9", 9.72 },
		["On Zephras Isle, you learn to read the wind before you learn to read anything else."] = { "f68b17303cfc", 4.99 },
		["On Zephras, the spirits were always in the wind, and the Skyborne never once thought about it."] = { "562723f036ae", 6.06 },
		["On a dare in a dockside tavern, I said I could walk into the Wyrmbog, in the south of Dustwallow Marsh, and bring back a dragon scale. People remember what you say."] = { "13dccaaba5a1", 11.68 },
		["On a narrow ledge in Deadwind Pass I met someone coming the other way, carrying a sleeping child wrapped up against the cold."] = { "ff6df0d81001", 8.05 },
		["On his deathbed, it went out. So now you know, he said. Every spell costs something. Do learn what, before you cast it."] = { "7e1c2d9feb62", 9.46 },
		["On my way out I saw the keeper sawing a little off one leg of a brand new table. He winked at me and didn't stop."] = { "69676b6709b4", 7.5 },
		["On still nights you can hear it ring. Slow and soft, from somewhere far below the water."] = { "aa38ca3d79f2", 6.84 },
		["On the Craftsmen's Terrace in Darnassus I watched a woodworker tie a green sapling into a curve, with a soft cord and a lot of care."] = { "c4d455d00c02", 9.12 },
		["On the count of three, my opponent lunged. On the count of two, I had already tripped."] = { "0793ffb6533c", 6.11 },
		["On the eighth morning, I woke up on the front step. Blanket tucked in, pack beside me, door bolted from inside. I've never been thrown out so politely."] = { "dea68b284ea0", 10.29 },
		["On the fifth day she came by, reached past me, and pulled the handle. It swung right open. It had never been locked."] = { "f1bd15e850f3", 8.05 },
		["On the fourth night, when I came in over the sill with my bag, the table had been laid for two. And the second chair was pulled out."] = { "8a95ce6b3dc7", 8.15 },
		["On the islands, there's one thing every child knows, mon. When you're out on still water at night and something knocks under the boat, you do not knock back."] = { "160c75e6fcbf", 9.87 },
		["On the last day we sat on a high cliff and watched the sky until sunset. Nothing came."] = { "e1ad82e56015", 6.48 },
		["On the last night I asked her why. She said a party walks at the pace of whoever carries the heaviest thing, and she'd wanted the hurry taken out of me."] = { "ef7dc34e8744", 9.3 },
		["On the last page, in her terrible handwriting: \"You should have counted.\""] = { "4e78ed9eac22", 5.07 },
		["On the ninth morning, a wren landed on my bow. It sat there and sang. I cried a bit, if you want to know."] = { "1cc87fc1ace2", 8.15 },
		["On the sixth morning, I was filling my skin upstream of Bloodvenom Falls, and the sun came through, and it hit that green water, and I stopped to admire it."] = { "6d71af4f0f9d", 10.24 },
		["On the tenth morning it came back, warm as ever, without a word of explanation. No one warns you that you can be angry about that."] = { "d5340a2ac785", 8.8 },
		["On the third day I stepped off the trail to rest. The prints kept going, right up to the edge of a drop hidden by the snow."] = { "24a31117b9e6", 7.81 },
		["On the way down, I met a couple going up with a picnic basket. They asked if it was worth the climb. I heard myself say it was lovely."] = { "d53b73ce359d", 8.75 },
		["Once she met a traveler whose shadow leaned in, toward the fire, like it was hungry. Polite sort. Sat a while, then wished her well."] = { "cb37b0aaeaa3", 9.87 },
		["One Children's Week, I took an orphan out of the city. I asked what she wanted to see most."] = { "1e6aea764120", 6.19 },
		["One I remember kept a sick pigeon in a box. Every morning, before his own breakfast, he fed it by hand and told it about his day."] = { "535b08cba77b", 9.35 },
		["One Winter Veil morning, I found a gift under the great tree with my name on it."] = { "08df7b44fe8f", 5.59 },
		["One Winter Veil, one of Greatfather Winter's reindeer got loose in Dun Morogh, and I was fool enough to grab the rope when it ran past me."] = { "e2eee4d2e21b", 9.35 },
		["One blow, and the rock split clean in two. I thanked the earth, though I was a little annoyed about doing the lifting."] = { "34bd532bb7e5", 7.97 },
		["One boot because they caught me in my bedroll. The first one got a faceful of hot coals. The second got the boot."] = { "2b250e9f610c", 7.99 },
		["One couple came out at the very same moment and argued about it until dawn. Then they noticed a bear had taken both piles. They walked home with their dignity, which wasn't much."] = { "eb5c35a25d15", 11.86 },
		["One day we'll go back and take it home. And I'll turn off that kettle. And then, I suspect, I'll have a good cry."] = { "eab26e031803", 7.44 },
		["One drop landed in it. It was warm, like it had been held in somebody's hand."] = { "20f26d1a50b9", 6.06 },
		["One evening a patrol went out toward the coast. Seven of them. That night he counted to six, and waited, and kept waiting until the sun came up."] = { "aa214d58506e", 9.72 },
		["One evening my grandfather finished half his meal. He set his bowl down in front of me, and he stood, and he walked out into the plain."] = { "b175e6ea7903", 8.83 },
		["One fellow says it's never been wrong. Better than any almanac. He brings it a fish every week, and it has still never said thank you."] = { "d59c2f554d21", 8.99 },
		["One full season with that log, until I understood it. I went to her after a week and said, it's a log, and it's dead. She sent me back."] = { "ec49f833a1ab", 10.92 },
		["One half-inch washer. I was on the upper level with this in my hand when the doors came down."] = { "92fcfdb03505", 6.06 },
		["One landlord caught me at it. An old fellow, who came puffing up a ladder at midnight to tell me that it wasn't allowed, and that I'd crack his shingles."] = { "4f2c5837ff3c", 9.48 },
		["One line, every year, going back further than the company. Greatfather Winter: one glass of milk, one cookie. Paid in full."] = { "8b0d7636c23e", 10.66 },
		["One morning when I was there, the drums hadn't started yet, and I saw a big scarred fellow kneeling at a doorway with a file."] = { "1645394c46e3", 7.55 },
		["One morning, in all that quiet, a crow came down and landed on a spear in the front rank. The fellow holding it didn't dare move."] = { "aac67513a20c", 9.17 },
		["One night I waited up. Nobody came, but the sign turned anyway, very slowly, with a little groan of wood, right in front of me."] = { "807166f3a1e7", 9.17 },
		["One night last winter, sitting up with my books, I heard someone call from the cellar. My own voice. Calm, reasonable. \"Bring the book down, would you?\""] = { "0e87c4b5b265", 10.32 },
		["One night she met it in the hall and asked it what it wanted. It seemed quite startled. Then it pointed down at a loose floorboard."] = { "9044e4f6a7a8", 8.46 },
		["One night, late, I counted heads around the fire out of habit, and got seven. I counted again. Seven."] = { "9b096b29032f", 8.46 },
		["One of them leaned his whole weight on my fingers. I counted my breaths. I counted his. He had more patience than I'd have liked."] = { "9cc21ba84efe", 9.59 },
		["One of them told us years later. They figured a camp that would put up with that noise had nothing left to fear."] = { "450e5172ac0b", 6.66 },
		["One old farmer waved me off before I'd even knelt. He knew what he had. He asked if I could write. He said he'd rather have that."] = { "6eeafeee3e3e", 8.65 },
		["One old fellow looked up from his ale and said, Tinker Town? I said yes. He nodded and went back to his drink."] = { "850f9647a25e", 8.41 },
		["One pair on, one drying against the heart. She's retired now, with all ten toes. Not many heroes can say that."] = { "a39d5bae08fd", 9.48 },
		["One ticket buys nothing. I stood by the prize table anyway, just looking."] = { "84682b8c93d7", 5.69 },
		["One was quite small. Someone had come along, I don't know when, and set a stone at its feet to keep the ash off. So I set one next to it."] = { "c8458055c3b8", 10.42 },
		["One winter he died, and the lantern went dark. Three nights later, I'm told, someone came knocking at his door."] = { "e69710f7510a", 7.63 },
		["One year I asked around, to thank whoever it was. Nobody knew. Nobody had ever known."] = { "dd0f14afca7f", 7.03 },
		["One year I found a paper flower left behind in the grass. Bent, a bit muddy."] = { "96a98efe440e", 5.69 },
		["One, two, three, into the dark at whatever moved. One got my sleeve, and I gave it the fourth at about the length of my arm."] = { "9df1b6b9f037", 10.37 },
		["Only one with dragon blood could remake it. The trail led to a cold peak in Winterspring, and Haleh of the blue flight. She knew the foul thing the moment she felt it."] = { "7978622babcb", 12.33 },
		["Or was. Nobody knows which word to use anymore. The king sailed for Theramore to talk peace, and he never arrived."] = { "fa8dc4d943d0", 9.12 },
		["Our banner snagged on a burning beam during a retreat. The bearer went back for it, of course, and he could barely walk."] = { "c76e5da1599a", 7.81 },
		["Our captain laughed. Said the crows had it wrong this time."] = { "d70dc38bcc79", 4.1 },
		["Our company had a water boy. Skinny, twelve or so, scared of everything. He learned how each of us took our drink without ever being told."] = { "d9e0f9dcaae0", 9.64 },
		["Our eldest walked around it three times, and then looked gravely at the sky. \"It senses a storm,\" she said. So we made camp. We waited two days."] = { "d155e617b0bd", 11.39 },
		["Our final examination is famous. They put you in a room with an examiner and one candle, at noon, and ask you to show what you've learned."] = { "74389709b7e6", 9.4 },
		["Our glide lasts about ten breaths, and it only goes down. Down is very useful when the thing you need is below you."] = { "0011a4be632c", 8.2 },
		["Our gravedigger drank at the same bar for thirty years, and never paid a coin. The keeper would wave the slate at him, and he'd only smile."] = { "4e6a39a4caea", 9.3 },
		["Our hosts have been very kind since we lost Gnomeregan. They gave us room. They gave us workbenches. Every one of them is a full head too tall."] = { "ac0c0b6a6acc", 10.24 },
		["Our neighbor's scarecrow faced the east field. It had always faced the east field. One morning it was looking a little to the left."] = { "01bab0788fb2", 8.33 },
		["Our orders were to leave nothing the enemy could eat. There was an orchard on that hillside that four generations had planted."] = { "59714664f3ce", 7.81 },
		["Our village had a storm bell. When the white came down off the peaks, somebody would ring it all night, so anyone caught out could walk toward the sound."] = { "71ca10e986b4", 9.9 },
		["Out by Uther's Tomb lives an old woman named Myranda the Hag. She knows illusions. Show her the right things, and she'll make you look like one of the Scarlet Crusade, for a little while."] = { "e6675ffa4637", 12.51 },
		["Out in the oldest part of Ashenvale there is a watch post in the crown of a great tree, and there is a sentry in it, still on duty."] = { "7ce62287583a", 8.33 },
		["Out near Nethander Stead there's one old apple tree. Nobody farms that land any more. The fences are gone, and patrols from both sides march through."] = { "576f6e5ab390", 10.79 },
		["Out of thin air a mage pours me out,"] = { "81ee1a7ab98b", 2.66 },
		["Out past the reef, one bad morning, I had a good fish on the line and the line wrapped twice around my wrist. Never do that, mon. Then something took the fish."] = { "536281cb4279", 10.97 },
		["Out there, they reached a land where the wind spirits lived. The elders say the spirits offered them a home, if they would keep faith with the wind."] = { "e55c1a95dfdf", 9.06 },
		["Outside Everlook, in Winterspring, a sled team bolted when a bear came out of the trees. The sled tipped, and the driver was dragged behind, tangled in the reins."] = { "02c54725cbfa", 12.33 },
		["Outsiders think the snow makes us grim. Nonsense. The snow makes us thirsty."] = { "5454e1ff62d0", 5.96 },
		["Over one ridge, along the gutter, and a jump I'd measured in dry weather. I made it. The slate I landed on did not. Neither did the one under it."] = { "36f1a535bde0", 10.84 },
		["Over the finest forge I ever worked at hung the ugliest knife in the world. Bent, pitted, and cracked halfway through the tang."] = { "1cf2b214c66d", 8.39 },
		["Owls mostly want me to stop moving. I thought it was a lesson in stillness until one explained that I was frightening its supper."] = { "7df34420cfd6", 7.81 },
		["Partway down, the sound of his footsteps changed. There were more of them, and they had claws in them. I sat on the bed with my boots on till dawn."] = { "bfaaccf417d8", 9.9 },
		["People always ask why I left home. They expect a grand reason. Revenge, or a prophecy."] = { "8f2de20ce039", 7.16 },
		["People ask about the fighting. What I remember best is the breath right before it, when two lines have stopped and no one's yet decided to die."] = { "efdb949676e5", 9.48 },
		["People ask me how I tamed this beast. I didn't. We came to an arrangement."] = { "858c6770ea54", 6.32 },
		["People ask which shape is the real me. The bear, the cat, or this one, sitting here talking to you."] = { "1d505145fc64", 7.16 },
		["People assume it was power I wanted. Some of us did. I've met them. They don't tend to last."] = { "681120392481", 6.71 },
		["People go strange on the road through the Barrens. It's the distance. There's so much flat that you start shouting just to prove someone's out there."] = { "94adf6b35902", 8.99 },
		["People imagine the Light as a river that never runs out. It's more like a bucket. Some nights you're down to the last of it, with two cots in front of you."] = { "228942e669b6", 10.19 },
		["People leave him little gifts. Bread, a flower, a nice rock. He's been promoted twice."] = { "d6d68c29b00b", 6.66 },
		["People lit candles and hung charms and wouldn't sleep up there. My aunt inherited the place, and she got tired of all that."] = { "6431b30484de", 8.15 },
		["People tell a priest everything. In one small village, I heard three men confess, on three different days, to stealing the same goat."] = { "137f360eb4b0", 9.25 },
		["People would beg him not to. He'd be laughing before he got to the end. It was the worst thing about him, and I'd have paid money to make him stop."] = { "c22710136818", 9.06 },
		["Picture a boring engine the size of a tavern, in a tunnel under the snow, and a governor valve that has just gone flying past my head."] = { "cbab6557dd99", 8.88 },
		["Pleasant company, though he never looked around. Knew every plank and tussock. Five hours, and I never once got my feet wet."] = { "9e65e6541b01", 8.8 },
		["Pull up a log. This one's worth hearing."] = { "cc05a2030d29", 3.27 },
		["Pumpkins everywhere. The children cheered. The farmer came running, looked at his pumpkins, looked at the children, and decided to cheer as well."] = { "92d486af3e10", 9.22 },
		["Raene guessed. Maybe Dartol meant to walk among the furbolgs unseen. Maybe the rod could make you look like one of them. There was only one way to find out."] = { "17f25204c0d3", 11.08 },
		["Ran fell at his camp under the southern hills, guards and all. His skull went to Raene in Astranaar, and she set it beside Dartol's Rod in a place of honor. Teronis, she said, would be proud."] = { "57395f4c8ddd", 13.71 },
		["Raptors don't chase you in a straight line. Two ran me down the coast path in Stranglethorn while a third cut through the ferns ahead of me."] = { "9db4442003d8", 9.12 },
		["Red as a rose and gone in a swallow,"] = { "3fa64ef294d3", 2.95 },
		["Rescue fee. Salvage fee, since they'd technically recovered me. And a storage charge for the time I spent thanking them on the dock."] = { "857a95438597", 9.3 },
		["Riding past Karazhan, I coughed into my sleeve. Up on the tower, something coughed back. Same pitch, same little catch at the end."] = { "0b9b77442b72", 9.87 },
		["Rub me along any edge, and it bites twice as deep."] = { "3e869116d574", 3.87 },
		["Sadly, he'd gotten my name wrong, my hometown wrong, and which side I'd been fighting on."] = { "2c5c5a034854", 6.11 },
		["Same boots. Same stride. And the same little patch on the left heel, where I'd mended it myself with a scrap of elk hide."] = { "5d39cf146d2c", 8.93 },
		["Saved the whole garrison. The wagon belonged to my uncle, who'd come to sell hay. He sent us the bill for eleven years."] = { "ccd079650e09", 8.39 },
		["Settle in, friends. Here's one I picked up on the road."] = { "ba2d56fedda6", 3.63 },
		["Seven of us walked off that bridge. They wrote it down as a minor skirmish."] = { "abec22223721", 5.12 },
		["Seven pairs of eyes. I had five arrows, one companion, and a fire that was mostly a memory. My sums have never been so clear."] = { "228e8cc860d2", 10.48 },
		["She always gave me the first drink, and the second. If I held the skin out to her, she'd wave it off. \"Already drank,\" she'd say. \"At the well.\""] = { "0a928b1bbcf0", 10.42 },
		["She asked me to stay for supper. We could have had three hundred years of those."] = { "dfc4d21767ae", 4.94 },
		["She asked me, very politely, what season it was. I said early autumn. She asked what year."] = { "0568d322ddae", 7.68 },
		["She asked why the great spirit of the earth had a bill."] = { "d06a6cc6fecb", 3.21 },
		["She came and looked, and she nodded. \"Good,\" she said. \"Now learn to go home and have people know you again. That part takes longer.\""] = { "df7f32571b6f", 9.95 },
		["She came back a year later and started apologizing for it again. Then she saw the worn patch where the bowl had sat every night."] = { "c5d3968d8965", 8.46 },
		["She came out gray from head to toe, still holding the bucket. Then she looked inside it and said it was a shame about the water."] = { "595e31f766fd", 8.39 },
		["She charged me for the measuring cup. Fair enough. I'd used it the most."] = { "bf9e8ceff413", 5.59 },
		["She could have pulled back behind the city walls and waited. She didn't. She met the dead in the forest and made them pay for every step."] = { "d50ca8fa9587", 9.22 },
		["She didn't so much as blink. \"One copper more a week,\" she said, \"and it wipes its feet.\""] = { "fe7668dca98c", 6.71 },
		["She doused me, the torch, and my pride all in one go. Then she offered me a cup of tea."] = { "489dc73f161f", 6.24 },
		["She dragged the branch aside and said most grown folk never pay that one."] = { "e5c08ebcf259", 4.62 },
		["She dropped me on a lower ledge and kept the pack. That ledge took me two days to get down from, and I've never been so happy to see dirt."] = { "c6520a82ed65", 9.17 },
		["She felt so sorry for me she gave me a chocolate. I'm not too proud to say I took it."] = { "e27d59712afa", 5.36 },
		["She flapped. I kicked. For one long moment neither of us was going up or down, and we looked at each other with the same exact expression."] = { "044222afcc0e", 9.4 },
		["She froze, the way you do. I was on the far side with a coil of vine and no time to be clever about it."] = { "d06513cf9284", 7.63 },
		["She gathered them and gave them a name: the Forsaken. Some call them monsters. Some call them family."] = { "886f8339d76e", 7.92 },
		["She gave me directions back to Nighthaven after that, every one of them by bushes. Left at the old bush, right at the older one. I deserved it."] = { "c1e6bbbfb051", 10.19 },
		["She had a whole tray of pieces from one border, laid out like a puzzle. Mine dropped right into a gap."] = { "7ff9d49b92c3", 7.39 },
		["She handed me the knife. I'm a good deal taller now. It's the highest mark on that frame, and I hope one of those children beats it."] = { "ec0e0f9ba16d", 8.41 },
		["She held each gate until it broke, and then she held the next one. She sent runners to warn Silvermoon. Not one of them got through."] = { "a1b29712cd2a", 8.99 },
		["She held it a long while without a word. Then she said it had been black with thirty years of her husband's cooking, and he swore it was the secret to all of it."] = { "295cc2d74d61", 9.9 },
		["She held out a bit of thread and looked off at the sky, so I could do it privately. She never asked who it was for."] = { "02243c154828", 7.68 },
		["She knew every name, too. She'd delivered most of us. She still sends me a pot of salve every year, with the bill attached."] = { "919b24f04cfa", 8.8 },
		["She landed right beside me without a sound, licked my face from chin to brow, and strolled off. She'd only wanted to play. I sat there until dawn, shaking."] = { "6926f6dbbeb4", 11.55 },
		["She laughed and said, of course not. You've never been far enough from home."] = { "b83870782dd6", 4.94 },
		["She leads her people, and she doesn't speak of it."] = { "9b66ea22e4b4", 2.98 },
		["She leaves a loaf on his step every morning. By noon, it's gone."] = { "4f3345435a73", 4.57 },
		["She lifted it dripping from the water, looked me up and down as if for size, and said, \"Not yet.\" Then she went back to scrubbing."] = { "62aac0dbdc71", 8.46 },
		["She looked at me and said, calm? I've been sick behind that wagon twice."] = { "c2b3487bd7ff", 5.46 },
		["She looked at me for a long moment. Then she gave me a bowl of what I can only call a dare. I took one spoonful and could smell colors."] = { "e81032a6a0aa", 9.64 },
		["She looked at my hand, and at me. \"You always were quick,\" she said. Then she held out her finger and waited for me to put it back."] = { "e114f266b192", 8.93 },
		["She looked both ways, leaned in close, and pulled a spare pair of socks from inside her breastplate."] = { "5c7ece10979c", 6.48 },
		["She married the fellow who repaired both their ships. The captains are still competing. Now it's over who gets to be godfather."] = { "d3aed64ea80d", 8.33 },
		["She moved camp that night. Come morning, the fire she'd left was still burning, with no ash at all."] = { "70273fb392e2", 6.9 },
		["She needed the blood of General Drakkisath, master of Blackrock Spire. The Horde tells of Rexxar in Desolace, who learned the same secret, and sent his champions after the same blood."] = { "45b17296b275", 12.51 },
		["She said a hammer remembers what it was first used for. I don't know if that's true. But mine has raised a great many shelters, and I like to think it hesitates."] = { "f97cf9de88be", 10.71 },
		["She said it wasn't called anything. It was only a hill. And the grass was poor, so she'd be moving on by noon."] = { "e7a04811b35c", 8.1 },
		["She said it wasn't courage. Nobody had ever managed to stop that horse. That's why we still had it."] = { "5fbd31163953", 6.71 },
		["She said she knew. She said someone had done the same for the forest she'd grown up in, and she'd never met them either."] = { "d8d9d00e453b", 8.15 },
		["She said that wasn't the chair's concern. I've thought about that on every rushed job since, and I've still rushed most of them."] = { "f0eb9c3dce61", 7.99 },
		["She said the finger isn't how you tell. You watch the gulls. The finger's just there so visitors feel included."] = { "97fb43b9bfae", 7.5 },
		["She said the safe mud has tracks in it. Frogs, birds, rats. The bad mud is smooth. Nothing walks there, so nothing leaves a mark."] = { "88d072ce6158", 9.87 },
		["She said the straight logs are easy to stack. Anyone can stack straight logs. The crooked ones are what hold the pile together, if you take the time to fit them."] = { "d8a31d366eff", 9.46 },
		["She said this horse used to bring her son's letters. There hadn't been a letter in eleven years. She went in and got the apple anyway."] = { "4d49fdefa7ae", 8.8 },
		["She said those words without a tremor. And all the while, her hands behind her back were shaking so hard she had to hold one with the other. Sixty years, she did that."] = { "e6e4de29b4db", 11.31 },
		["She said, it isn't empty. It's grieving. Sit down. So we sat. For three days. On the fourth, it rained a little."] = { "1d333f599a69", 8.8 },
		["She says it's the stew. It is not the stew. Everybody knows whose room is at the top of the stairs."] = { "f18687741845", 7.55 },
		["She set the grass alight, right in front of us. I thought she'd gone mad. It raced away downwind and left a black patch, smoking. \"Drive them onto it! Now!\""] = { "bb48dd017ea6", 12.04 },
		["She sneered at it all. Bolvar made the messenger a deputy anyway, and Solomon sent them on to Marshal Maxwell. And Maxwell had a missing man on his mind."] = { "d3b39b53e2cb", 10.89 },
		["She stepped over me without spilling a drop. Soup's on Elder Rise, she said, if you arrive this week."] = { "bf983c8a8fb3", 6.61 },
		["She stood in the middle of that cloud with her arms folded, stung a hundred times and not even blinking. Fifty years of practice."] = { "1384d0f8ee48", 8.83 },
		["She struck Windsor down with one claw, mocked Bolvar as her puppet, and vanished. But she left something behind."] = { "924224e36d37", 7.73 },
		["She thanked me very warmly, from the roof."] = { "101115e8d142", 2.85 },
		["She thanked me. Then she asked me to walk back with her and explain it to him, because she wanted to watch his face."] = { "3b0071075a8b", 6.84 },
		["She threw a pot at me. Then I changed, and she listened, and she was on her way while I was still catching my breath."] = { "845752e0031b", 7.55 },
		["She told me you carry a piece of every fire you sit at. You forget the names, but you keep the warmth."] = { "a3345537a156", 6.79 },
		["She waited ten thousand years once. She is waiting again."] = { "bcfbee23626b", 4.39 },
		["She walked around that spot once, then put her head down and went on. Nobody said anything until the village."] = { "5df2c660b30f", 7.55 },
		["She walked out into her yard, looked them over, and kicked down the first hive. Then the second. Then all twelve."] = { "282fc0b05de0", 7.73 },
		["She was angry about the reins for exactly one breath. Then she looked over the ridge, sat down, and asked if I'd like to stay for supper."] = { "1f610c3a088f", 8.75 },
		["She was sitting on a rock, drawing in the snow with a stick. She looked up and said, \"Largest failure I've ever been part of. Think how much there is to learn.\""] = { "1f081e94943a", 10.55 },
		["She was the fattest goat I ever saw. Everyone kept feeding her out of guilt, you see. I gave them all one penance: share the cheese."] = { "bdba8724ad15", 9.9 },
		["She went down to the shoulders and kept sinking. I couldn't reach her without going in myself."] = { "3e6d0e07234e", 5.77 },
		["She went over the edge after it. Just like that. The gryphon was already halfway down the gorge, very pleased with itself."] = { "746ca5004487", 8.65 },
		["She won a great deal of the time, my auntie. Sometimes on the red crab, sometimes on the blue. Nobody ever could find a pattern in it."] = { "07e840db66d5", 9.4 },
		["She won. I still think that was fair."] = { "29ce92b7f137", 3.27 },
		["She wouldn't let me. She said it was the first map she'd ever made that got better by being wrong."] = { "ca288e35c743", 5.88 },
		["She wrote back that night, and I carried that one too. He paid me two silver, and didn't open it in front of me."] = { "e8f40a83269b", 7.13 },
		["She'd be pleased about that. She always said I'd come around. It only took me nine years."] = { "7bed2a323c8f", 6.14 },
		["She'd pour it out on our doorstep. I asked her why, and she said it's so the sea would know where we went. So the island could find us again."] = { "fc056667bd01", 9.3 },
		["She'd wrapped a lot of suppers for that road, she said. Mine was the first cloth that ever came back."] = { "23d802534832", 6.43 },
		["She's been in the ground twelve years, which is the only reason I kept my feet on the road. I stood there with my heart going, not answering."] = { "f188168c81b9", 9.17 },
		["She's gone now. I don't know if I believe all that, mon. I don't think I do."] = { "a2be1b8679c1", 5.28 },
		["Short of the city, Arthas finally reached her. Her bow broke on his sword, and she asked him to end it quickly."] = { "e979d0bdc0a4", 7.86 },
		["Since nobody's sleeping yet, here's one to keep you up."] = { "62063d05babc", 3.5 },
		["Sit there, the barkeep says, and you'll dream of the sea every night for a week. Sailors line up for it. Not one of them will tell you what the dream is."] = { "7d104c2313ec", 10 },
		["Six days. By the end we had a routine. I'd complain about the heat, and it would make a little noise. I'd started calling it Gerald."] = { "68fafb45a9cc", 10.06 },
		["Six of us set out that autumn. I packed the food myself, so I know. Six."] = { "dcf53ce664dc", 6.43 },
		["Sleep well, everyone. Keep the fire high."] = { "7a5fc2c65818", 3.21 },
		["Small folk ask how I can stand so much open space. I ask them how they can stand so many walls."] = { "5bd27e4d1151", 7.39 },
		["Small. Wrapped in plain brown paper. No note, and no word of who it was from."] = { "8dcc54656e40", 6.53 },
		["So I asked a guard for the way to the Trade Quarter. I'll remind you what some of those guards are. It was a big stitched-up fellow, with a lot of arms."] = { "aa46cfc88f9f", 10.14 },
		["So I asked her about the second one. The faster one, lower down. She stopped smiling and asked me which root I'd been listening to."] = { "613c3505ecb8", 8.52 },
		["So I asked her to teach me hers. She gave it to me a few words at a time, and stopped me every time I rushed."] = { "c13db93cf526", 7.58 },
		["So I asked one of their goblins, between selling me a fruitcake and a second, larger fruitcake. He got out a ledger as thick as my arm."] = { "d81e21d77750", 9.12 },
		["So I asked the butcher what was in it. He looked at me for some time."] = { "3cebd3eefe1f", 4.52 },
		["So I beat the drum. Every head in the valley turned at once, and the driver was so startled he hauled his beast to a stop."] = { "b61e4f2628b2", 8.15 },
		["So I bought it. He charged me for the hours I'd hired it too. That was the deal, he said, and pointed at the sign I'd been standing under all day."] = { "89e2b717440b", 10.29 },
		["So I called on it to help us. I was very respectful. I said all the proper words. And it came down through the dry grass, and it helped."] = { "4927102c0338", 10 },
		["So I can't say why, when I reached a fork in the trail, I looked at the sign that said Webwinder Path and thought, I bet that's a shortcut."] = { "86ef3d965fb1", 9.9 },
		["So I did, one grey morning in the high woods. And there they were, fresh prints laid over mine. Somebody had been walking in my steps."] = { "f51e1a6e3fda", 10.42 },
		["So I fitted two latches. They each tested their own without a word and went inside."] = { "98b1d39a0035", 6.19 },
		["So I folded a bit of paper under the short leg. The fellow at the next table asked how I'd done it. He'd been fighting his all night."] = { "d0361213325d", 8.46 },
		["So I followed the arrow. It's a stiff climb. And at the top you can see a very long way, and every part of it is gray, and I sat there for an hour out of spite."] = { "5f0011cf4317", 11.21 },
		["So I grabbed a burnt cork from the wine rack. A bad black smear where the twelfth mark should be. I said the words, and the door came down."] = { "4ffbc1d20190", 9.87 },
		["So I held the lamp and took down a letter, three hours, to a brother he hadn't spoken to in forty years. It was mostly about a fence."] = { "7104df0629a3", 9.04 },
		["So I jumped on it. I stamped and I jumped till it gave way and I went in up to my neck. I stood in that black water till dawn, with the thing pacing the bank."] = { "f16ebf06a95a", 10.61 },
		["So I just grabbed a bucket, filled it, and handed it to the person beside me. She handed it on. Then the next one did. In a moment, the line was there."] = { "ea6a670393e5", 10.61 },
		["So I lay flat, held out a bucket by the handle, and when she grabbed it I pulled like I've never pulled anything."] = { "07e6c3c29e51", 7.16 },
		["So I learned to knock. People laughed, and came out with an apple for her. Went on like that for three towns."] = { "72fab6db9c3a", 7.97 },
		["So I paid three more, and he drew me again, this time pointing the right way. I followed it. He was right. I still have them both."] = { "7a4b98e48c42", 9.22 },
		["So I ran. Boulders, gullies, sharp red rocks, and these huge beasts crashing along on either side, close enough to smell. I figured I was finished."] = { "25d920e4e162", 12.04 },
		["So I ripped the sack wide open. Grain poured out everywhere, and that horse stopped dead to eat it. I didn't stop. I went right over its head."] = { "a6f7d15f8606", 10.08 },
		["So I say my name, going in and coming out. Now and again, coming back, it takes a moment."] = { "3e3f6fe51af4", 6.53 },
		["So I sent it as it was. Somewhere, maybe, a brother still thinks his family had a very good year."] = { "e5eb49a12a07", 7.21 },
		["So I shut my mouth. I walked two hours without a word, stepping softly, and it was all right. It got better. I could see the edge of the woods."] = { "8c1523339201", 10.42 },
		["So I stepped off. Ten breaths of falling slow, steering for that ledge, and I landed with one to spare."] = { "306598df7ce5", 8.1 },
		["So I stood up. Partway through standing up, I got a good deal bigger. He dropped the lantern. The others came running, and then ran."] = { "beb349537a85", 9.77 },
		["So I stopped pushing, got down in the water, and put my shoulders under the back axle. My mother always said I was built like a hill. I was glad she was right."] = { "7f7f53a6a932", 10.92 },
		["So I stopped. Just stopped. His tonk shot straight past, hit the barrel, and fell over."] = { "02cda0545832", 6.61 },
		["So I thanked him again, and while I was thanking him, I missed that one as well."] = { "4e74e4eeb5f5", 5.07 },
		["So I threw a coil of rope at the boat with a boot tied to the end for weight. It landed square on his chest."] = { "49bdf8fbb65a", 6.97 },
		["So I told her. The binding, the nature of the entity, the sealed circle I'd need on the floor. I don't know why. I was tired."] = { "7505c8779586", 9.95 },
		["So I took his hand and asked if he had anybody at home. He said he had a dog. A terrible dog, that had bitten everyone he loved."] = { "1dfaba7f1e69", 8.93 },
		["So I took out my scarf, for something to look at. A good red scarf. My sister made it. I'd worn it for years, and I remember the day I got it."] = { "067c61e39fb7", 9.9 },
		["So I took that money back, on behalf of the public. And some of the paper. Nice paper. Purely an educational experience."] = { "cf6d409769ca", 9.12 },
		["So I took them to see a valley where someone had once killed all the wolves. Too many deer. Nothing but bare earth and bones."] = { "dc6bf8aaf767", 8.41 },
		["So I tore a strip off my shirt and tied it to a branch, and I walked on with the sun at my back."] = { "f635045aab1c", 6.11 },
		["So I try to keep a light on. You never know who's still on the road."] = { "737b9a62c45d", 4.86 },
		["So I waited up. Midnight came, and the wall was bare. I looked down to rub my eyes."] = { "49bbacdefbd0", 7.08 },
		["So I walked across the Commons, smoking, trying to get my arms out of the sleeves. People stepped aside. Nobody shouted."] = { "71e3436a099d", 9.22 },
		["So I walked into Jasperlode Mine with a crate of candles, and I'll be honest, it worked. They left me entirely alone."] = { "94046cccdb06", 8.83 },
		["So I walked up to have a look. The third man had her, stolen from the second, who'd stolen her from the first, who'd had her from his cousin the same way."] = { "1c3b9033eebf", 9.48 },
		["So I went back for another try. She made me a pirate. Then a bat. Then a pirate again."] = { "28335f1b487e", 6.97 },
		["So I went forward along the pole, between the horses, with a bread knife in my teeth, and I cut the traces one by one."] = { "15acc1035bf0", 8.15 },
		["So I'd stack a little for whoever came next. Then one bitter night, half dead, I stumbled onto a camp with a neat stack all ready."] = { "0cf9382910f3", 9.22 },
		["So Tirion's gift went into Hearthglen in Scarlet colors, through the gates and up into Mardenholde Keep. Right to the Highlord himself."] = { "e51511a98b7f", 8.93 },
		["So before every ritual I eat a good bowl of porridge, take a nap, and go see someone who's glad to see me. The others used to laugh."] = { "6c41fbd58213", 9.06 },
		["So brave folk went after those two and took the notes back, carved on stone tablets. What was written there, Windsor said, would end a grand deception. Now he just had to get out."] = { "2ae93084ac29", 12.28 },
		["So don't aim for where a person looks like they're standing. Aim a little under. You'd be surprised what you hit."] = { "4094c7b8d508", 6.71 },
		["So each of us carries a little stool. You'll see it, if you look. Nobody mentions it."] = { "f4b2fe14a321", 6.61 },
		["So each one salted the soup when the other wasn't looking. Every day, for thirty years. It was dreadful soup."] = { "f1091c54917d", 7.81 },
		["So for nine years, two people who never met have been telling each other how much they miss each other, in our words."] = { "f2cdf846d1cf", 7.44 },
		["So forget my name if you have to. I won't mind. Just take a little of the warmth along."] = { "3294684aaee4", 6.24 },
		["So happy Midsummer. This one's for us."] = { "96f33bac0055", 3.45 },
		["So he brushes, and they open. I thought it was the dullest job I'd ever seen. Now I think about it every time something sticks."] = { "b9681f86ba86", 9.06 },
		["So he killed her, and then he tore her spirit from her body and bound it to him. She had to follow him into her own home while he finished it."] = { "025b0855b7ea", 9.12 },
		["So if you see a night elf counting the years, sit with them a while. It's new to them."] = { "7d0a59c74434", 5.64 },
		["So if you're ever in Stormwind and you see a small face at a high window in the keep, wave."] = { "a78897d876b9", 6.06 },
		["So in the morning I went where it pointed. Behind the brambles was the old road, half buried, and it cut a day off the walk to the next town."] = { "158104ddeb5e", 9.77 },
		["So someone had to carry a rope across. I tied it around my waist before I had time to think better of it, and I ran for the edge."] = { "3d8f51b94c1d", 8.1 },
		["So someone must be feeding it, the traveler said. They said it like it might be good news. Someone must still be in there, after all."] = { "50af2d193070", 9.22 },
		["So the letters pile up. Maybe one year I'll meet them at another fire and hand over the whole stack."] = { "ecee131a21b8", 7.03 },
		["So there I was on a narrow stretch of castle wall, with teeth coming at me from either end. I did what I'd practiced. I stepped."] = { "f109abdbca5d", 9.3 },
		["So there I was on the Tradesmen's Terrace, with pollen coming down from every side. I felt it coming. I tried. I want that known."] = { "52b7b58cd50e", 9.72 },
		["So there I was, three days later, up to my thighs in warm black water, with things hatching around me. I saw eggs bigger than I am, and every one of them was moving."] = { "be81265339d6", 12.04 },
		["So there you have it. Who's got the next one?"] = { "fc7bec3f933e", 3.19 },
		["So they came to Dalaran to learn it again. Nobody knows if the spirits are ever coming back."] = { "625aca569d23", 6.06 },
		["So they put the crown on his son, and set a regent beside him to rule until the boy is grown."] = { "34ab2a087faf", 6.37 },
		["So they raised a hand to see. The reflection didn't. It just went on looking up at them, and it looked sad, or maybe sorry."] = { "a82547ffabbb", 9.53 },
		["So we backed the wagons to the top of the slope and knocked out the tailgates. Forty full barrels, downhill, straight into the pack."] = { "ed0d9f4fe84e", 8.93 },
		["So we burned the books. We thought if no one read the names, no one would answer."] = { "b2b5b8f4259e", 5.04 },
		["So we did, and then we argued for an hour over who got to keep it."] = { "7b914345ec9e", 4.34 },
		["So we had a sheep. A very angry sheep, standing in the camp, and perhaps half a minute before it went back to being a bear."] = { "3452d998a4de", 8.33 },
		["So we spent those two days trying very hard to kill each other. Over nothing. Over a war that had already stopped."] = { "a1e044c49aab", 8.33 },
		["So. Sixty years of terror, and nobody had simply asked. I think about that more than I'd have guessed."] = { "7098b30d81bb", 7.99 },
		["Some days it's a sunrise. Some days it's a hot meal. Some days, I'll be honest, it's that someone I can't stand tripped over a tent rope."] = { "c87855b8ea20", 10.61 },
		["Some evenings in Mulgore, at the very end of the light, a herd will cross the far side of the plain. It's a big one. You'll feel no hoofbeats. The grass will not bend."] = { "a7a6309ccf48", 12.38 },
		["Some fools go up into the high limbs to run them by moonlight. I was young, only a few hundred years old. Of course I went."] = { "07d96758a309", 9.12 },
		["Some nights I lie awake and think: that thing will outlast the stars, and it thinks I should get a bigger bed. It's probably right."] = { "6575774aadcb", 9.17 },
		["Some of those graves have axes for markers. Some have arrows. Nobody's in much of a mood to tell you which is which."] = { "d5f45c10a690", 7.44 },
		["Somebody built that terrace to stand straight, ten thousand years ago. As far as the water's concerned, it still does."] = { "16a8098f3ed1", 8.65 },
		["Somebody put up a sign in Desolace. On the track above the Kodo Graveyard, hand painted, with an arrow. It says Scenic Overlook."] = { "8cd814957f12", 10.24 },
		["Somebody told me there's a kodo in Mulgore that's been on the council at Bloodhoof Village three years running. Nobody's quite sure who voted for it."] = { "23a0866a60d9", 9.17 },
		["Somebody's got to stand where nothing grows, he said. That's how it works. That's how it gets to grow someplace else."] = { "65fa7fad004b", 7.39 },
		["Someday that tree will shade a whole camp. I want it on record that I was its first customer."] = { "7448102a426a", 6.95 },
		["Someone dug it up for Tirion. Then went north to Northdale, where Taelan had once thrown down a banner. The Symbol of Lost Honor, the day he turned his back on the Silver Hand."] = { "3198f8dd51f1", 11.86 },
		["Someone reaching for a door. Two together. Most of them have been worn down by the wind, and you'd have to know what you were looking at."] = { "32bb523bc881", 8.93 },
		["Someone took me by the arm and sat me down. I never did see who it was. I took off my boots, and I put my feet on that grass, and I'm not ashamed of what I did next."] = { "89895678c0e2", 11.49 },
		["Something did. We came out through the hillside into open air, shot off a ledge, and landed in a frozen tarn. I'm told the steam was visible for miles."] = { "942b05ae4069", 11.55 },
		["Somewhere across the sea, they say, there's another light that answers twice. Thirty years now. Neither of them has ever crossed."] = { "a36894a3f176", 9.64 },
		["Somewhere past midnight the wind dropped dead. The grass stopped moving. And the wailing kept right on going."] = { "356de57615a4", 7.39 },
		["Somewhere there's a door someone is still watching. And I'm wearing the reason he never reached it."] = { "b642b7c579a9", 6.24 },
		["Sorry. Some tales need telling, even the hard ones."] = { "795e94bf468c", 4.65 },
		["Southeast of Mystral Lake, a torchlit path runs down to a stream. Across it lived Krolg, a furbolg untouched by the madness, who'd fight any stranger. So the rod was raised, and its bearer wore fur."] = { "149223491881", 16.27 },
		["Squirrels: \"Mine. Mine. Where did I put it? Mine.\" That's the entire conversation. Deer: \"What was that? What was that? Oh, what was that?\""] = { "aa9f3e1581ab", 13.48 },
		["Stayed late at a roadside place once. At closing, the keeper calls out \"last call,\" the way they all do."] = { "0c12f9257fdf", 7.37 },
		["Step in, rain. Step out, nothing. I'm ashamed to say I did that a dozen times, like a child with a door."] = { "35cbfbf2f126", 7.86 },
		["Still water isn't so restful for me now. It's very patient, and it knows I lied."] = { "72ce17a0bdeb", 6.32 },
		["Still, nobody's ever complained after three days in the wilderness. Hunger is an excellent sauce. I don't conjure sauce."] = { "57af54f67f26", 8.41 },
		["Stirred through two wars and a wedding, and never once tasted the stew. Said that wasn't the job."] = { "3bd1a36de047", 7.44 },
		["Stone remembers, he'd say. Every blow. It just takes its time telling you."] = { "d79111281b0f", 6.24 },
		["Stools. Plates. A whole bench, thrown by two people who I think were married. Somebody swung a roast goose. I've seen sieges with less commitment."] = { "4b193d621388", 11.76 },
		["Stumps for miles. Sawdust drifted up against the rocks like snow. A rusted machine the size of a barn, sitting where somebody got tired of it."] = { "a6d780ca3aab", 10.29 },
		["Taelan cut his way out of his own keep, through the very soldiers he'd commanded. Out of Hearthglen, down the road, toward the edge of the forest where his father waited."] = { "d1fbe9440d5f", 10.71 },
		["Taelan opened it. The hammer. The banner. The painting of a beach and a father he'd been told was dead. He said it couldn't be true, and knew it was."] = { "abcd8acd83ee", 10 },
		["Take a look at a map of the Western Plaguelands sometime. Read the names. Dalson's Tears. Sorrow Hill. Gahrron's Withering."] = { "2c7317a50f98", 9.87 },
		["Take it or leave it. It's served me well enough."] = { "82101fe36696", 2.85 },
		["Taken from those who sing one word by the sea,"] = { "04e46dc086f5", 3.21 },
		["Tall things fear the wind, she said. The grass knows it's only visiting. She never asked what I was angry about. I've forgotten some of it myself."] = { "1f0b3780e57e", 10.08 },
		["Ten of them, and one of this. I have run the numbers every way that there is."] = { "4e76d776ac6e", 5.49 },
		["Ten silver. I paid it, too. His version's much better than mine."] = { "627e5a50bebd", 4.94 },
		["Ten years of that. Everything I really know, I know from those evenings. When he died, I went through his notes and found out how it had been."] = { "51c5e7c086f0", 9.25 },
		["Ten years, it turns out, I'd been singing at that gate. She wanted to know if I took requests."] = { "003399f53e02", 6.9 },
		["Teronis's notes pointed to a dryad named Shael'dryn, who keeps a moonwell east of Iris Lake. She took the gem and frowned. The rod was in pieces, she said, and the forest around them had gone wrong."] = { "1486180ac97c", 13.82 },
		["That beast flew through every cloud in the Hinterlands. Every tree branch, too. It took a slow, thoughtful turn across Valorwind Lake, at the height of my knees."] = { "2a982b1c7675", 11.08 },
		["That imp has never eaten bread in its life. It called her a fool and a waste of good meat. Then it hid the crust where it thought I couldn't see."] = { "e5b3f5df7ee8", 8.99 },
		["That last one has only happened twice. Both of them are fine now. One of them can see colors nobody else can."] = { "18f58539efe7", 7.68 },
		["That night I made my own stew, stood a spoon in it, and watched it fall over. So I kept adding flour."] = { "407b20f2af68", 7.5 },
		["That night the stone cracked open, and something small and green climbed out and bit him on the thumb."] = { "33de7d747be5", 6.19 },
		["That same night he sat down at the bar and asked the keeper's son to start him a new one. The son doesn't laugh at the joke."] = { "1faf94e8cfef", 7.99 },
		["That village ate all winter. I've done grander things for grander people, and not one of them mattered as much."] = { "285533ef6bb6", 7.37 },
		["That was all of it. Now I lie awake when it rains, and I wonder who went up that ladder."] = { "7a852ebb8c90", 6.19 },
		["That was eleven years ago. It has been to every place I've ever been. There's a good bit less of it now. Stoppers are not what they were."] = { "92f23cda64b6", 9.77 },
		["That was the first page. It wasn't the last."] = { "d33591ba4726", 3.79 },
		["That was years ago. Every midwinter I get a note from him, and it only ever says, \"Still leaning.\" I keep them all. I check the bone first now."] = { "cc5f22d6068e", 10.74 },
		["That was yesterday's list, he said. I'd paid for the crossing, got on, and never got off at the other side."] = { "fd86c58052ca", 7.31 },
		["That's all of it. Make of it what you will."] = { "2be7e9d9bf0c", 3.19 },
		["That's all the wisdom I have. Somebody lit a fire for you once. Stack some wood."] = { "542ab2495e8c", 6.56 },
		["That's all. No voice, no vision. Just the right knot, and then the wind again. I sat there in the mud for a while. That fence is still standing."] = { "d3b406d33d40", 11.08 },
		["That's for a she-bear with a white ear, he told me. He'd had her dead to rights three times, and three times he'd lowered his bow."] = { "ffd762a10e14", 9.06 },
		["That's how I heard it, anyway. Someone else might tell it different."] = { "0a39d2d59eaa", 4.65 },
		["That's how it ought to be, I said. I said it the whole way back to the road. I said it for a long while after that."] = { "cdd44cb06891", 7.81 },
		["That's how they get you. It's never power that they offer, not at the start. It's that something finally listened."] = { "3e8b268e444d", 7.63 },
		["That's how we noticed. A slow sound, in and out, coming from an open grave at the far end of the row."] = { "445983250aff", 7.39 },
		["That's not what bothers me. It's the boots. I sat down in new boots, and I woke up with the soles worn nearly through. I've no idea where I went."] = { "33bd0641de56", 10.08 },
		["That's the thing about home. It's not that it's safe. It's that it lets you forget, for a little while, that nowhere is."] = { "b4a6351b896e", 9.06 },
		["That's the true work. You're not their master. You're the one who has to keep the peace at a very loud family dinner."] = { "b73d78724330", 7.5 },
		["That's when I started walking. Whatever it was had been learning what I liked."] = { "c09e34cf419d", 5.22 },
		["That's when the reflection started moving away from me, along the water, toward the deep part of the marsh, as if it wanted me to follow."] = { "e18f826756c8", 8.83 },
		["That's where it starts. It gets worse from here."] = { "e8c5cbd21f5b", 3.21 },
		["The Charred Vale? Charred. Windshear Crag? You will be sheared, by wind. They're warnings, all of them, and they're very fair."] = { "4ba1c4613cdd", 10.89 },
		["The Harvest Festival honors two heroes. The Alliance remembers a paladin, and the Horde an orc."] = { "7d1dd27993ef", 7.44 },
		["The High Order came for a different reason. Their forebears were magisters, and they had let most of what those magisters knew slip away."] = { "7c902723f292", 9.06 },
		["The Light went out of me, once. I don't tell many people that. I put my hands on a wounded man, and called, and nothing came."] = { "8b2d45973104", 9.59 },
		["The Skyborne were Highborne once, in the city of Eldre'Thalas. Most folk call it Dire Maul now."] = { "4d4dcc884997", 7.21 },
		["The Windshapers came down to Azeroth to find out where the spirits went, and to bring them back."] = { "14c63d120421", 5.83 },
		["The autumn after I lost someone, I ended up at Mystral Lake without meaning to. I had no business there. I'd just stopped choosing roads."] = { "363b4d3bcab9", 9.72 },
		["The barkeep thought it over and said, nothing is good. It's Brill. I appreciated that. You don't often get such honesty from someone with so few lips."] = { "1ac7c34f7b1c", 10.74 },
		["The barkeep told me later she'd invented that game. She'd come in that evening on foot, and she'd be leaving with her fourth horse this month."] = { "e4a85cbf9121", 9.3 },
		["The barrel floated down to him, and he grabbed it and held on. We ran along the bank and fished him out at the next bridge with a mop handle."] = { "efb3e767052f", 8.83 },
		["The beam stopped an arm's length above the fire. The young ones went on eating. Not one of them looked up."] = { "5f9e8a0ba0b8", 7.21 },
		["The big quiet one I keep doesn't speak. It has no mouth that I've ever found. It stands in the corner and listens to me work. I talk to myself a lot."] = { "7dded033c34d", 10.89 },
		["The bird followed me. It didn't attack. It never made a sound. It just stood about ten feet off, looking at me."] = { "6fd9f7d40bb0", 7.86 },
		["The blast burned Grom, and he did not get up again. They say he told Thrall he was finally free of it."] = { "8a2af8045120", 7.16 },
		["The boar sat at the bottom. I sat at the top. We looked at each other for most of the afternoon."] = { "157356ecd417", 7.21 },
		["The bookmaker ruled that the wheel had won. Then he ruled that I'd bet on the car, not the wheel. I've never heard a sound like that crowd."] = { "1ab7e8a6902f", 9.46 },
		["The boy king of Stormwind is named Anduin. He was named for a man: Anduin Lothar, the Lion of Azeroth, Stormwind's champion in the First War."] = { "8276913aa91f", 11.08 },
		["The boy said I should have thought of that. I told him I had, around breath four, and decided I didn't care."] = { "4e1098cad711", 7.37 },
		["The bridge dropped out from under her, and she swung across that gap holding on with both hands and cursing my whole family by name."] = { "d31300b33b45", 8.15 },
		["The bridge started swaying. I opened one eye, and there was an elder, older than anyone I've ever met, walking along with a full pot of soup."] = { "ed2edc1db5ec", 9.95 },
		["The bronze ran right up to that line and stopped. Two apprentices were standing on the far side of it, still holding their tongs."] = { "1f372418fbf8", 8.83 },
		["The bubbles stopped. Then they came up again, right beneath us this time, and a good deal faster. The boatman took the paddle from me without saying a word."] = { "1b887d9514f1", 10.84 },
		["The bucket glowed for a week. You could read by it. People came from three valleys over and paid a copper to look."] = { "d92abe470ce9", 7.55 },
		["The bull won his ribbon that afternoon. I was never asked back to judge the pies. I'm told the crumbs were held against me."] = { "00afacf3ba3b", 8.83 },
		["The camp cook and I had a difference of opinion about seconds. I'll say no more. He charged me extra for that dent."] = { "61f3b387fd9a", 7.68 },
		["The canyon is still there. They call it Demon Fall. I stop when I pass it. I'm never sure if it's for him or for Cenarius."] = { "23122494c425", 9.4 },
		["The carnie gave me a prize ticket and asked me never to come back. Best win I ever had."] = { "825cf26cd07c", 6.06 },
		["The champion shook my hand, took off his apron, and tied it around me. Meals on the house, he said. You're the house now."] = { "92e8d08b8f1a", 8.8 },
		["The child was fine. Not a scratch, not even wet. I'm told I made a very large splash."] = { "9a18a66ab045", 7.21 },
		["The coin bore my family's mark. I'd never told him my name."] = { "53fd590fda63", 4.62 },
		["The column came down where she'd been sitting and broke into three pieces. Dust everywhere. We lay there coughing for a while."] = { "116d9ae54e33", 8.1 },
		["The cough stopped that same night. He got up and ate like a horse. When he found out how, he never spoke to me again."] = { "f985dc470dc5", 8.1 },
		["The dam above our valley let go at dusk. You could hear it before you saw it, like a cart full of thunder."] = { "d21b376c21ec", 7.37 },
		["The dig master took it off me, wrapped it in cloth, and wrote something in his book. He didn't seem surprised. That bothered me more than the hand."] = { "8673622b286c", 10.24 },
		["The dock folk have fourteen words for rain. There's one for rain that comes sideways. There's one for rain that gets in your ale."] = { "20d6ccc5567b", 8.65 },
		["The dogs were running straight for a ridge. Over that ridge was a long, steep drop."] = { "72c8d8619233", 6.32 },
		["The door swings open. Pitch dark. We strike a light, and there's the goblin at a little table, with a pot of tea and three cups."] = { "1025a92204f3", 8.99 },
		["The door swung open, my friend rolled out into a ditch, and I rolled in after him. The wagon went on to town carrying nobody at all."] = { "de890c69473a", 8.41 },
		["The driver didn't even try. He sat down and took out his pipe. Ten minutes, he said. She lost a calf here, a long time back. She does this every year."] = { "a819e08b1be3", 11.55 },
		["The driver woke up at the inn and asked if he'd missed anything. I told him only the scenery."] = { "756b3968e5f7", 6.3 },
		["The druid didn't say a word. He just turned into a bear and sat down on the goblin's stall."] = { "53d1c82c5826", 6.48 },
		["The drum's owner limped home with a bruise and told me that's not what that drum is for. Then he bought me a drink anyway."] = { "ce35b03d5056", 7.5 },
		["The eighth never turned up. I traded for it, begged for it, nearly bought a fake from a goblin."] = { "702227fa81a4", 6.9 },
		["The elder asked, very respectfully, if I might do his mule. I said the Light was not a lantern. He offered two coppers."] = { "d3b49ebe0dad", 8.75 },
		["The enemy turned south and never came near the place. People think I don't eat apples because of my teeth. I let them."] = { "0c2351d45df1", 7.68 },
		["The family kept a summer house near Eastvale in Elwynn, and Stalvan went with them. Years later, another page turned up in its attic."] = { "c11dd5504dd3", 9.25 },
		["The fanatics camped outside carried scraps of parchment. Gather enough of them and a name came out of the ink. The Cult of the Dark Strand. Balthule had never heard of it."] = { "a93a28c2c249", 12.17 },
		["The farmer brought me a bowl of soup anyway. Out of pity. It was chicken soup, but not that chicken. That chicken is still out there."] = { "639766b3cc6d", 8.62 },
		["The farmer nodded. I dropped the sack straight down the ladder. It burst on the first one's head, and the whole barn went white."] = { "5bde7bf53d12", 8.83 },
		["The fence who brought me up cheated me on everything I ever sold her. Eleven years. I knew it, and she knew I knew it. We got along fine."] = { "0735e53a87eb", 10.55 },
		["The fifth I kept, because a person should always have something left to lie about. My companion went off the rock and took the rest."] = { "2c5a3faf10e9", 8.33 },
		["The fire's getting low. Rest well, friends."] = { "ed019e6686c7", 3.79 },
		["The first day they all flew off when I scratched my nose. The fourth day I stopped being bored, and that was worse. The things you think about out there."] = { "8f3cb2ba460e", 9.46 },
		["The first deer I ever shot, I shot badly. High and back, and it ran. I was pleased at how far it went. I was very young."] = { "e34d95cba0aa", 10.5 },
		["The first dry summer, I went up there with a full bucket. It had three brown leaves on it. I stood there for an hour, then poured the water out on the path."] = { "96c8cb885a9b", 10.42 },
		["The first flower picked by an herbalist's hand,"] = { "ae3d2be60d3b", 2.85 },
		["The first gust threw me upward, higher than the cliff. The next one dropped me nearly to the waves. Lightning on my left, and that rope dragging like a dead whale."] = { "0af8b65e0882", 11.34 },
		["The first patrol stopped me and asked. I said I was on the side of whoever was hungry. They bought a sack, and paid me not to mention them to anyone."] = { "ec052f9a6470", 9.25 },
		["The first scholar I showed said I'd drawn it backward. I went back and checked. She was right, so I copied it again, very carefully."] = { "594c8b979067", 9.77 },
		["The first thing I noticed was the wind, once I'd walked out across that red ground. It was blowing at my back. Steady, and not strong. And I thought that was odd."] = { "83825548de23", 11.44 },
		["The first thing you loot from a bandit's cold hand,"] = { "2c032a246b91", 3.32 },
		["The first time I sat at a storyteller's fire, she finished her tale, looked right at me, and said, your turn."] = { "e19354f61ec5", 7.97 },
		["The first time I visited Stormwind, I tried to find the Trade District by following the canals. Do not do this."] = { "431715ffef42", 7.44 },
		["The first time any child of ours goes off the high ledge, an elder stands behind them. Not to push. Just to say the same four words. \"The wind's got you.\""] = { "9ab70cf16bf4", 11.39 },
		["The first time something answered me from the other side, it knew my mother's name."] = { "9a4759a90608", 5.04 },
		["The first time, I lit it from across the room with a lovely flourish of one finger. She wrote something down and told me to come back in a year."] = { "d4ff8a4c0c49", 9.17 },
		["The first walked me along the fence line, past a fat sheep with one black ear grazing right on the border. Then he served roast mutton. Very fine it was."] = { "59a3dd088147", 10.89 },
		["The fish seller was furious about the fish. Then the boy's mother turned out to be his best customer. He gave me a free herring."] = { "2bbfb8479e41", 8.7 },
		["The fishers of Loch Modan won't put a line down near the Stonewrought Dam on a still night. They don't tell you why, so naturally I did."] = { "104070750354", 8.7 },
		["The flag dropped. The goblin car exploded. The gnome car took a good lead for almost a whole minute, and then it exploded too."] = { "71258e50e552", 8.28 },
		["The flowers left at both are the same. Wildflowers, picked on the road by tired travelers."] = { "b71264824c8e", 6.79 },
		["The foreman walked me up a hill of straight, beautiful pines and asked if I could guess who their mother was."] = { "4c1472d4016e", 6.06 },
		["The gate swung, the water went, and twelve very wet people walked out past me. I stayed in the box a while. It was the warmest place in the tunnel."] = { "5932c223d183", 10.37 },
		["The gem came back to Astranaar in the end, and so did the journal. Raene read it, and asked if someone would finish what her friend had started."] = { "94995cbf6d3f", 8.46 },
		["The girl finally let go of the reins. Then she climbed down and patted me on the head, the way you would a good kodo. I let her."] = { "789366f24679", 8.99 },
		["The goblin said it's the only account they've never managed to raise the price on. He seemed personally hurt by it."] = { "82a94835130a", 6.66 },
		["The granary went up at night with people still in the loft. The door was already burning, and everybody stood looking at the armor."] = { "af2229a62512", 8.05 },
		["The gryphon came back an hour later with the kite in its beak, a little chewed. It dropped it at her feet. They've been friends ever since."] = { "a20e91cec11e", 9.22 },
		["The guide looked at me for a long moment. I asked what was making the sound. He said it's not making the sound. It's just keeping up."] = { "06713da68d3f", 8.83 },
		["The guide said, what's under your home? And I stopped, because I've no idea. I've stopped being sure about the ground anywhere."] = { "8312d98cb730", 9.12 },
		["The handwriting matched. There was no doubt left. Stalvan Mistmantle had killed Tilloa, the young man she loved, her brother, and her mother and father."] = { "fe8b2cd30fd6", 10.29 },
		["The healer who asked me that day seemed less reassured than you would think."] = { "8572546f0ef8", 4.28 },
		["The hills. The lake. Whole forests with their own smaller trees. I asked what happens if something's wrong with the roots."] = { "66210f4643aa", 8.41 },
		["The horse is long gone. Hob's been my closest friend for twenty years, and he still owes me for half the burial."] = { "00500d821862", 7.63 },
		["The horses went left. The wagon went straight into the duck pond, with me on it. Not a soul was hurt, and that pond smelled of ale for a year."] = { "958de9efce00", 9.82 },
		["The innkeeper looked down at me and asked if I'd been drinking. I told him no. I said, why would anyone build this?"] = { "28207ef6f5e5", 7.5 },
		["The iron shaft was locked in a chest in a glade near the Felwood border. The key was carried by a treant. The treants up there have gone mad, and they don't hand anything over kindly."] = { "9af2c959b216", 11.73 },
		["The joker stopped around midwinter. The sergeant gave just one order about it: leave it be, and say good night when you pass."] = { "472b82e4dd4e", 8.88 },
		["The keeper asked if I'd like to apologize. I said I'd found a fault in my eyes, and I'd need another drink to test it."] = { "ea3a6a80ef88", 8.2 },
		["The keeper of one of those great bonfires told me the big fires are for the world."] = { "73eaed32ac79", 5.04 },
		["The knots on that harness were my grandmother's. Nobody else tied them that way. The figure stopped, and raised a hand. Then it waved me over."] = { "0eacf7419291", 10.19 },
		["The last page was written that very evening. It said, someone is walking up the path. We can hear them. We'll go and have a look. That was all."] = { "9878238209eb", 10.97 },
		["The last pages turned up muddy and torn at the Scarlet Raven Tavern in Duskwood. Tilloa had come home with a young man she meant to marry. She introduced her tutor to him as a kind old man."] = { "31ab72b22ddd", 12.56 },
		["The last piece had been given to the druids of Dor'Danil to hide, out east toward the Barrens. The druids were dead. Slimes had swallowed the place, and the pommel with it."] = { "30698f6a3013", 10.79 },
		["The last stop was a cottage miles past anywhere. An old woman opened the door, and she put her forehead against that mare's neck."] = { "33da74e22646", 8.88 },
		["The left head wanted to boil me. The right head said boiling was for vegetables and I should be roasted. It got heated. They'd clearly had this talk before."] = { "df1f4c321806", 10.37 },
		["The left one, empty. The right one, empty too."] = { "867d01988606", 4.15 },
		["The letter just said: you were always one short. Now you're not."] = { "4427536649d7", 4.88 },
		["The letter was for Lord Flintridge of Stormwind. Stalvan got the post anyway. Two children. A boy named Giles, and his older sister, Tilloa."] = { "91f38b166341", 10 },
		["The lieutenant was Ilkrud Magthrull, an orc warlock holed up at Fire Scar Shrine in southern Ashenvale. A burnt, ugly place, crawling with demons."] = { "416312a14a3b", 10.74 },
		["The lift slowed, the rope held, and we stepped off at the bottom. He sighed and said that was a whole week of blades. Then he went to fish them out."] = { "dbf925ea6d27", 10.55 },
		["The light was coming from one side. But my shadow was leaning the other way, and it was stretching up toward that thing, like it wanted to leave."] = { "97523fa5a235", 9.59 },
		["The line never moved. Finally I leaned around to ask what the holdup was, and found I'd been queuing behind a young tree."] = { "98bc986742d9", 8.1 },
		["The locals said it was the old roadwarden, dead thirty years, and I'd do better to leave him be. I don't like being told what to leave be."] = { "1c99c9c7c301", 8.83 },
		["The log jumped tracks and went into the river twenty feet from her. She turned round soaked from head to toe, and asked if we'd done that on purpose."] = { "87db1c885d97", 9.72 },
		["The mage thanked me and asked what it had offered. I told her. She sighed and said it was getting cheap."] = { "24923403efbb", 7.03 },
		["The master made me sweep up the sand myself. He kept the lump, though. Says it's the best thing that forge ever cast."] = { "4b699bd789d0", 8.15 },
		["The miller pulled him out. Then he looked at his broken spokes, looked at me, and said the rail was his too."] = { "fb3dbd78550a", 7.03 },
		["The miner asked who I thought had put that seam there. I carried his hammer for the rest of the day."] = { "e4ace4772237", 5.9 },
		["The mud in Dustwallow Marsh took my right boot on my first morning. It sucked it clean off, and I stood there on one leg, looking at the hole closing up."] = { "a81516e6be1d", 10.66 },
		["The music stopped, and an old wooden flute rolled out under the gate. The innkeeper said that courtyard had been empty since he was a boy."] = { "a6186d8a6929", 8.99 },
		["The next stool she made me, I can actually sit on. I still use the little one more."] = { "d3d2e3efd584", 5.59 },
		["The next summer, every bird on the plain came to our field. All of it, every row, gone before it had ripened."] = { "a0587f06149e", 7.99 },
		["The next time they met, Arthas carried a new sword, and Uther stood guard over his dead king's ashes."] = { "da283c6decae", 6.37 },
		["The night before I crossed Deadwind Pass, I sat in a tavern with a supper I was too nervous to eat. The cook asked where I was headed."] = { "bffa58c7ecb7", 8.52 },
		["The ogre looked up too. Then at me. Then he said, very politely, me not that kind of ogre."] = { "5d2e03f4c46a", 7.39 },
		["The ogres poked me, argued about whether I was dead, and then argued about which of them had killed me. It got loud."] = { "885444c45b7f", 8.05 },
		["The old hands at Eastvale Logging Camp have a rule. In every stand you cut, you leave the crooked tree."] = { "c7e68ba5e1d7", 6.97 },
		["The old ones turn their backs to it, and they tell the children not to count."] = { "acb3221aa2e3", 4.62 },
		["The old speaking pipes from the city run for miles, you know. One of them comes out in a vent on a hillside in the snow. I won't say where."] = { "6bddc78512ed", 9.87 },
		["The old woman who taught me had one rule that mattered. Never summon anything when you're tired, when you're lonely, or on an empty stomach."] = { "26c4a323e771", 9.59 },
		["The one I have now looked me up and down on her doorstep. \"No pets,\" she said. I told her it wasn't a pet. She asked me what it was, then."] = { "fb34d3c1889f", 10.42 },
		["The ones that didn't burst kept going all the way to the river. We sat on that hill until dawn, deaf and shaking, drinking what was left."] = { "1283bc6de1fb", 8.8 },
		["The orc Tirion spared stands beside the Warchief in Orgrimmar now. What became of the boy is another story, and a sadder one."] = { "924a70f7b883", 8.99 },
		["The other squires were off breaking straw men to pieces. I drove pegs in the rain, and straightened them when they went in crooked."] = { "6472de0f5d93", 8.15 },
		["The page after that one is stained with blood."] = { "1d2332f573d2", 2.85 },
		["The paladin was Delgren the Purifier, a human who had come to help the Sentinels hunt demons and the dead. He kept his post at Maestra's Post, in Ashenvale."] = { "15768b8fdd7d", 11.21 },
		["The parents were horrified. The children fought over who got to wear it. One of them slept in it."] = { "1f8ded0d9ead", 6.53 },
		["The peace was signed on a clear morning, far away. The rider carrying the news went lame. It took him two days to reach our valley."] = { "841ffa810dbf", 9.17 },
		["The purse held the difference. All of it, down to the copper."] = { "a0e5830ade42", 4.28 },
		["The rain crossed the lake toward me, ripple after ripple, getting closer. When it reached the bank, I held out my hand."] = { "475c926c7dbd", 8.2 },
		["The real line was across the terrace. Everyone in it had watched me the whole time, and not one of them said a word."] = { "4d0cc1d2aef2", 8.15 },
		["The rebuilt rod was laid in the shrine's basin. They say it began to glow, and hum, and every tree on that hillside seemed to lean in and listen."] = { "9ff6a6d552a2", 9.53 },
		["The rest belonged to travelers who'd come through soaked to the bone. She'd lent each of them a dry coat off her pegs, and promised theirs would be ready by morning."] = { "ca1e9d7c05ce", 10 },
		["The roof was their wedding gift to each other. They were nearly finished, they told me. They've been nearly finished for some time."] = { "abfc68734a2a", 7.68 },
		["The roses are real. They're just cold, and they never wilt. The innkeeper has a vase of them going back thirty years. She won't rent that room to a couple."] = { "1d8491f6b197", 10.5 },
		["The rule is that you take one and you leave one, next time you're able. Nobody watches. Nobody keeps count. Nobody can tell you who started it."] = { "81d683964b05", 10.42 },
		["The saddest morning of the month is the one after the Darkmoon Faire leaves."] = { "003c64073c3f", 4.88 },
		["The sailors there tell a story that they were two great friends, a long time ago, who agreed to meet at that spot when the fighting was over."] = { "13cca67c8b6f", 8.33 },
		["The scars are on the left, if you're curious. I have learned to pray very, very slowly."] = { "ebe7b3da97c2", 5.69 },
		["The second scholar said it was backward too. So did the third. I checked every time, and every time I'd gotten it wrong again."] = { "f63feb2332a9", 8.33 },
		["The second time, I lit it without moving at all, turned the flame blue, and made it sing. Come back in a year."] = { "fb230aecfbfc", 8.39 },
		["The seventh had the name of a friend we'd lost in the pass that autumn. Nobody would open it. It's still on a shelf in Kharanos, wrapped."] = { "b39e0431ebf3", 9.4 },
		["The sheep in Arathi won't graze inside those old stone circles. The Circle of East Binding has the sweetest grass for a mile, and not a hoofprint on it."] = { "a7543decca87", 10.32 },
		["The sheet split all around us, and there we were on one slab of ice, drifting, the bear and me, about a spear's length apart."] = { "e530d2882441", 8.46 },
		["The sign has two arms now. I added the second one myself. It hasn't turned since."] = { "7f8e62083dd5", 6.37 },
		["The sky was cloudless when I entered Lethlor Ravine in the Badlands. When shade crossed my back, I was grateful before I thought to look up."] = { "86837cd7c1b4", 8.88 },
		["The smith didn't hesitate. He kicked the crate off the edge. It fell past the forges and landed in the cooling trough with a hiss you could hear from the gates."] = { "4b61939db1e0", 9.95 },
		["The spirits held. We came back to the bank with the boy, his two goats, and a third goat I'm fairly sure belonged to someone else."] = { "d8e12a24d833", 9.06 },
		["The spirits kept them hidden, from the prince and from everyone else. For thousands of years, they lived on air that had agreed to hold them."] = { "e43cefa9f73c", 8.88 },
		["The stag looked at her for a while, head on one side. Then the herd moved, and off it went. It wasn't cruel about it. It just had somewhere to be."] = { "a5e152a14e4f", 10.48 },
		["The stone leaned like a roof. The water in my cup sat perfectly level, right to the brim, as if the cup were standing on a table."] = { "ae741807c616", 9.3 },
		["The sun goes down very slowly in Tanaris. I swear it stopped to look at me. By evening I owed him more than the umbrella was worth."] = { "64c4e2cb41fd", 9.48 },
		["The table was still set for supper. Five bowls, five spoons, and dust on all of it as thick as my thumb."] = { "c53c0b828f2a", 7.68 },
		["The thing I respect about Stonetalon is the names. No one out there is trying to sell you anything."] = { "a559f90d41b5", 6.84 },
		["The thing about a paid job is the preparation. Two weeks, at the least. You have to know someone better than their family does."] = { "79da48c66eeb", 9.06 },
		["The thing you notice is the quiet. No birds at all. Then I saw one, a little brown thing, flying around and around in the empty air above a stump."] = { "00403eeab9a8", 10.66 },
		["The things on the other side know that. They're never in a hurry. They'll wait out your whole life for one bad night, and be so understanding when it comes."] = { "2ed01fdcbe20", 9.82 },
		["The third had a crossbow and all the time in the world. He took aim. Click. The string snapped clean."] = { "efb31cb8ebee", 8.05 },
		["The third time, I kept the pebble and drank the water. It was the sweetest water I've ever had."] = { "662266f3c713", 6.37 },
		["The third year, I looked at that candle for a long time, with the sun on my face. Finally I said, \"What's it for?\" She smiled and put down her pen."] = { "2a5dbd707787", 10.89 },
		["The thirteenth time I stepped in, the rain stopped. Something in the fog had noticed me listening, and it was listening back."] = { "01187441198e", 8.28 },
		["The toll, she said, was one thing she didn't already know. I told her how far it was to the sea. She knew. I told her what iron costs. She knew."] = { "456ec3a26f1c", 10.61 },
		["The tower stair was so narrow only one of us could fight at a time. So we took turns. Each fought as long as they could stand, then stepped back."] = { "daa304a80bbc", 10.08 },
		["The town clerk sat up all night with his records, and found it. Stalvan Mistmantle. A schoolteacher, once, out in Moonbrook. Well liked. A gentle sort, everyone said."] = { "e6accadcbba9", 12.7 },
		["The track ran out over a slag pile, and I flew further than I've ever flown. I still have a scar in the shape of that cart's handle. I got off lightly."] = { "02e179181cda", 10.97 },
		["The tracks went up to the cave, stopped, and then ran the other way. I never told a soul. Well. I'm telling you."] = { "f1be0aefe984", 9.12 },
		["The trader's daughter was still up on the seat holding the reins, because nobody had told her she could let go."] = { "637d43f159c1", 6.43 },
		["The trail led to the Lion's Pride Inn in Goldshire. Stalvan wrote from there, asking to tutor a noble family's children. The courier fled that inn one stormy night in his nightclothes."] = { "b351155f0e5c", 12.98 },
		["The trees in Feralas are bigger than any tower you've seen. You don't appreciate that until there's a yeti behind you and you've got to climb one."] = { "1dfd42315c6f", 8.39 },
		["The wanting changes, and the road doesn't care. But someone who still remembers their first answer hasn't got lost yet."] = { "541516130a13", 8.39 },
		["The way I heard it, it starts at Morgan's Vigil, at the edge of the Burning Steppes. Black dragonkin were massing under the ridge, and Helendis Riverhorn needed them pushed back."] = { "3c31c25b9f7d", 11.08 },
		["The wheels came up out of the mud, and the wagon rolled onto the bank with me still underneath it, plodding along like a slow, wet kodo."] = { "3f018cfae96b", 8.99 },
		["The whole village sat there and wept into their bowls. Which, I'm told, brought it right back to how it used to be."] = { "e05c157dd431", 7.31 },
		["The widow took my hand, and she said I was the first person to speak at any of his funerals. This was his third. He'd done it twice before, to dodge his debts."] = { "2551029eca8f", 10.29 },
		["The wind had it before the first bend. I watched it go, up and out over the sea, getting smaller. So I bought another one. That lasted until lunch."] = { "49d431f616d1", 11.26 },
		["The wind off the north cliffs of Zephras carries voices. Everyone there will tell you it's only the sea caves, and it's nothing, and you shouldn't go there alone."] = { "909da5556413", 9.95 },
		["The wisps answered. Thousands of them, like stars coming down. They poured into the demon until there was nothing left of him."] = { "2a8a19f42839", 8.65 },
		["The woman there led me straight to the door without a word. My notches were all still there. Beside them, she had started cutting her own children's."] = { "c62f9da6bafd", 9.46 },
		["The woodcutter kept his leg. The healer kept the pot. She says I still owe her a new lid."] = { "37738274d4a2", 6.84 },
		["The woodcutters didn't waste a breath. They picked it up, carried it at a run to the edge of the clearing, and set it down facing the other way."] = { "aee20ec8a73b", 9.4 },
		["The year I went, it had a sack of toys bigger than a cart, and it would not let go."] = { "bc55f8e9a343", 6.19 },
		["The year his luck turned, every farm around him failed. His neighbors don't talk to him now. They don't talk about him, either. Not after dark."] = { "28bdaf425cfd", 10.32 },
		["The year the rains failed in Mulgore, there were more mouths in our camp than there was food. Nobody talked about it. There was nothing to say."] = { "509b3381e236", 9.12 },
		["The young races are always in such a hurry. I used to pity them. Now, I think they might have noticed something we forgot."] = { "9075d24cf19e", 7.99 },
		["Their ancestors rose up against him. It cost them dearly, and then they ran."] = { "1f9289ce2508", 5.59 },
		["Their weapons were on the bank, and their colors were folded on top. I knew those colors. They could see mine. All three of us looked at each other through the steam."] = { "772923cfce64", 10.66 },
		["Then I got the legs wrong, and it was going to be a spoon. Now I'd call it a peg. A small peg."] = { "44e073565921", 7.55 },
		["Then I met an old veteran whose blade was smooth as glass. I asked if he'd seen no action. He laughed."] = { "ba2034f69126", 7.55 },
		["Then I saw her hands. She was holding on to her own sleeves so they wouldn't shake. I asked if she wanted to stop. She said yes before I'd finished."] = { "9fc31b7ac3f8", 10.14 },
		["Then I told everyone in earshot it would be a calm afternoon. I said it with great confidence. I had the finger and everything."] = { "c3b17c7dd54a", 8.15 },
		["Then I walked out the front door, looking annoyed. Nobody stops someone who looks annoyed. The watch held the door for me."] = { "09ef1865fa24", 8.7 },
		["Then I was called before the elders on a very serious matter concerning the groves. A solemn occasion. I'd washed and everything."] = { "23cc3733ca48", 8.7 },
		["Then I was clearing out my grandmother's pantry, and at the very back, behind the pickle crocks, I found it. Our mark was on the handle."] = { "f97226e3f944", 9.4 },
		["Then I was on the road near the Plaguewood, a clear gray afternoon, and everything went darker. There was no cloud. No sound. Just a shadow moving over the fields."] = { "69b9030ba945", 11.57 },
		["Then I went abroad and met my first staircase, at an inn. I looked at it. It seemed like a lot of trouble. I stepped off the top, the way you do."] = { "b6ccdd228432", 11.26 },
		["Then Windsor read from his tablets, in the old tongue of dragons. Her disguise fell away, and there stood Onyxia, daughter of Deathwing. The royal guards turned into dragonspawn."] = { "852857069466", 13.06 },
		["Then a farmer laughed so hard at me he fell off his fence. We've been friends ever since."] = { "b61ca2270f1d", 5.64 },
		["Then a fellow came through with a little board on a stick. Rain, one silver. Pay here. He had a roped-off section already."] = { "144fd520360a", 9.64 },
		["Then a guide at Rut'theran Village pointed up, and up, and told me what I already knew and hadn't thought about. All of it sits in a tree."] = { "b5d176d174ad", 9.25 },
		["Then a man came in with an onion. He had a wager on at the fair, and wanted his lucky onion blessed. I told him it doesn't work like that."] = { "85ad6b0bec96", 10.19 },
		["Then a third arrow landed ten paces away, flat along the ground, pointing east. I walked that way until morning, and I found the road."] = { "44f0b31a4fce", 9.25 },
		["Then a whiteout caught me in the Tundrid Hills. Couldn't see my own hands. Couldn't tell up from down."] = { "7d0f88941413", 7.03 },
		["Then a young trader who was passing through dragged a log over the stream one afternoon and walked across, whistling."] = { "dac563eb3206", 7.21 },
		["Then an old friend passed, and their pack came to me. At the bottom, wrapped in a letter, was the eighth card."] = { "430c4ad35cc6", 7.55 },
		["Then came a day on a bad road when I truly needed the earth to hold. I spoke up, and it answered before I'd reached the end of the sentence."] = { "9eca5d9d9931", 8.8 },
		["Then came the dry year. The sweet well gave out by midsummer. The bitter one was full to the brim, because nobody but Odda had touched it."] = { "10105673d4b4", 9.53 },
		["Then came the part nobody plans for. The glide doesn't go back up. We sat very still on what was left of that ledge until his father came with a rope."] = { "fe6e4f6cdcb3", 10.55 },
		["Then he asked my name, and wrote it in the back, in case. I've been meaning to ask him to cross it out."] = { "379a9e0803dd", 6.84 },
		["Then he leaned over, very quietly, and asked if I'd come across a small gray cat."] = { "5fe5b7cff93b", 5.64 },
		["Then he looked out the door at the hills. There's bears out there. Spiders. Crocolisks down by the shore. He looked back at me."] = { "3129e34188e1", 9.46 },
		["Then he looked up, and every chicken in the village was sitting on his roof. Staring. Lesson is this, mon: read the bargain."] = { "cd1ad437d18a", 8.41 },
		["Then he pointed down at the pass. The gnolls don't know it's empty, he said. They only know there's a fire up here, and someone's awake."] = { "5b7c914ae262", 9.12 },
		["Then he sold me the advanced model, for twice the price. I've beaten a lot of armed opponents since. That man is still undefeated."] = { "88a3c743ce14", 9.35 },
		["Then he stopped at one by the ribs and squinted at it for a long time. \"This one,\" he said, \"is a ladle.\""] = { "1750f4c87f3f", 7.68 },
		["Then he went home, to his family's manor north of Darkshire. It's a ruin now. Ghouls stand about in the yard, and a pale little flower grows all around it, that some in Darkshire call Tilloa's tears."] = { "08b609785739", 14.6 },
		["Then it passed. And up it all came, the whole plain, like it had never heard of any storm."] = { "e923bd4a51c9", 7.03 },
		["Then it turned and went back out for more. I stood a while, and then I straightened the stack that had tipped."] = { "db11539c8da6", 7.13 },
		["Then it was his hair. Then his posture. Then a stain on his sleeve. By suppertime he looked splendid."] = { "bb22da4b63d1", 7.26 },
		["Then on the last day, a little one walked straight up and handed him a lumpy gift wrapped in a sock. It was a rock with a face painted on it. A smiling face."] = { "03a5bef3b4b2", 10.74 },
		["Then one morning I was mending a fence, badly, in a bad temper, and the rope wouldn't hold. And something moved my thumb. Over and under, the way she did it."] = { "897e1ce0efb9", 10.55 },
		["Then one morning, a speckled hen walked up to the machine, looked straight at me, and clucked twice. The needle moved. The dial read, \"I know about the eggs.\""] = { "08bc83d47aea", 11.13 },
		["Then one night I happened to be sober. Don't ask why. And I noticed he'd turned off the road, three miles the wrong way."] = { "5bde12ea6d02", 8.65 },
		["Then one night raiders came up the canyon, thirty of them. They got within a bowshot of us, stopped to listen, and turned back."] = { "75c6b3b333cd", 8.52 },
		["Then one wet morning they found him in his own millrace. The constable asked every house, and every house told him the same. Slick boards, poor man."] = { "94afffd6142a", 10.37 },
		["Then she made me untie it. That took twenty minutes, and I broke a nail. She watched the whole time and said nothing."] = { "15a47945397c", 8.1 },
		["Then she pointed at a cloud and said, there, that one's a dragon. And it was, a little."] = { "7afb71b58d57", 6.74 },
		["Then she sat smiling at it for a while, and said it was just nice to finish something. I stayed and watched her finish the rest of that corner."] = { "ecfddf47f8ac", 8.62 },
		["Then she set it in the wall facing inward, carving and all, where no one would ever see it again."] = { "b886a2a7a40b", 6.3 },
		["Then she thanked it too. You can't be too careful."] = { "597d178a45f4", 3.74 },
		["Then she turned her big head and looked right at me. Not angry. Just waiting. I understood that this part wasn't mine to see, and I walked away."] = { "7b15c7e9b32c", 9.87 },
		["Then the Burning Legion came back, and its general, Archimonde, climbed the mountain to take the tree for himself."] = { "65ad6c1dfc79", 7.08 },
		["Then the cloud moved on toward Thunder Bluff. And my patch of shade stayed exactly where it was, right on top of me."] = { "4c1d48e3907c", 7.92 },
		["Then the dead got up. Some of them came back to the chapel and stood outside, as if waiting to be called."] = { "8e89622a6161", 6.84 },
		["Then the first of the naga rose up, with her scales catching my firelight. I grabbed a log out of my fire and swung it, and I ran up the beach, with water at my heels."] = { "4f783b6a4884", 11.34 },
		["Then the keeper died. The gravedigger dug him the finest hole anyone had ever seen, square as a table, and wouldn't take a coin for it. He dropped the old slate in after the box."] = { "6ab4c1cf7e9d", 12.17 },
		["Then the reeds parted, and a crocolisk the length of a rowboat came sliding through them, in no hurry at all."] = { "78e2d2aed9cd", 7.03 },
		["Then the ripples stopped, and the lake went flat as glass. I sat there a long while waiting for a second drop. I'm still not sure why."] = { "51f002fb0e76", 9.77 },
		["Then the river takes you, and you come up coughing on the far bank. The only thing behind you is one very wet gnoll, as surprised as you are."] = { "f72009687eea", 9.77 },
		["Then the wind picked up, the sort of wind that comes in beats, and a black dragon landed on the other end of the rock."] = { "4d4f3d9ba9e4", 7.03 },
		["Then there was a fee for the plank, and a fee for asking about the fee. So I stepped back to argue and fell into the harbor."] = { "8c9dcd0bbf06", 8.33 },
		["Then they followed me back to the inn. Every evening since, a kobold turns up at my door with a rock, and waits for a candle."] = { "d4fcb3bb1690", 8.99 },
		["Then they gave me some nuts, patted me on the head, and they sent me on my way. I've been treated worse by people who had asked to meet me."] = { "190e6b3c4152", 8.65 },
		["There are old terraces in Azshara, all broken marble, tipped every which way. I sat on one to rest and set my cup down on the slope."] = { "f2071d6ff205", 9.59 },
		["There are trees I've watched grow from seed. I've outlived some of them. That does something to you."] = { "dfda94dbd677", 6.48 },
		["There is a stretch I can't remember. Between dying and waking up as myself. Some of us had months of it, and some of us years."] = { "bad48090a0f8", 8.75 },
		["There she was with a candle stub, sewing the buttons back on their coats. So they'd look right, going home. She looked up and said, you saw nothing."] = { "74fe6a2480ac", 10.74 },
		["There they stopped. I've left an offering at every mountain shrine I've passed since."] = { "d36b2b3bd8d4", 5.77 },
		["There was a camp of trappers in the old woods, taking more than the land could bear. Cages stacked high. I walked in at dusk and asked them politely to stop."] = { "2d86014b09a8", 11.02 },
		["There was a crew ahead of it and rock on every side. The only way to the shutoff was along the outside, while the thing was running, at about a brisk jog."] = { "d73ccbd1abdd", 10.06 },
		["There was a ferryman on a wide brown river who tied a knot in his rope for every soul he carried across."] = { "02deb4be02d4", 6.37 },
		["There was a fish seller nearby with an empty barrel. I didn't ask. I tipped it out, fish and all, and rolled it into the water."] = { "f9d14d439c3f", 9.06 },
		["There was a footbridge in Ashenvale that needed mending. So our elders gathered to discuss the matter, with all the care it deserved."] = { "26078eda05f0", 8.65 },
		["There was a girl up there, minding goats. I asked her if she knew what this hill was called."] = { "2d717bc8f5ce", 6.06 },
		["There was a goose outside Goldshire that held the east road for six years. Nobody gave it leave. It simply decided."] = { "096fa6772867", 8.15 },
		["There was a locked courtyard I passed every evening, where someone practiced the flute. They always stumbled on the same note."] = { "fc9d440c61dd", 7.92 },
		["There was a note with it, in his awful handwriting. \"Big for its age.\""] = { "a671bd45aaa1", 5.07 },
		["There was a rope bridge in the jungle, mon, rotten through, and an old herb woman halfway across when the ropes on her end started to go."] = { "9c483ce49f11", 9.77 },
		["There was a sentinel who came each evening and sat on the left end of one bench, always the left end, with the right end empty."] = { "980af46390e3", 8.33 },
		["There was a signpost at a crossroads that somebody turned every night to point at a stand of brambles. Every morning I turned it back, and every night it turned again."] = { "5be29d2e1f3b", 11.08 },
		["There was a smith on the lift with me, and a crate of fresh blades between us. Far too heavy. We were going to come down fast."] = { "6cf1c484ac00", 7.92 },
		["There was a winter when the grain ran short, and the miller's scale ran shorter. Everyone knew. He was the only miller we had."] = { "e46503b98bd8", 8.93 },
		["There was a young soldier on a cot, a hard night, nothing more to do. I started to say it, and he looked me right in the eye and said, \"Don't.\""] = { "f1c68d7df6b9", 9.87 },
		["There was an old keeper who lit a lantern on a hill every night, long after the road below had washed away."] = { "11e68334dbae", 6.97 },
		["There was an old one out past our camp digging a well in the driest ground you ever saw. Every day, for years. We used to go and watch for a laugh."] = { "faebdd45a78c", 10.42 },
		["There was an old sow bear on my side of the mountain, whom I'd known for years. That last winter she was all bones, and I could see how it would go."] = { "15d6fbced6f5", 10 },
		["There was no catching it. Nobody is that strong, whatever my uncle says. But there was a post, and I had the end of a rope."] = { "87a5b08dc71a", 8.8 },
		["There was no way to turn it off. It wasn't in the design. I asked him later and he said, why would you want to?"] = { "a6f725502ed0", 8.1 },
		["There was nobody there, of course. I asked a priestess about it. She smiled and said the well only shows you who is with you. She didn't say when."] = { "8c80ed5ff906", 9.64 },
		["There was one water barrel and twelve of us. Somebody started shouting orders. Nobody listened, because everybody was running."] = { "176c5fb28452", 8.88 },
		["There was something I never got around to saying to someone. They're a long way off now, and it's a very long story why. So one morning I climbed up to the highest cliff."] = { "401eb6671e27", 10.92 },
		["There wasn't time to explain. I grabbed the back of her collar and pulled her clean off her stool, sketchbook and all."] = { "ccc0f3e7be41", 7.31 },
		["There were eleven of us holding that bridge, and we'd been told help would come by dusk."] = { "4421b4516b37", 5.77 },
		["There were eleven of us on my bench, in the old city. The day it happened, we'd run short of parts, and it was my turn to go up to stores."] = { "029b17fbb446", 8.93 },
		["There were people out on the high cliff paths, leaning on the wind the way we all do. A good many of them, on a fine clear morning. And then every banner on the isle went limp."] = { "c3564ffca5b1", 11.55 },
		["There were questions of wood. Questions of tradition. A very moving speech on the nature of crossing. This went on for about seventy years."] = { "0682c6978a96", 10.29 },
		["There were raiders behind me in the Burning Steppes, and nowhere to hide on all that scorched ground. So I climbed the Pillar of Ash. Hand over hand, with cinders in my eyes."] = { "a29ef4964341", 11.81 },
		["There were seven of us. We walked over and stood around it in a circle, and not one of us would be the first to look down."] = { "7b61e8d623d5", 7.63 },
		["There were some children eating there, and a woman I didn't know, staring up at me. I said I was very sorry. I said I had the wrong door."] = { "87563b879fce", 9.17 },
		["There's a bat handler in the Undercity I'll always remember. Rotten old coat, half a jaw, and a whole roost of big bats that came down whenever he clicked his tongue."] = { "6572abe727a4", 10.84 },
		["There's a blessing the water spirits sometimes allow, if you ask with respect. It lets you walk on the surface. It doesn't make it any less frightening."] = { "076ca8235c4d", 9.59 },
		["There's a book in the old temple library where I studied. At the back, on a short chain, with no name on its spine. Novices dare each other to touch it."] = { "c32cb017cc38", 10.55 },
		["There's a boy in Stormwind Keep who wears a crown. He's about ten years old. His name is Anduin, and his father is King Varian Wrynn."] = { "ca93f0fb3c57", 9.72 },
		["There's a card table in a certain tavern that always gets dealt one hand too many. Three players, four hands. You deal the chair in. Everybody does."] = { "94521abe91ff", 10.08 },
		["There's a clause on page forty. It's beautifully written. The other side was very confident that no one reads page forty."] = { "4e9f00852b3e", 7.92 },
		["There's a fellow in Booty Bay who takes bets on anything. I once wagered I could guess a stranger's trade from their boots."] = { "9d3a024e79c1", 7.86 },
		["There's a ferry in the Riverglades that charges by weight. The ferryman keeps a scale on the dock, and he's very proud of it."] = { "eef0495c5d63", 7.63 },
		["There's a gnome in Ironforge who'll sell you, for one silver, the combination to a vault under Tinker Town. Left, left, right, sneeze."] = { "345df2c05afb", 10.14 },
		["There's a goblin in Gadgetzan who runs a matchmaking service. One gold to meet the love of your life, guaranteed or your money back."] = { "513876ba6087", 8.8 },
		["There's a hill in the Hillsbrad Foothills, on the road between the two towns, that gets fought over so often you'd think it was made of gold."] = { "71088fe4f660", 8.7 },
		["There's a hunter I met near the Farstrider Lodge with a wall full of trophies. Antlers, tusks, a boar's head as big as a cart wheel."] = { "089251713260", 9.46 },
		["There's a lake I won't fish. They flooded a valley to make it, and the chapel bell went down with the town."] = { "c2774fa291a5", 6.9 },
		["There's a little brown bird that's been following me for three towns now. Every morning it lands on my knee and steals my breakfast."] = { "a752ceaad175", 8.15 },
		["There's a long staircase in the ruins of Shen'dralas with one step missing, about halfway up. Everyone who climbs it steps over the gap without thinking."] = { "92ba2fe5018d", 10.08 },
		["There's a place called Seradane in the Hinterlands. Green mist in the trees, and it's the most restful place you've ever seen. They warn you not to nap there."] = { "8d2b361de03c", 11.13 },
		["There's a practice post in the yard where I trained. Plain oak, older than anyone there."] = { "038a17054ea6", 6.19 },
		["There's a prayer that makes a body light as a feather. Most of us use it to cross water and impress people. I had about one breath to say it properly."] = { "236e74868f59", 9.64 },
		["There's a row of white stones along that cliff. I know how many there are. Please don't ask me."] = { "c5b1290c4580", 6.9 },
		["There's a scholar at Marshal's Refuge who pulls old bones out of the tar pits in Un'Goro. He labels every one with great care, and keeps a ledger thick as a door."] = { "cddff0bfa149", 10.92 },
		["There's a seller in the Undercity whose jaw doesn't work quite right anymore. I asked his name. He said it, and I didn't catch it, so I asked again."] = { "df8c658aba17", 9.77 },
		["There's a shelter of Light we're taught to call on when things go badly. Nothing touches you. It lasts about as long as one slow prayer."] = { "468d4cdb5bce", 8.99 },
		["There's a stretch of road in Ashenvale with lumber carts on one side and graves on the other. It's a pretty road, otherwise. Everything there is."] = { "7e4ae87d3103", 9.64 },
		["There's a thing they ask you when you come out of Felwood, the ones who know. They don't ask how long you were in there. They ask if you liked it."] = { "aa99c3aac44d", 9.3 },
		["There's a trick every hunter learns. You fall down, very convincingly, and you stay down. It works on most things that can't count."] = { "54dfe01236aa", 9.3 },
		["There's an alchemist in Undercity who sells love potions by the canals. Two silver a vial. People swear by them."] = { "ac29dd50f9e5", 8.39 },
		["There's an empty post at the end of the row. Nobody will tell you who it's for. They just look at the sky, and check their own knots."] = { "9f1df11a3ff5", 8.52 },
		["There's an empty stretch of road I walked alone, weeks of nothing, and somebody had been scratching notes on the milestones."] = { "4ad463c78cbc", 7.81 },
		["There's an hour before dawn when even the crickets stop. Have you ever noticed? Everything out there holds very still."] = { "582e008c72cc", 8.33 },
		["There's an old fellow who fishes Crystal Lake every morning. Same spot on the bank. I sat with him one day and never saw a bite."] = { "bc3697cc60e9", 8.39 },
		["There's an old gravedigger who works Raven Hill Cemetery, and you'll know what I mean when I say the dead there don't always stay put."] = { "cd1ad2727b87", 7.99 },
		["There's an old guard on the wall at Razor Hill who counts the riders in at dusk. Out loud, every one, until the last of them is through the gate."] = { "ee2152105c7c", 10.37 },
		["There's an old hand at Cenarion Hold, in Silithus, who walks out every morning with a sack. I took him for a scavenger, and I suppose he is one."] = { "68675bc793b1", 10.55 },
		["There's an old seer in Darkshire, Madame Eva. Years back, she woke from a dream with one name on her lips. Stalvan. Death was coming for her granddaughter, and it had a name."] = { "03603d5bc8fe", 12.28 },
		["There's an owl in the woods of Teldrassil that kept asking me who. I was sitting on a log near the Oracle Glade and it would not stop."] = { "acc6c0a43025", 8.93 },
		["There's no running from a rockfall. There's only being small and being covered. I had a big shield and a lot of practice hiding behind it."] = { "c43be301e90c", 9.53 },
		["There's nothing anyone can do from the cliff. You only stand there. It's very quiet, and you can see a very long way."] = { "9a32754774f7", 8.75 },
		["There's one rule on the cliffs of Zephras Isle, and they'll tell you the first day. If the wind ever drops, you get away from the edge. Fast. It doesn't drop for long."] = { "ac799352b9ff", 11.44 },
		["There's supposed to be a whole city at the bottom of the Bay of Storms, off Azshara, sunk so long ago that nobody can tell you the year. Fishers there don't talk about it."] = { "5aa7b7709796", 10.89 },
		["There's talk that one of the coins in the fountain in Stormwind's Trade District isn't a coin at all. Turn it over, and it's a key."] = { "a654e0f83cff", 8.23 },
		["There. It's gone now. Still, I'd stay near the fire until morning."] = { "9c8a0cb80c98", 5.59 },
		["These are deer trails, the guide said. Deer have been walking these hills for a very long time, and they never go straight."] = { "c3e7c55fd221", 7.55 },
		["They ask me back every year now. The parents have stopped saying friendly. Now they just say smaller."] = { "377278139ca0", 6.71 },
		["They both showed up. They both got there early, as friends do. Neither one wanted to be the first to leave, so they stayed."] = { "12451830a3fd", 8.93 },
		["They broke him out together. Windsor got his armor back, opened the cells, and fought his way up out of the Depths. Then he made for Stormwind, and told everyone to bring friends."] = { "8c8b998480cd", 11.91 },
		["They broke our gate an hour before dawn. Rotten hinges, and we'd been complaining about them all year."] = { "60119bf47d85", 7.16 },
		["They call it Zephras. Some of them were given skysight there, so they could see the spirits and speak with them."] = { "745923839261", 6.84 },
		["They came down with proof that Athrikus Narassin was dead, and the Cult of the Dark Strand scattered to the winds. The demons would be back one day, Balthule said. But not soon."] = { "13b636f465bb", 12.51 },
		["They came one at a time, then two at once, then over each other. Behind me the captain kept shouting that the carts were nearly clear, and that I must not give way."] = { "fcab1d9854a8", 11.02 },
		["They come up close behind whoever's listening hardest. They only want to hear. They like a story as much as anyone."] = { "5d0f4333fdfd", 8.41 },
		["They don't fit. They wouldn't fit two of my fingers. They are, however, the only thing I own that anyone has ever given to me, the second time around."] = { "3aae35526f48", 9.82 },
		["They fed me for three days, and when I left, an old woman handed me a new map."] = { "0d1c400ffdda", 5.41 },
		["They found Teronis on a little island in Lake Falathim. Murlocs had got to him. His journal was still in his pack, and the murlocs had carried off the gem."] = { "8c7884b60e06", 10.5 },
		["They found him in a canyon in Ashenvale. Thrall was struck down, and Grom faced the demon alone."] = { "4c9297fac1b8", 7.81 },
		["They found what was left in the spring, out among the red rocks. There was nothing to bring home but a broken spear and a name."] = { "089f43216f25", 8.28 },
		["They hauled us both out with ropes. Two days later we fought again on dry ground, and I saw him across the line. I went and found somebody else."] = { "b8f332b56216", 10.32 },
		["They held it exactly the way you'd hold a child. Careful of the head. I didn't say a word."] = { "cfd54a1a3b9a", 6.43 },
		["They laughed. One of them offered me a job. So I thanked them for their time and walked out. And when it was dark, I went back as a cat."] = { "bfee37a49625", 10.08 },
		["They made that pact. The spirits lifted that land up out of the world and into Skywall, where no ship could follow."] = { "492ab24cf170", 8.15 },
		["They make a blood sausage in Thelsamar that would make you weep. I've had it in three different bad moods and it cured all of them."] = { "847dd8040e3d", 8.15 },
		["They planted a new tree, Teldrassil, but it doesn't keep them young. Now they grow old. Slowly, but they do."] = { "31ce38ceb4c3", 8.46 },
		["They ran for it, and they forgot about me. Then that storm came down on us, and I couldn't breathe or see. I put my face against that post and held on with my teeth."] = { "cb7d37afb917", 10.61 },
		["They ran off coughing, blind as moles, and left a trail of white all the way to their camp. The militia at Sentinel Hill followed it the next morning."] = { "d46904fae25c", 9.67 },
		["They rode straight into the river and kept going. She spent the rest of the day apologizing to the bees."] = { "488f7ffde643", 6.79 },
		["They said there was a third. The shelter doesn't come twice that quickly. So I tied a wet sack round my head and went back in on just the words."] = { "1e3aa77ea789", 9.46 },
		["They sailed straight over me and out through the window. The crowd went wild. I've been a swordmaster in that town ever since."] = { "e01b230fd889", 8.41 },
		["They say Cold Hearth Manor in Tirisfal got its name honestly. I didn't believe that, so I walked in out of the drizzle one evening."] = { "6bdb4cd71042", 8.65 },
		["They say if you kiss someone in the middle of the Deeprun Tram, right where it's darkest, you'll be together until the tram stops running."] = { "6379f5579cec", 8.46 },
		["They say on Zephras Isle that the wind carries whatever you tell it. It never stops blowing up there, high above the sea. You've got to shout just to hear yourself."] = { "7c5afbaa9de8", 10.29 },
		["They say one of the grunts at the gates of Orgrimmar has been asleep on his feet for six years. Nobody has the nerve to wake him."] = { "d5d39707bf98", 7.81 },
		["They say that kodos walk to Desolace from all over the world when their time comes. You'll know the Kodo Graveyard when you see it. Bones like the ruins of a city."] = { "5c7e96bc34c2", 10.79 },
		["They say that time runs funny out near the Caverns of Time, in Tanaris. Sand slides uphill. You'll set something down and find it there before you got to it."] = { "9fd66f8e54c0", 10.97 },
		["They say that whole kingdom sold itself, one bargain at a time, and thought it was getting a good price."] = { "da6cc2197551", 6.79 },
		["They say the Great Forge in Ironforge burns hotter whenever a certain blacksmith walks past a certain miner. The apprentices have started timing it."] = { "9c9ba6ad5536", 9.59 },
		["They say the bells of Stromgarde still ring at midnight, up in the Arathi Highlands. Nobody's hung a bell in those ruins for years."] = { "9d49c3f2c894", 8.8 },
		["They say the boy asks every morning if there's any news from the sea. They say the answer is always the same. \"Not yet, Your Majesty.\""] = { "c24a2252517f", 8.99 },
		["They say the children outside Ironforge built a snowman one Winter Veil, a fine one with coal eyes, out past the gates. The next morning it was a little closer to the road."] = { "cb00e63b378f", 12.28 },
		["They say the innkeeper in Goldshire keeps a second ledger, just for travelers who set their hearthstone there and swear they've no idea why they keep coming back."] = { "4321915f1fd9", 9.72 },
		["They say the wisps in Ashenvale linger near people who are grieving. I don't know. A little light came out over the water and settled by my knee."] = { "4eee72abbc4c", 9.95 },
		["They say there's a lake in Ashenvale where couples go to swim by moonlight, and whoever comes out first has to carry both sets of clothes home."] = { "cf524ac288a6", 8.7 },
		["They say there's a temple sunk under the Pool of Tears, in the heart of the Swamp of Sorrows. On a still evening, you'll see bubbles coming up."] = { "4ba64c3f3c46", 9.4 },
		["They say there's an old couple in Menethil Harbor, married fifty-nine years, and he still comes to her door every evening with flowers, like he's asking for the first time."] = { "2c319feeac6d", 11.39 },
		["They send for us when someone's dying. They hope for a miracle, and you arrive in all that armor, looking like one."] = { "b72c5210138f", 7.99 },
		["They smoked, all right. Black smoke, thick as wool. But I'll tell you something: nothing in Duskwood came near my camp all week."] = { "d901077178c3", 9.4 },
		["They started when I left camp and they matched my stride, step for step. No one in sight for miles."] = { "2153cc4dc5d8", 7.03 },
		["They took ships at Eldre'narr on the coast and sailed west, with the prince's fleet behind them, out past the edge of the maps."] = { "d5919c4476f2", 8.05 },
		["They went on ahead toward my camp, at an easy pace. Whoever it was knew where they were going."] = { "fe9d60e6eb3c", 6.79 },
		["They went to every tent, and stopped at each one, and there was a gift by every door. Seven gifts. There were six of us."] = { "8d81e52f9a94", 8.8 },
		["They'd had it from their mother, who'd had it from a traveler who stayed one night. Nobody knew any more than that."] = { "61d49297aa8f", 6.48 },
		["They're all in chains down there, he said, and they've got no way to tell anyone anything. But sometimes the beat stumbles. Then it picks back up, one hammer short."] = { "f89e2511317e", 11.08 },
		["They're still on his ore carts. Never let go once. Best thing I've ever made by accident, and I've made a lot of things by accident."] = { "5ee4ef14dc33", 9.06 },
		["They've been insulting each other for two years now. Everyone knows. The whole barracks is waiting for the wedding."] = { "86399f3c440b", 7.44 },
		["Thieves, soldiers, a man with a goose in his coat. It didn't matter. Bowl first."] = { "899b54334726", 7.08 },
		["Thing is, there are thousands of coins in there. They say the key knows who's looking. Look for it for the wrong reasons, and it's only copper."] = { "a30eeccb4613", 9.04 },
		["Think of it. Something that big, swung by something that mattered that much. And all that's left of them now is a good place for moss."] = { "ee32c1dd8601", 8.99 },
		["Thirty feet out from the wall, as it turned out. In the direction I'd been facing. Nothing underneath me but a long evening and a moat."] = { "f9861a580b7a", 8.93 },
		["Thirty years I've worked by that rule, and I have never once been hunted. Very wise. I taught it to two apprentices."] = { "ae0ddc3c2f95", 8.52 },
		["This child walked right up to me and took a good, long look at my hands. Then, very seriously, said, \"You're cold.\""] = { "e569787f9e53", 8.46 },
		["This fell from the branch above the place where I was born. I picked it up the morning I left Ashenvale, meaning to plant it somewhere."] = { "1a6679b846a4", 8.52 },
		["This hand has closed wounds. And this one has opened them, when it was needed. People prefer to hear about the first."] = { "f0fba5284a8d", 8.15 },
		["This is no small office. The last keeper held the spoon for eleven years."] = { "24a71c9e41d6", 5.22 },
		["This is only so I can get a better shot at it. Don't tell anyone."] = { "3b29058aec36", 4.62 },
		["This went on for a week. It became a sort of correspondence. I'm a very stubborn sleeper."] = { "817ecb5a2024", 6.79 },
		["This will sound strange. An old woman stopped me on the road days ago and pressed this on me. Said to give it to someone who'd sit at my fire."] = { "d1e8a7224417", 9.46 },
		["Those seeds are tall trees now. I still can't make a fist on a cold morning without thinking of them."] = { "0f81cb3ab2e7", 6.66 },
		["Those were named after. Which means that somebody walked out there afterward, by themselves, with a pen and a sheet of paper. And looked at it all."] = { "cad4925c993f", 10.48 },
		["Three bandits caught me on a bridge in the fog, with boat hooks and a net. They didn't care what I was. They wanted my boots."] = { "8785ea0019b8", 9.04 },
		["Three children, two adults and a goat, all of us under one shield. It rang like a bell for a long minute, and my arm went numb to the shoulder."] = { "15fcf7c7dcf5", 10.74 },
		["Three days it kept that up. It watched me eat, it watched me sleep. I started apologizing out loud. I started explaining my childhood."] = { "295f1ab76af8", 10.5 },
		["Three days later I walked out of that valley alone. The crows never even looked up at me."] = { "6ccd950fd16e", 6.06 },
		["Three days of hills, and we never used it once. Not a cliff, not a river. I complained about that rope at every rest."] = { "23d051c44425", 9.35 },
		["Three days of silence left. Honestly, the silence is worse."] = { "2ba657233ce1", 4.88 },
		["Three hundred of us followed that noise home. He stood out there blowing till sunrise, with arrows falling all around him."] = { "d17579a738a4", 8.41 },
		["Three men in red masks came in, looking for anything worth taking, and started up the ladder."] = { "58cde7c297ba", 6.56 },
		["Three nights in, walking back from Raven Hill, I heard my name. It came from off the road, and it was my mother's voice."] = { "f008af657f6c", 9.12 },
		["Three nights running I went up the drainpipe, only to look through the shutters. Dust on everything, and a table laid for one, with a fresh-cut loaf."] = { "47e8cbf94528", 10.08 },
		["Three of them scrubbed me, with brushes that I think were meant for bark. They changed the water twice. It came out a color I won't describe."] = { "56d4f91e4bfc", 9.04 },
		["Three rams, one sled, forty kegs, and a frozen lake that had been perfectly solid all the way up until we reached the middle of it."] = { "6ad96736c984", 8.65 },
		["Three villages. She went through each one screaming and ringing, with the trees going over behind her."] = { "d69fda9b9ff8", 6.66 },
		["Three weeks I sat with that turtle. I brought it berries. I spoke to it softly. I told it things about my family."] = { "c1b3570dad75", 8.33 },
		["Three weeks later and half a world away, I was standing in a harbor, and I saw a sailor wearing my hat. I asked him where he'd got it. It came down out of a clear sky, he said."] = { "0163d66ccfba", 12.04 },
		["Three years later a fisherman landed it. Took six people. Everyone came down to the water to see."] = { "85aef7161186", 7.31 },
		["Through a snowdrift. Under a cart. Past a very surprised troll. I held on. I don't know why. By then it was a matter of pride."] = { "ea427308d801", 10.37 },
		["Thumb over the rim, just like that. It used to drive me mad. I told her she'd burn herself."] = { "dd80fd89b037", 6.9 },
		["Tilloa had given her tutor a flower that summer. A small kindness, the kind you give a teacher you like. He wrote about it as if she'd made him a promise."] = { "3ea16d89ee3b", 9.9 },
		["Tirion Fordring was once a lord of Lordaeron and a paladin of the Silver Hand. One day, near Hearthglen, he found an old orc hiding in a ruined watchtower."] = { "06693946d144", 11.15 },
		["Tirion came too late to save him, but not too late to answer for him. The old man fell on Isillien like a storm, and the Inquisitor could not stand against him."] = { "f65e7294a0e6", 10.74 },
		["To be fair, if you climb the rock on a clear day, you can see the Southfury River. He never said it was close."] = { "68d8462d4637", 7.86 },
		["To hear people tell it, everybody's first beast was some great snarling thing. Mine was a turtle. I chose it because I thought it couldn't get away."] = { "05377bfaa8aa", 10.19 },
		["To start me off, my teacher sat me in front of a door with a big iron lock, handed me a bent pin, and said I'd eat when it opened."] = { "077c0a353dc6", 8.33 },
		["Took me a year to work up the nerve to ask the old master about it. Who made such a thing, and why keep it?"] = { "b44131385135", 7.21 },
		["Took me years to see that's true of nearly everybody. The angry one, the laughing one, the one who says they're fine."] = { "235dddafb581", 7.99 },
		["Top speed was excellent. I wrote that down first."] = { "13c7e23d38fe", 3.79 },
		["Transformation is taught in the third year, in pairs, in a locked yard. Nobody could explain why the yard was locked. They said it was tradition."] = { "b7ca6617d0b3", 10 },
		["Truth is, I looked up from my work one morning and couldn't remember a single thing that had happened that year."] = { "999dde02a876", 6.56 },
		["Try finding a room when you smell faintly of sulfur. Landlords suddenly remember a nephew who needs the place."] = { "95575d2fbccb", 7.73 },
		["Turnips. Forty carts of turnips."] = { "16e17ed4bf3e", 3.21 },
		["Turns out it's only manners. You're meant to say \"fine.\" So I practiced. I've said \"fine\" with a spear through my shoulder."] = { "94f06f755655", 8.15 },
		["Twelve years of study. I know the nine principles and the true shape of cold. So, naturally, a baron hired me to chill the wine at his feast."] = { "6c595a160be9", 10.66 },
		["Twenty guests in their finery, spoons frozen halfway. I brushed myself off, took a glass from the nearest hand, and raised it to the host."] = { "7caa3993a221", 10.32 },
		["Twenty years she'd been traveling. I asked her how she ate. She said there's a pot on in every village, and nobody turns away a guest who brought their own spoon."] = { "4a13983a4454", 10.08 },
		["Two days later it slid right into Marshal's Refuge and stopped by the cook fire. Better sense of direction than any guide I've ever paid. I bought it a drink."] = { "3382c7df2e23", 10.66 },
		["Two days, uphill. It had gone a long way in that condition, and we saw every place it had stopped to rest."] = { "d6f8910deb73", 7.86 },
		["Two farmers in Hillsbrad asked me to settle where the fence between them should go. Each one invited me to supper first, to discuss it."] = { "6b70581774f3", 8.8 },
		["Two hours later I had told that bird about my father, the debt, and the time at the river. I had never told anybody about the river."] = { "f5e7db4260a6", 9.04 },
		["Two hours later I was face down in a pigsty, missing a boot, with that bird standing on my back."] = { "aa682e43abb3", 6.84 },
		["Two hours later a little girl had forty eggs. I had one, and it was a rock somebody painted."] = { "4a1524508e9c", 6.97 },
		["Two hours later we were all in the tavern, soaked to the beard, buying each other drinks."] = { "1346dca53d1a", 6.01 },
		["Two more gems found, two more Highborne spirits let go. With them gone, Athrikus had lost most of his strength. Delgren said it was time to finish this."] = { "a7548b565940", 11.55 },
		["Two of them were up there arguing about whether the other could do anything right. I could hear every word. So could the nails, I expect."] = { "145ae912f044", 8.46 },
		["Two ogres ran me down in a ravine once. Big ones, with clubs, and my companion was off chasing a rabbit, as companions do."] = { "243b8d5827d3", 9.4 },
		["Two ribs and a collarbone. I'd have done far better with the water. So look first, I tell the young ones. They never listen. I didn't, either."] = { "c8589300c759", 11.34 },
		["Two ship captains in Ratchet spent eleven years trying to win the same harbor mistress. Flowers, poems, duels. One of them named a ship after her."] = { "731a9569746e", 10.89 },
		["Two sisters ran the cookhouse in the village where I grew up, and neither trusted the other with the salt."] = { "87dec5555198", 6.32 },
		["Two thousand people watched that bird scratch itself. Then the horns went, and I ran, screaming, into the worst day of my life."] = { "e12fd1323ee2", 9.59 },
		["Two turns around the post, and I sat down on the rope with all my weight. It burned through my palms like a brand."] = { "8f08fd90b491", 7.81 },
		["Tyrande Whisperwind leads the night elves now, from Darnassus. Ten thousand years ago, she loved a druid named Malfurion Stormrage."] = { "d483f9640161", 9.82 },
		["Under the board was a baker's note, three coppers owing, and never paid. She paid the baker's grandson that morning. That was the last of it."] = { "94d77dd360a6", 10.92 },
		["Up in the hills above Shael'dryn's glade there's a shrine most folk walk right past. The path spirals up the mountainside, and you'd never see it from below."] = { "0750a71ea8ee", 10.08 },
		["Up it came with a white pebble in it. The same one, near as I could tell. I threw it farther."] = { "48335e267c41", 7.39 },
		["Uther fell to his own student. His tomb stands in these hills, and paladins still come to it."] = { "67bc81d32142", 6.79 },
		["Uther himself took the Light from him, and they sent him into exile. He had just enough time to say goodbye to his young son, Taelan."] = { "3b4a4acc20d9", 8.8 },
		["Uther the Lightbringer taught a young prince named Arthas everything he knew about the Light."] = { "7d0d5f2b9e37", 5.41 },
		["Varian was a boy in the keep that night. Stormwind fell that year, and he was carried north with the refugees, to grow up in someone else's kingdom."] = { "f184690438e8", 9.95 },
		["Vines through the canvas. Vines through the boots. A tree root thick as my wrist, right through the middle of a bedroll."] = { "d12ce8c747f8", 7.81 },
		["Violet and humming, a heart in a stone,"] = { "3042c4d81df8", 3.32 },
		["Waiting for a ferry in the Riverglades, the ferryman handed me his passenger list to check while he tied up. My name was on it, halfway down."] = { "5b3f189b4ec3", 10.08 },
		["Walk through the Irontree Woods in Felwood, and you'll notice that the trees all lean a bit toward the road. And they lean more if you talk."] = { "02f4455b6075", 8.65 },
		["Walking into Goldshire after dark, I passed the lamplighter on his round. I counted his lamps as I went, the way you do when the road is long."] = { "84061ef96490", 9.72 },
		["Want to hear something strange? Come a little closer."] = { "bc08ba1abf66", 3.6 },
		["Warm, it is. It stays till morning. I don't look. I've never once looked."] = { "5c628ee96692", 6.79 },
		["Water costs more than ale in Gadgetzan. Everyone knows that. So you can imagine the fuss the one afternoon I was there when it rained."] = { "9571cbe6cdc0", 9.06 },
		["Water up to my chin, and there it was. A pebble wedged in the main cog. One pebble. I hooked it out with a hairpin."] = { "0e02787aca89", 9.25 },
		["Water would blow the place apart. Every dwarf knows that before they know their letters. What you want is sand, and the sand was across the room."] = { "5e3948f8a3b2", 10.19 },
		["We all drink from it now. Whatever you're digging, understand that you may not be the one who gets the water. Dig anyway."] = { "88b86aa3a893", 8.41 },
		["We all lined up, gagging on it. Odda drank hers down without blinking, and said she'd been practicing."] = { "63a1561e17dc", 7.68 },
		["We beat out the flames while the owl sat on a branch above us, watching, very interested. By the time help came, it was only smoke."] = { "999f030134a1", 9.46 },
		["We broke through into an old gallery once, deep down, sealed off since before anyone's records begin. The air tasted of a thousand years."] = { "0bc46bc6bc85", 9.82 },
		["We built it from nothing, with our own hands, and no one gave it to us. That is worth more than green."] = { "f214982430f6", 6.97 },
		["We camped once on an old field, no one living knew whose. Grass grew strangely there, in long straight rows. We were too tired to care."] = { "982697d1e3a9", 10.37 },
		["We carried the rest of the wood without talking. I didn't grumble about the weight again."] = { "946d1e299b11", 5.59 },
		["We did find him. We only had to wait. The spell wears off, you see. I'm told the shepherd has not been the same since."] = { "106ea5385673", 8.62 },
		["We didn't stay to hear it. We left the tents."] = { "9b67a190b6a3", 3.03 },
		["We dug for two more days. Nobody suggested otherwise, and nobody said why."] = { "43f954856975", 6.11 },
		["We figured it had been there ten years, maybe twenty. Then we found the journal, and read the last page, and checked the date."] = { "bff2284fa298", 8.2 },
		["We fought half the night. In the end the sack tore, and toys rained down the whole mountain."] = { "cf265463e984", 6.32 },
		["We fought three days for a hill. Nineteen of my company are still on it. I went back, a long time after. I'm not sure what I expected."] = { "693c34ae2c40", 10.32 },
		["We found a camp in the deep jungle of Stranglethorn. Tents, cook pot, bedrolls, and every bit of it grown through with green."] = { "1640dd7f561c", 9.17 },
		["We found the herd. That one came right up to me and smelled my hand. Then we brought the child they'd left at home, and stood her at the edge of the trees."] = { "d90190e25ed1", 9.77 },
		["We found the lad two days on, alive. He wouldn't speak of it, and he never sat with his back to a fire again."] = { "3dbcec2d574c", 8.15 },
		["We got all nine out. The guests stood around half dressed in the snow, cheering. Nobody ever did find their own coat."] = { "fd8bd75c5b20", 8.8 },
		["We got it out just as the water reached the bed. The peddler checked his goods, and found the only thing ruined was a crate of umbrellas."] = { "05d0f2d49b76", 8.93 },
		["We had a sergeant so frightening that crows went around her. Never a kind word in four years. I'd have sooner faced the enemy."] = { "dfb97905cc96", 8.2 },
		["We had nine of us out on the flats and no cover. I roped us together, shouting, and then I could no longer hear my own voice. Then the light went out."] = { "c77ae49338b7", 9.77 },
		["We had two wagons of ale on the road near Three Corners when the gnolls came down out of the rocks, howling, on both sides."] = { "1ab38e3de5ae", 8.39 },
		["We have a word for a day when the wind dies all at once. We don't say it aloud, not even to explain it. I was nine, the only time I saw one."] = { "e899e6f13b2c", 10.29 },
		["We heard them. Three knocks, every hour, while we dug. On the second day they came slower. On the third day we stopped hearing them."] = { "3ff20b94cbd0", 9.3 },
		["We hit the far shore with black water at the runners and a single keg aboard. All three rams lived, and I gave each of them a mug of it."] = { "1b4c1e3308aa", 8.93 },
		["We hunted it for three days. I'm proud to say I led them nowhere near it."] = { "336d30dd3af5", 4.75 },
		["We jammed it in the gateway and someone threw in a torch. A wall of fire, right in their faces, and it burned until the morning relief came."] = { "3a11c600b31f", 9.25 },
		["We joke a lot, my people. You've noticed. We joke about nearly everything except Gnomeregan."] = { "c687333c911b", 6.9 },
		["We keep vigil the night before we take the oath. Alone, kneeling, on cold stone until sunrise."] = { "b37dbc362530", 7.78 },
		["We left the old island at night, with no lights on the water. I was small. I remember being told there were twelve boats, and to be very quiet."] = { "b5a3bcd6e0f0", 10.37 },
		["We looked at each other for a good long while. Then we both ran. Opposite ways."] = { "9c96aae9ed31", 5.96 },
		["We looked at each other for two hours. When the slab bumped the far shore, it got off first. Neither of us ever mentioned it again."] = { "83b466935f5b", 9.48 },
		["We lost him when I was fifteen. And at dusk, some evenings, we still heard it. Mother would get up without a word and put the kettle on."] = { "fc9b9ce22a03", 8.65 },
		["We lost the farm when I was grown. Years later I passed that way, and I knocked, and I couldn't even say why."] = { "f7f1e0f3e980", 7.37 },
		["We made camp near the Wailing Caverns one night, and yes, it wails. It's the wind in the rock, they tell you. It's only the wind."] = { "2e7736a6fbbb", 9.12 },
		["We marched into a valley one clear morning with no enemy in sight. Every tree was black with them. Quiet. Waiting."] = { "0e3ffd750281", 9.35 },
		["We moved it down to shoulder height. A lot of tired, hurt people have beaten that drum since."] = { "838040eb35e1", 6.24 },
		["We parted at a crossroads twenty years ago, with a handshake and a promise to write."] = { "6d4c0912c28a", 5.72 },
		["We passed forty-one safety measures in my time. Measure forty-two was to stop storing the examples in the meeting room."] = { "e5b0ed1ac821", 8.28 },
		["We pushed the whole herd onto the hot ash and stood in it, coughing. The great fire came, found nothing there to eat, and parted around us. That grass grew back thicker."] = { "adf590e99286", 12.51 },
		["We put it out with half a barrel to spare. Afterward we argued about who'd been in charge. Nobody had. That's why it worked."] = { "78bb1e2b78f9", 8.8 },
		["We reached the Hold with one mouthful left. We drank it at the gate, together. Then we drank a great deal more."] = { "752f2057c4ba", 7.92 },
		["We said good night. Nothing got through that door all winter, and plenty tried. We marched out at the thaw."] = { "bb42e73dfa74", 8.28 },
		["We sat in a hollow where she could see solid ground all round. After a while, she pointed at a cloud and asked what it meant."] = { "253417a531fa", 8.1 },
		["We sat on that dock and hummed it together till the light went. Then we shook hands and never met again."] = { "d8cde091d0a4", 7.13 },
		["We shouted for the driver. Nobody could hear a thing over the market, and the cart kept grinding forward."] = { "4a029b129d5c", 6.9 },
		["We spend ten years studying the fundamental forces of the cosmos, and can make bread that tastes like a wet Tuesday."] = { "e265fec9ea79", 7.73 },
		["We split a pie instead. Best company I had all winter."] = { "1634b7281aeb", 4.62 },
		["We take turns carrying food out to her. She takes it, and thanks us, and she asks if there's any word of her relief."] = { "45cd000c76b0", 7.58 },
		["We take vows about the truth. Everyone knows it, so everyone wants my opinion on their baby, their poetry, and their cooking."] = { "3c17445a00f0", 8.33 },
		["We talked about that dog till near dawn. He knew a lot of stories. He was laughing about a butcher's apron when he stopped."] = { "4e284635bc4f", 7.81 },
		["We tell her soon. Four hundred years, we have been telling her soon. My people have far too long to learn how cruel a small word can be."] = { "3d735a61ed90", 10 },
		["We took a mouthful each, every hour, on the hour, no matter how much we wanted more. We walked by the stars, and slept through the worst of the heat."] = { "534995152376", 10.48 },
		["We tried to kill each other for a while. Then we traded insults. By sundown he was telling me about his sister's cheese."] = { "dc629a85c512", 7.99 },
		["We waited there until a voice asked whether supper was ready. It came from the empty air between us. He answered before I could stop him."] = { "bfea4388c4fe", 8.8 },
		["We walled that gallery up the same day, and we did it quickly. It's a good, thick wall. The shift that works near it says somebody's been chipping at the other side."] = { "9de2db9c8398", 10.71 },
		["We were at the bottom for most of an hour, bowing to each other. People started stopping to watch."] = { "c47aae6065da", 6.79 },
		["We were crossing Mulgore with the whole caravan when the lead kodo sat down in the road. When a kodo sits, the world waits."] = { "a76bc67850f9", 8.8 },
		["We were pouring bronze in a big forge in Ironforge when the chain on the crucible snapped, and a whole lip of molten metal came sliding toward the apprentices."] = { "e7127b9b3519", 10.5 },
		["We were raising the first longhouse of a new camp in Durotar when the ropes on the ridge beam gave. A great timber, swinging straight for the cook fire and the young ones around it."] = { "d141f12cdb64", 11.08 },
		["We were routed, scattered in the dark, every one of us sure we were the last alive."] = { "6dbb2fda496a", 5.72 },
		["We wintered once in an abandoned keep, with a stand of somebody's plate still in the hall. Good steel, never rusted. Nobody would take it."] = { "8e42828d74cd", 9.46 },
		["We wrote each one down in the chapel book. Mothers, smiths, children. It filled three books."] = { "36b81d1466d3", 7.58 },
		["We're a short-lived people, and stubborn. We bury our dead, and then we go plant something."] = { "8e470d522e6c", 6.66 },
		["We're taught that mending and ending come from one source. It's a hard thing to learn, and harder to forget."] = { "e700d1cba5ca", 6.84 },
		["We've not spoken to the neighbors in two hundred years over that ladle. There have been fistfights. There was a song."] = { "e6d669868767", 7.68 },
		["Weeks later, coming back through, I set the cloth on her counter. She knew it before she knew my face. Then she sat down hard and laughed."] = { "7a00d5d51c6b", 9.82 },
		["Well, I'm a kind soul. I explained it twice. She kept asking which numbers were the good ones."] = { "8bc6535e799a", 7.13 },
		["Well, I've got manners. I did it back. It seemed pleased. We went on like that for some time, and I thought, this is why I left home."] = { "c2b0c2c39ff1", 10.97 },
		["Well, four of them. The fifth bowl had been wiped clean."] = { "d6112608beeb", 4.62 },
		["Well, that's my last one tonight. Goodnight, all."] = { "1c98a7f0428e", 3.92 },
		["Went to a barber about a bad tooth. He sat me down, got a knee on my chest, and out it came. Best relief of my life, for about one breath."] = { "1886d03bf19e", 10.08 },
		["Westfall's full of empty farms, and some of the old harvest machines never got told to stop."] = { "34b6d2d31a40", 6.06 },
		["What I wasn't ready for was the complaints. The fire's too small. Why must it carry the bag? It has a bad back. Since when? Since always."] = { "02b1d99bf215", 10.61 },
		["What came up out of that floor was very big, in a bad temper. It went through the men at the door like a cart through a hedge. Then it turned around."] = { "29ed5f7a1a32", 9.67 },
		["What did the bucket say to the well? Nothing. It's a bucket."] = { "162918eeed50", 4.34 },
		["Whatever side you're on, I think the dead would rather we shared the harvest than argued over it."] = { "882dcdfed88f", 5.72 },
		["Whatever that post was built to watch for has been gone a long, long time. Her company is gone too. She was told to hold until relieved."] = { "ea6265607b5a", 10.14 },
		["Whatever you've heard about the Dark Portal, in the Blasted Lands, it's bigger than that. I've met people who went to see it. They don't talk about it for long."] = { "9bb340c68106", 10.32 },
		["Whatever's slowest, he said. And I noticed he was measuring me, just a little, so I took two more for the road and walked briskly."] = { "935d859ea2a3", 8.57 },
		["When I brought him back, he told the matron I was the wisest person in the whole world."] = { "c9cfbfd2b604", 5.28 },
		["When I could speak, I asked what the spicy one was like. Everyone within earshot stopped eating, and the cook slowly shook her head."] = { "889180b3b43b", 8.88 },
		["When I finally got to the front, the clerk asked if my friend would be needing anything too."] = { "ba75dd60206f", 5.07 },
		["When I finally had it loose, she said a knot you can't undo is only half a knot. Then she tied it again, the right way, and it came apart with one pull."] = { "3701be679d64", 10.24 },
		["When I finally reached a camp, it circled once and flew off after a fellow heading the other way. I'll be honest. It hurt my feelings."] = { "f01be2689907", 8.46 },
		["When I finally went back, my sister had saved every scrap of news about me. Mostly wrong. She kept it anyway, in a tin."] = { "f941bfa9bc56", 9.35 },
		["When I first left the isle, I couldn't get used to how everyone here looks straight ahead. All day. Never up."] = { "128bc36f0677", 7.81 },
		["When I got back to the inn, there was a ram in my bed. It had paid for the room, as far as the innkeeper could tell."] = { "3351c9e4b83f", 7.37 },
		["When I left Dun Morogh, my friends packed me a jar of snow as a joke. Something to remember the cold by, they said, when I went soft."] = { "de1255611c14", 8.83 },
		["When I looked up, there it was. Lit. Grinning. And still warm when I touched it."] = { "c121c6b64192", 5.72 },
		["When I told her, she wrapped the whole meal in a clean cloth and wouldn't take a copper for it. I thought she was being kind about my nerves."] = { "a7e53747d029", 9.04 },
		["When I turned around, the ogres had stopped at the edge. The big one looked at the gap, looked at me, gave a nod, and sent a small one to go and fetch a ladder."] = { "daa9c4806540", 10.66 },
		["When I visited Darnassus, I took to walking in the Temple Gardens at moonrise. It's the quietest place I've ever stood in."] = { "568ec57c3970", 7.99 },
		["When I was fourteen, I knew everything. I called it waste. And so I got up early, in secret, and I brought that row in myself. I was very proud."] = { "beb946d022d2", 10.74 },
		["When I was given my hammer, my teacher said I could use it for one thing that whole first year: tent pegs."] = { "a5204b248fc0", 6.74 },
		["When I was new at this, I told every dying soul the same thing. \"You'll be fine. Rest now. You'll be fine.\" I thought it was kind."] = { "8f166437c15d", 9.67 },
		["When I was small, my mother walked four miles to the well before every dawn, and four miles back through the dust with the skins on her shoulders."] = { "5ba286523ddf", 9.46 },
		["When I was small, my uncle made an offering to the loa, for good fishing. A fine, fat chicken."] = { "a7f4c0acd635", 6.97 },
		["When I went back to tell him, he gave me a fourth. You don't have to learn everything yourself. There isn't enough time, and there isn't enough of you."] = { "f426b70457ff", 9.17 },
		["When I've brought something down, I drag it around in a wide circle and leave it upwind of him. Then I go and stand a little way off."] = { "595f191994f9", 8.75 },
		["When Stormwind fell, Lothar is the one who got its people out, by ship, north to Lordaeron. He brought the young prince Varian with them."] = { "6e44b5a15c14", 9.82 },
		["When Tirion saw it again, they say the old paladin nearly fell where he stood, and wept like his heart was breaking open."] = { "8bf2ae9ad155", 7.78 },
		["When Varian was a boy, his father was King Llane. In the First War, with the orcs at the walls, someone Llane trusted killed him in his own keep."] = { "5e2849daec16", 10.19 },
		["When a tunnel comes down, ye put your ear to the rock and ye listen for three knocks. It means someone's alive back there."] = { "e2cb2d5cf8fc", 8.1 },
		["When at last I stood at her door and spoke it, she looked at me kindly, and with great puzzlement. She had no memory of it at all."] = { "8bdf9f22b1e8", 8.93 },
		["When he died we opened the little box he kept under his bed. Inside, wrapped in his good cloth, was a dried fish."] = { "b26acd38903a", 8.23 },
		["When he got too old to walk, he took to sitting by the fire with it in his lap. I thought he was counting."] = { "b1623e68b29f", 6.71 },
		["When he reeled in to go home, I saw there was no hook on the line. Hadn't been for years, he said."] = { "5ef647301fde", 6.74 },
		["When it died, she gave it a burial at sea, and it was the only time I ever saw her cry. Twenty years that crab had worked for her, under six names."] = { "b6f131dfe3d9", 10.37 },
		["When it finally died, the whole village came out for the burial. Mostly to be sure."] = { "1442a8980576", 6.01 },
		["When it passed, there was no camp. No tents, no bandits, only clean new dunes. And me, tied to the only post still standing. It took me till noon to get loose."] = { "e7f80a5c955c", 12.51 },
		["When it stopped, the goat got out first and walked off without a word. The tinkers hammered the dents out of my shield that night, for free."] = { "880d18752d6d", 9.59 },
		["When it was finally brought to him, Delgren broke it open. Out came a ghost. A Highborne named Sargath, from Ameth'Aran, ten thousand years gone."] = { "3f8eb9ee9684", 11.31 },
		["When it was over, I couldn't open my hand. They had to pry the shield off. I asked what was in those carts that was worth all that."] = { "a9fd83b9a704", 8.7 },
		["When it was staring straight at his bedroom window, he dragged it out and burned it. We all helped. We all felt quite silly."] = { "8349edb136ab", 8.15 },
		["When my teacher knew her time was close, she gave me an acorn and walked me up to a bare patch on a dry slope. Very poor soil. Not a place I'd have chosen."] = { "2c2002b1ca64", 11.44 },
		["When one of ours sets off into the wide world, someone in the family ties a knot in the tall grass at the edge of camp. It's a small thing."] = { "10fb27b448b4", 9.72 },
		["When orcs stormed into Stratholme, he broke the orc out in the chaos. At his trial, his own wife begged him to lie. He told the truth."] = { "6af047323963", 10.42 },
		["When she could speak, the first thing she said was that the carving on the broken side was much better than the front. She drew that instead."] = { "e463ca6278fb", 8.2 },
		["When she died, a boy found me with a purse and a little book. In the book was every job, every date, and the true price against what she'd paid."] = { "b90197b454a7", 9.72 },
		["When she let go, I had her ring in my palm. I don't remember taking it. I stood there with my whole past going cold in my stomach."] = { "54c0f7874a66", 9.4 },
		["When someone came back over, he untied their knot. By the time I met him, that rope filled half the boat."] = { "6b0e73813725", 7.39 },
		["When the Legion came back, she was the one who went down into the barrow dens and woke him. They fought side by side at Hyjal, and they won."] = { "3df87b662be6", 9.25 },
		["When the Scourge marched on Quel'Thalas, she already knew who led it. Prince Arthas, the paladin who came home wrong."] = { "558eb2d6127c", 8.93 },
		["When the brood was beaten back, Helendis sealed a letter. The Blackrock orcs were not their own masters, it said. The black dragonflight was pulling their strings."] = { "8127bae6028a", 11.44 },
		["When the dust settled, I crawled out and stood up, and I was the only one standing. They carried me around the room and named me the undefeated champion. It's a title I still hold."] = { "255c76c3be52", 11.76 },
		["When the footlocker was opened, something pale rose out of it and wailed. A girl, or what was left of one. Nobody knew yet who she was."] = { "f7fad628d6ad", 10.66 },
		["When the guards asked him to describe the thief, he said it must have been a professional. Tall. Scarred. Very menacing."] = { "5853d589c8e8", 8.28 },
		["When the light faded, the rod was whole again. Raene was proud. Teronis's work had outlived him. But nobody quite knew what the thing actually did."] = { "d245c5e7b88f", 10.84 },
		["When the morning came there were nine boats. Nobody said anything, and nobody looked back."] = { "e3d6d59721ad", 5.72 },
		["When the orcs came to Kalimdor, the Warsong went into Ashenvale to cut timber, and Cenarius himself came to drive them out."] = { "08c0925141fe", 7.99 },
		["When they finally cut me free, the regulars took up a collection. There's now a small plaque on that door. I think of it as my only monument."] = { "fad7247a35b9", 9.25 },
		["When they finally moved on, they left the satchel on the ground beside me. It was heavy, and they were tired of carrying it."] = { "7e4eb2cd3bd2", 7.44 },
		["When we buried her, I danced until my feet bled, mon. I sang so loud I had no voice for a week."] = { "a2b217d5ceda", 7.39 },
		["When we finally rolled it off, there was a shield underneath, dented and black from the fire. He cleaned the rim with his sleeve."] = { "f6a98d4f36d5", 8.8 },
		["When we were building our camp in Durotar, I was given the job of hanging the gathering drum. I put it on the highest beam, so it would carry."] = { "f7ac44d19bc2", 9.3 },
		["When you are as large as my people are, you spend your childhood breaking things. Fences. Cups. Small friends, nearly."] = { "3e93537bbd91", 9.35 },
		["When you think you're being followed, you walk a big slow loop and cut your own trail. Anyone in my trade will tell you that."] = { "be0fa964debb", 7.37 },
		["When you visit Aerie Peak, the gryphons look you over first. One of them walked up, sniffed my coat, and sneezed. The handler winced."] = { "30043034057c", 9.9 },
		["When your people live as long as mine, you stop saying long ago. You say, when I was younger."] = { "6f77ded26b0c", 7.03 },
		["Where I grew up, if you wanted to get to a lower place, you stepped off the edge of the higher place. It never struck any of us as complicated."] = { "112d67553148", 9.3 },
		["Where I grew up, nobody asks that unless they're checking how badly you're hurt, and whether to finish the job."] = { "09021a902957", 6.61 },
		["Where's the pea, I asked. He grinned and said, what pea? That's a different game. Two silver."] = { "0858e0060988", 7.26 },
		["Wherever I go, I pay for a room at the inn, and then I climb out the window and sleep on the roof. I can't settle beneath a ceiling. It sits on my chest."] = { "629fdc2ba638", 10.84 },
		["While they were shoving each other, my companion came back with the rabbit, saw the ogres, dropped it, and bit the bigger one somewhere tender."] = { "92a40b569d18", 8.57 },
		["Who wanted it first. Who wanted it poured over the neck. Who'd wave him off twice and then take it."] = { "f903f3695466", 6.53 },
		["Whoever left it is long gone and will never know. I expect you've got a stack or two of your own to be thankful for."] = { "b8a9fa41a4cd", 7.86 },
		["Whoever she sent found him alive, tucked in the trees west of the tower. He hadn't dared leave. Warlocks had moved in, and he was afraid he'd miss whatever they did next."] = { "d5b5619c6476", 11.86 },
		["Whoever went in found him waiting. Not a man anymore. Dead, and still standing, and still angry. When they carried his ring back to Madame Eva, she only nodded. She had already seen it."] = { "86189dc8a77b", 13.71 },
		["Why is grass green. Why do murlocs smell. Why don't you have a house. Why is your sword chipped."] = { "685029300c72", 7.81 },
		["Windsor was alive in a cell down there. But a crumpled note from Emperor Dagran Thaurissan bragged that General Angerforge and Golem Lord Argelmach were breaking Windsor's secret notes."] = { "6c7f98195bb0", 11.73 },
		["Winter Veil Eve, we were camped in the snow outside Ironforge, six tents and one small fire. In the morning, there were tracks."] = { "00217c8ec76e", 9.17 },
		["Winter Veil in the city. I was minding my own business with a mug of cocoa when the first snowball hit."] = { "6215179bacfd", 7.37 },
		["Winter Veil, a crowded inn, and some joker had hung mistletoe over the only free seat."] = { "5481650bf97e", 6.48 },
		["With his last breath Windsor pointed Bolvar to his medallion. It had kept the Highlord's mind in her grip, and it lay shattered now. A piece of it was a piece of Onyxia herself."] = { "bba06807f2c7", 12.46 },
		["With that blood the shard became the Drakefire Amulet, and no ward in the Wyrmbog could keep its bearer out. Onyxia waits there still. But Windsor tore off her mask first, in front of all of Stormwind."] = { "20342e7588bb", 14.18 },
		["Word around Westfall is that the farmer with the best harvest every year has never planted a seed. Nobody's ever seen him in his fields. Not once."] = { "356561ffae28", 9.9 },
		["Word in Orgrimmar is that two grunts on opposite watches leave notes for each other in the same loose stone in the wall. Rude notes. Very rude."] = { "1cc2b9792248", 10.19 },
		["Word is the keeper of the Westfall lighthouse flashes the lamp twice every night at the same hour, though there's never a ship on the water."] = { "b315fe6b2cc0", 8.75 },
		["Word is there's a table at the inn in Booty Bay where the chair is always pulled out and the mug is always full. Nobody's paid for it in forty years."] = { "2bbb2cb2669a", 9.67 },
		["Word is, if you dance alone at midnight on the high rises of Thunder Bluff, someone will step out of the dark and dance with you. They never say a word."] = { "b6e2210ea59d", 10.08 },
		["Would I steal bread for a starving friend? Would I tell a king a hard truth? That sort of thing."] = { "d554e9d128cf", 6.53 },
		["Wouldn't take another step. I left it my dinner, and it didn't look. It turned and trotted back, to wait for the next one."] = { "afa1025fc2d6", 8.8 },
		["Years later, a long way from anywhere, I heard a stranger humming it while mending a net. Same turn at the end and everything."] = { "8213c3207342", 8.65 },
		["Years on, a shield edge broke my sword arm in the first minute of a long fight. I shifted my grip and carried on. I don't remember deciding to."] = { "d7d0b6fb8d40", 10.55 },
		["Yes, I can conjure food. No, it isn't good. Everyone's always so impressed until they've eaten it."] = { "7389d385ccf4", 7.31 },
		["You always thank it. It kept my totems, all of them, and my left boot. I'd call that fair."] = { "a2a24069711d", 7.21 },
		["You can row out to Fenris Isle from the Silverpine shore, if you've a mind to. I'd heard there was an old village out there and thought there might be something worth taking."] = { "2c4ce819ac67", 10.29 },
		["You can't ask it to stop. I tried, and the wind told everyone I'd asked."] = { "80030e72c0be", 5.64 },
		["You could see the map inside it, floating there, all the little roads. And then it started to move off, slowly, but with real confidence."] = { "5539a0bcef81", 10.06 },
		["You didn't hear this from me, but folk in Lakeshire say their magistrate is twins. One does mornings, one does afternoons. That's why he never remembers lunch."] = { "ab95bd2a9f26", 11.31 },
		["You don't command a river. But once, with a whole camp packing behind me and the hills pouring rain, I went down to the bank to ask it for an hour."] = { "d4bbcc320594", 9.9 },
		["You don't know what silence is until you've stood in Darnassus. It's all moonlight and whispers. People there can spend a whole afternoon on a pause."] = { "477b17034ba3", 9.9 },
		["You don't name them. That's the first rule anyone teaches you, and it's a good one. It's how you go on using them."] = { "817edeb6511c", 7.13 },
		["You don't pick a lock on a rough road. You pick it between bumps. I counted the ruts, and every time the wheels ran smooth, I got one pin."] = { "1e95b13999d9", 9.59 },
		["You get about four seconds to think about your education. I flung frost at the water with everything I had. It worked beautifully. It froze solid."] = { "4a1b9b2eaf12", 10.19 },
		["You know the Thandol Span, up where the Arathi Highlands meet the Wetlands? The bridge has gaps in it you could lose a house in. No one jumps those."] = { "1468413d8d09", 10.42 },
		["You know what it was, and I knew too. I walked toward it anyway, because at that point you need something to walk toward."] = { "d93587263b97", 7.68 },
		["You learn a house before you touch it. This one was a dead widow's place, shuttered up, empty since the funeral. Good silver, I'd been told."] = { "496ada2cf486", 10.14 },
		["You learn how a thing moves when you've worn its shape. Where the weight goes. How a deer's ears turn before its head does."] = { "f4d30dbb802f", 8.33 },
		["You run, naturally. Gnolls don't give up. It's a matter of pride."] = { "90bb82464721", 5.59 },
		["You see it coming from a long way off in Durotar. A red wall from the ground to the top of the sky, and it moves faster than a running wolf."] = { "d6466f212f0c", 9.53 },
		["You see these little cairns all along the roads in Dun Morogh. Everyone who passes adds a stone. I always thought it was just a nice custom."] = { "cb2a3d6bdc8f", 9.46 },
		["You walk in, the ale is middling, the price is fair, and the keeper tells you to shut the door, were you raised in a barn."] = { "90e008b42131", 8.41 },
		["You walk out to the field, and it's just grass again, flattened in big circles where the tents stood."] = { "44d12985e3ff", 7.03 },
		["You walk through the Eastern Plaguelands for days. Black trees, poison streams, and things moving that shouldn't be. You stop expecting anything else."] = { "417cace55f43", 10.29 },
		["You want to know the bravest thing I ever saw? A cook. A camp cook named Bram."] = { "af7ff0bb9242", 6.32 },
		["You'd think it would be wicked. Most of it is only honest. It explains what a mind is, and where it's fastened on."] = { "34a3c1b8b09b", 7.44 },
		["You'd think they'd be heavy. I did, the first time. A life, in a little stone, small enough to lose down a drain. It weighs nothing at all."] = { "ee1dbba5b629", 12.17 },
		["You'd think, speaking to spirits as I do, that I'd have spoken with my grandmother by now. Everyone assumes so."] = { "92532abcf83f", 7.5 },
		["You'll hear about the thing that floats over the Eastern Plaguelands. A great dark shape up in the sky, with no business being up there. I thought that was only talk."] = { "dbf9840f2d43", 11.31 },
		["You'll never hear a song about a day like this. Nobody buys a round for it."] = { "c6f33f3d58da", 5.22 },
		["You'll notice a hum, walking out in the sands of Silithus. It comes up through your feet. You'd take it for the wind, and I did too. It's a low sort of thrum."] = { "81a90f5b240e", 10.42 },
		["You'll pass the burnt-out remains of the Shady Rest Inn, on the road through Dustwallow Marsh. It's just black beams and a chimney. Nobody stops."] = { "9c0deed7828d", 10.42 },
		["You've heard about the sharks there. A crew fished me out before I'd finished screaming, and I was very grateful, for about a minute."] = { "37cfea8d86dd", 7.99 },
		["You've never truly seen the dark until you've walked Teldrassil's roots with only the moon above you."] = { "46e3f8e7a90a", 5.77 },
		["You've seen the notices. Greatfather Winter is visiting, courtesy of Smokywood Pastures. I always wondered what that meant. Who pays Greatfather Winter?"] = { "84baaf288fd7", 10.29 },
		["You've seen what's left of Stromgarde. Ogres in the keep, thieves in the square, and rain coming through what used to be the roof."] = { "e2e64c2fb85b", 8.83 },
		["Young soldiers like to cut a notch for every fight they've won. I did too, for a while."] = { "13a8e98eba81", 6.11 },
		["a fisherman pays you a copper for me. What am I?"] = { "f68db4816382", 3.97 },
		["a mage lets me fall so they won't fall to their death. What am I?"] = { "6b414c1ef04a", 4.86 },
		["and I weep as I burn till there's nothing ahead. What am I?"] = { "669528ac5ca2", 4.21 },
		["and alchemists tremble to find me alone. What am I?"] = { "25f51ed3534a", 3.92 },
		["but after the hunt, I take something away. What am I?"] = { "80519d5e4d67", 4.39 },
		["but take one more hit, and I fall to the ground. What am I?"] = { "4f975f05862e", 4.94 },
		["free for the thirsty who wander about. What am I?"] = { "b99efb6111d5", 3.92 },
		["the first thing you'll mine when you're new to the town. What am I?"] = { "258754dc89db", 4.65 },
		["the gold, and then I'll carry you over the ground. What am I?"] = { "18e37fbeb2c7", 4.88 },
		["the whole city asks if they've heard about you. What am I?"] = { "937c98ce8c32", 3.81 },
		["then rise with my help on a borrowed breath. What am I?"] = { "3309bc080756", 4.44 },
		["yet hold me and wait, and I'll bring you back home. What am I?"] = { "9c84a11928d8", 4.94 },
	},
	emote = {

	},
}
